// Dueling and Two-Weapon Fighting (0.36.0, 1.97).
{
  const equipment = JSON.parse(shippedCatalogSources.get("catalogs/equipment.json")).entries;
  const damage = (id) => equipment.find((entry) => entry.id === id).item.attack.damage;
  assert.deepEqual([damage("longsword").sheetBonus, damage("longsword").oneHanded], [{ derived: "dueling" }, true]);
  // A greatsword carries it too: it takes two hands, so the Engine never counts it one-handed.
  assert.equal(damage("greatsword").oneHanded, true);
  assert.deepEqual(
    damage("longbow").sheetBonus,
    { itemStat: { stat: "archery_damage", from: "worn", pick: "max" } },
    "a longbow reads Bracers of Archery, not Dueling",
  );
  assert.deepEqual(parsedAsset.combat.offHand.fullWhen, { listSum: { list: "features", column: "offhand_ability" } });
  // Weapons held are counted by the melee and ranged tags, so a staff (gear or a magic staff) counts.
  const magic = JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries;
  for (const item of [...equipment, ...magic].map((entry) => entry.item).filter((item) => item?.attack))
    assert.ok(
      (item.tags ?? []).filter((tag) => tag === "melee" || tag === "ranged").length === 1,
      "every weapon is tagged melee or ranged, never both",
    );
  const styles = parsedAsset.catalogs.find((each) => each.id === "fighting_styles").entries;
  const row = (id) => styles.find((style) => style.id === id).rows[0].values;
  const sheet = (lists) =>
    evaluateSheet(parsedAsset, { abilities: {}, skills: {}, saves: {}, bonuses: {}, fields: {}, lists });
  assert.equal(row("two-weapon-fighting").offhand_ability, 1);
  assert.equal(sheet({ features: [] }).derived("dueling"), 0);
  assert.throws(
    () =>
      assertRulesetSheetHooks(
        { ...shippedManifest, capabilityApi: { major: 1, minor: 96 } },
        parsedAsset,
        shippedCatalogSources,
      ),
    /read the sheet for damage and must declare capability API 1\.97/u,
  );
}
