// Exhaustion's fourth and sixth levels, and creatures immune to it (0.45.0, 1.115).
{
  const creatures = JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries;
  const levels = parsedAsset.combat.levels.filter((level) => level.track === "exhaustion");
  assert.deepEqual(
    levels.map((level) => level.at),
    [1, 2, 3, 4, 5, 6],
  );
  assert.deepEqual(levels.find((level) => level.at === 4).modifiers, [{ to: "health-max", times: 0.5 }]);
  assert.equal(levels.find((level) => level.at === 6).defeats, true);
  const immune = creatures.filter((entry) => entry.creature.conditionImmunities?.includes("exhaustion"));
  assert.ok(immune.length >= 20, `undead and constructs immune to exhaustion: ${immune.length}`);
  for (const id of ["skeleton", "iron-golem", "lich"]) {
    assert.ok(
      immune.some((entry) => entry.id === id),
      `${id} is immune to exhaustion`,
    );
  }
  for (const entry of creatures) {
    assert.ok(
      !(entry.creature.traits ?? []).some((trait) => /^Immune to exhaustion$/u.test(trait.name)),
      `${entry.id} has no stand-in trait`,
    );
  }
  for (const [minor, message] of [[114, /must declare capability API 1\.(?:1[1-9]\d|20[0-4]) or newer/u]]) {
    assert.throws(
      () => assertRulesetCombat({ ...shippedManifest, capabilityApi: { major: 1, minor } }, parsedAsset),
      message,
    );
  }
}
