// Grappler in place of an improvement (0.33.0, 1.94).
{
  const features = JSON.parse(shippedCatalogSources.get("catalogs/features.json")).entries;
  const grapplers = features.filter((entry) => /grappler/u.test(entry.id));
  assert.equal(grapplers.length, 64, "one on its own and one per improvement");
  const alone = features.find((entry) => entry.id === "grappler");
  assert.deepEqual(alone.filters, { kind: "feat" });
  assert.match(alone.rows[0].values.text, /^Prerequisite: Strength 13 or higher\./u);
  // Its Strength 13 is checked (0.40.0, 1.99 offeredWhen): every Grappler, alone or in an improvement's place.
  for (const grappler of grapplers) assert.deepEqual(grappler.offeredWhen, { derived: "mc_str_13" }, grappler.id);
  const strength = (str) =>
    evaluateSheet(parsedAsset, {
      abilities: { str, dex: 10, con: 10, int: 10, wis: 10, cha: 10 },
      skills: {},
      saves: {},
      bonuses: {},
      fields: {},
      lists: {},
    }).derived("mc_str_13");
  assert.equal(strength(12), 0, "not with Strength 12");
  assert.equal(strength(13), 1);
  for (const asi of features.filter((entry) => /ability-score-improvement/u.test(entry.id))) {
    const twin = features.find((entry) => entry.exclusive === asi.exclusive && entry.id !== asi.id);
    assert.ok(twin && /grappler/u.test(twin.id), `${asi.id} shares its group with a Grappler`);
    assert.equal(twin.filters.level, asi.filters.level);
  }
  assert.throws(
    () =>
      assertRulesetSheetHooks(
        { ...shippedManifest, capabilityApi: { major: 1, minor: 93 } },
        parsedAsset,
        shippedCatalogSources,
      ),
    /has catalog entries exclusive of each other and must declare capability API 1\.94/u,
  );
}
