// Cantrips and spells to pick (0.28.0, 1.90): the builder's counts off the class tables.
{
  const sheet = (fields, abilities = {}) =>
    evaluateSheet(parsedAsset, { abilities, skills: {}, saves: {}, bonuses: {}, fields, lists: {} });
  const picks = (fields, abilities) => [
    sheet(fields, abilities).derived("builder_cantrips"),
    sheet(fields, abilities).derived("builder_spells"),
  ];
  // A wizard's spells go in the Spellbook step since 0.376.0, counted by wizard_spellbook.
  assert.deepEqual(picks({ level_wizard: 1 }), [3, 0], "a 1st-level wizard: 3 cantrips, none at the Spells step");
  assert.deepEqual(picks({ level_wizard: 5 }), [4, 0]);
  assert.deepEqual(
    [1, 5].map((level) => sheet({ level_wizard: level }).derived("wizard_spellbook")),
    [6, 14],
    "6 in the spellbook, 14 at 5th level",
  );
  assert.deepEqual(picks({ level_bard: 1 }), [2, 4]);
  assert.deepEqual(picks({ level_cleric: 1 }, { wis: 16 }), [3, 4], "Wisdom 3 + level 1");
  assert.deepEqual(picks({ level_paladin: 1 }, { cha: 16 }), [0, 0], "a paladin prepares none at 1st");
  assert.deepEqual(picks({ level_paladin: 2 }, { cha: 16 }), [0, 4]);
  assert.deepEqual(picks({ level_fighter: 3 }), [0, 0]);
  const steps = parsedAsset.sheet.builder.steps;
  const step = (id) => steps.find((each) => each.id === id);
  assert.deepEqual(step("cantrips").countFrom, { derived: "builder_cantrips" });
  assert.deepEqual(step("cantrips").filters, { kind: "cantrip" });
  assert.deepEqual(step("spells").countFrom, { derived: "builder_spells" });
  assert.deepEqual(step("spells").filters, { kind: "spell" });
  const spells = JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries;
  // A spell's special function (Dispel Evil and Good's, 0.103.0) is neither, so the guided steps never offer it.
  assert.ok(
    spells.every(
      (entry) =>
        entry.filters.kind === (entry.filters.level === 0 ? "cantrip" : "spell") ||
        // And the flame a held Flame Blade or Produce Flame is used with (0.164.0), Sunbeam's later
        // lines (0.175.0), Compulsion's steering (0.242.0), seeing through a familiar's eyes (0.246.0)
        // and Pact of the Chain's own copy of Find Familiar (0.248.0).
        (entry.filters.kind === "special function" &&
          (entry.id.startsWith("dispel-evil-and-good-") ||
            // And Wind Walk's way back (0.284.0) and into the cloud again (0.288.0), and looking through
            // Mislead's and Project Image's double (0.296.0), and Magic Jar's possession and return (0.366.0).
            [
              "flame-blade-strike",
              "produce-flame-hurl",
              "sunbeam-line",
              "compulsion-direct",
              "find-familiar-see",
              "find-familiar-pact-of-the-chain",
              "wind-walk-revert",
              "wind-walk-recloud",
              "mislead-see",
              "project-image-see",
              "magic-jar-possess",
              "magic-jar-return",
            ].includes(entry.id))),
    ),
  );
  assert.throws(
    () =>
      assertRulesetSheetHooks(
        { ...shippedManifest, capabilityApi: { major: 1, minor: 89 } },
        parsedAsset,
        shippedCatalogSources,
      ),
    /reads the count of builder step "(?:pact_boon|cantrips|hit_point_rolls)" off the sheet and must declare capability API 1\.90/u,
  );
  const badCount = structuredClone(parsedAsset);
  badCount.sheet.builder.steps.find((each) => each.id === "spells").countFrom = { derived: "nope" };
  assert.throws(() => assertRulesetSheetHooks(shippedManifest, badCount, shippedCatalogSources), /countFrom/u);
}
// Racial spells (0.27.0): the high elf's wizard cantrip and the tiefling's thaumaturgy, cast with the
// race's own ability whatever the class casts with.
{
  const sheet = (fields, abilities = {}) =>
    evaluateSheet(parsedAsset, { abilities, skills: {}, saves: {}, bonuses: {}, fields, lists: {} });
  const elf = sheet(
    { racial_spell_ability: "int", spellcasting_ability: "wis", level_cleric: 5 },
    { int: 14, wis: 18 },
  );
  assert.equal(elf.derived("racial_spell_save_dc"), 13, "8 + proficiency 3 + Int 2");
  assert.equal(elf.derived("racial_spell_attack"), 5);
  assert.equal(elf.derived("spell_save_dc"), 15, "the cleric's own spells stay on Wisdom");
  const entries = (file) => JSON.parse(shippedCatalogSources.get(`catalogs/${file}.json`)).entries;
  const races = entries("races");
  assert.deepEqual(races.find((entry) => entry.id === "high-elf").grants.sets, { racial_spell_ability: "int" });
  assert.deepEqual(races.find((entry) => entry.id === "tiefling").grants.sets, {
    racial_spell_ability: "cha",
    size: 3,
  });
  assert.equal(races.filter((entry) => entry.grants?.sets?.racial_spell_ability).length, 2);
  assert.deepEqual(
    races
      .filter((entry) => entry.grants?.sets?.size === 2)
      .map((entry) => entry.id)
      .sort(),
    ["gnome", "halfling"],
    "Small races set size 2",
  );
  assert.deepEqual(
    races
      .find((entry) => entry.id === "tiefling")
      .rows.filter((row) => row.list === "spells")
      .map((row) => row.values.name),
    ["Thaumaturgy"],
  );
  const offered = entries("spells").filter((entry) => entry.filters.race_ids);
  assert.equal(offered.length, 14, "the SRD's 14 wizard cantrips");
  assert.ok(offered.every((entry) => entry.filters.level === 0 && entry.filters.class_ids.includes("wizard")));
  assert.ok(offered.every((entry) => entry.filters.race_ids.join() === "high-elf"));
  const step = parsedAsset.sheet.builder.steps.find((each) => each.id === "racial_cantrip");
  assert.deepEqual(step.within, { step: "subrace", filter: "race_ids" });
  assert.equal(step.max, 1);
}
// Seller honesty: the shipped package's five fakes, each a real, sellable item's look-alike read across
// the catalog FILES, gated at 1.79.
assert.equal(assertRulesetSellerHonesty(shippedManifest, parsedAsset, shippedCatalogSources), 8); // and the three typed Armors of Vulnerability (0.431.0)
{
  const magic = JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json"));
  const withMagic = (edit) => {
    const entries = structuredClone(magic.entries);
    edit(entries, (id) => entries.find((entry) => entry.id === id).item);
    return new Map([...shippedCatalogSources, ["catalogs/magic_items.json", JSON.stringify({ ...magic, entries })]]);
  };
  const older = { ...shippedManifest, capabilityApi: { major: 1, minor: 78 } };
  assert.throws(
    () => assertRulesetSellerHonesty(older, parsedAsset, shippedCatalogSources),
    /has a risky item, a fake or a dishonest seller and must declare capability API 1\.79 or newer/u,
  );
  for (const [edit, refusal] of [
    [(_entries, item) => (item("bag-of-devouring").passesFor = "magic_items/bag-of-devouring"), /, itself$/u],
    [
      (_entries, item) => (item("bag-of-devouring").passesFor = "magic_items/bag-of-nothing"),
      /no item of the package/u,
    ],
    [
      (_entries, item) => (item("bag-of-devouring").passesFor = "magic_items/potion-of-poison"),
      /itself a fake or cursed/u,
    ],
    [(_entries, item) => delete item("bag-of-holding").cost, /has no cost and is never sold/u],
    [
      (_entries, item) => (item("bag-of-devouring").passesFor = "magic_items/potion-of-healing"),
      /a different kind of item/u,
    ],
    [(_entries, item) => (item("armor-of-vulnerability").slots = { hands: 1 }), /worn in other slots/u],
    [(_entries, item) => delete item("shield-of-missile-attraction").binds, /binds differently/u],
  ]) {
    assert.throws(() => assertRulesetSellerHonesty(shippedManifest, parsedAsset, withMagic(edit)), refusal);
  }
  // No honesty, no gate: the package as an older one would ship it.
  const plain = withMagic((entries) => {
    for (const entry of entries) {
      delete entry.item.passesFor;
      delete entry.item.risky;
    }
  });
  const honestOnly = structuredClone(parsedAsset);
  for (const seller of honestOnly.items.market.sellers) delete seller.honest;
  assert.equal(assertRulesetSellerHonesty(older, honestOnly, plain), 0);
  // A dishonest seller alone is 1.79's too.
  assert.throws(
    () => assertRulesetSellerHonesty(older, parsedAsset, plain),
    /has a risky item, a fake or a dishonest seller and must declare capability API 1\.79 or newer/u,
  );
}

// The shipped starting gear: every class's and the Acolyte's, every item in the equipment catalog FILE.
assert.equal(assertRulesetStartingGear(shippedManifest, parsedAsset, shippedCatalogSources), 13);
{
  const gearWith = (edit) => {
    const document = structuredClone(parsedAsset);
    edit(
      document.items.startingGear.find((gear) => gear.id === "fighter"),
      document,
    );
    return document;
  };
  assert.throws(
    () =>
      assertRulesetStartingGear(
        { ...shippedManifest, capabilityApi: { major: 1, minor: 77 } },
        parsedAsset,
        shippedCatalogSources,
      ),
    /offers starting gear and must declare capability API 1\.78 or newer/u,
  );
  for (const [edit, refusal] of [
    [
      (gear) => (gear.choices[0].options[0].lines[0].item = "equipment/chain-mial"),
      /which that catalog does not hold/u,
    ],
    [
      (gear) => gear.choices[1].options[1].lines[0].oneOf.push("equipment/lance-of-ages"),
      /which that catalog does not hold/u,
    ],
    [(gear) => (gear.choices[0].options[0].lines[0].item = "weapons/longsword"), /which is no item catalog's entry/u],
    [
      (gear, document) => {
        gear.lines.push({ item: "equipment/torch" });
        const catalog = JSON.parse(shippedCatalogSources.get("catalogs/equipment.json"));
        catalog.entries.find((entry) => entry.id === "torch").item.service = true;
        document.catalogs.find((each) => each.id === "equipment").entries = catalog.entries;
      },
      /a service, which is never carried/u,
    ],
    [(gear) => gear.lines.push({ coins: "dollar", count: 5 }), /pays in unknown coin "dollar"/u],
    [
      (gear) => (gear.fits.value = { field: "level_fightr" }),
      /fits by a value that names unknown field "level_fightr"/u,
    ],
    [(gear) => (gear.fits = null), /fits by a value that must be a value reference/u],
    [(gear) => delete gear.fits.atLeast, /fits needs a finite number atLeast/u],
    [(gear) => (gear.fits.atleast = 1), /fits has the unknown key "atleast"/u],
  ]) {
    assert.throws(() => assertRulesetStartingGear(shippedManifest, gearWith(edit), shippedCatalogSources), refusal);
  }
  // The phrase parser on sentences written the SRD's way, so its rules are pinned without the fixtures.
  const item = (id, category = "gear", tags = []) => ({ id, item: { category, tags } });
  const equipment = [
    item("greataxe", "weapon", ["martial", "melee"]),
    item("longsword", "weapon", ["martial", "melee"]),
    item("dagger", "weapon", ["simple", "melee"]),
    item("mace", "weapon", ["simple", "melee"]),
    item("shortbow", "weapon", ["simple", "ranged"]),
    item("chain-mail", "armor", ["heavy_armor"]),
    item("shield", "shield"),
    item("quiver"),
    item("arrow-bow", "ammunition"),
    item("backpack"),
    item("rope-hempen-50-feet"),
    item("torch"),
    item("pouch"),
    item("book"),
    item("crystal"),
    item("orb"),
  ];
  const itemSets = new Map([
    [
      "explorers-pack",
      {
        desc: "Includes a backpack, and 10 torches. The pack also has 50 feet of hempen rope strapped to the side of it.",
        items: [],
      },
    ],
    ["arcane-focuses", { desc: "", items: ["srd_crystal", "srd_orb", "srd-2024_crystal"] }],
  ]);
  const build = (desc, acolyteText = "A prayer book, and a pouch containing 15 gp") =>
    buildStartingGear({
      classFeatures: [{ pk: "srd_fighter_equipment", desc, className: "Fighter" }],
      classNames: new Set(["fighter"]),
      acolyteText,
      itemSets,
      equipment,
    });
  const [fighter, acolyte] = build(
    [
      "You start with the following equipment, in addition to the equipment granted by your background:",
      "* (*a*) chain mail (if proficient) or (*b*) a shortbow and quiver of 20 arrows",
      "* (*a*) a martial weapon and a shield, (*b*) two martial weapons, or (*c*) any simple weapon",
      "* (*a*) An explorer\u2019s pack, two daggers, and an arcane focus",
    ].join("\n"),
  );
  assert.deepEqual(fighter.fits, { value: { field: "level_fighter" }, atLeast: 1 });
  assert.equal(fighter.group, "class");
  // A single "(a)" is no choice: its lines are the gear's own, a pack as what it holds.
  assert.deepEqual(fighter.lines, [
    { item: "equipment/backpack" },
    { item: "equipment/torch", count: 10 },
    { item: "equipment/rope-hempen-50-feet" },
    { item: "equipment/dagger", count: 2 },
    { oneOf: ["equipment/crystal", "equipment/orb"] },
  ]);
  assert.deepEqual(
    fighter.choices.map((choice) => [choice.label, choice.options.map((option) => option.label)]),
    [
      ["Choice 1", ["Chain mail (if proficient)", "A shortbow and quiver of 20 arrows"]],
      ["Choice 2", ["A martial weapon and a shield", "Two martial weapons", "Any simple weapon"]],
    ],
  );
  // Armor and a shield are put on; a quiver's 20 arrows are part of the phrase; "two" of a kind is two picks.
  assert.deepEqual(fighter.choices[0].options[0].lines, [{ item: "equipment/chain-mail", equip: true }]);
  // "(if proficient)" is offered only with the training (0.301.0).
  assert.deepEqual(fighter.choices[0].options[0].offeredWhen, { derived: "prof_heavy_armor" });
  assert.deepEqual(fighter.choices[0].options[1].lines, [
    { item: "equipment/shortbow", equip: true },
    { item: "equipment/quiver" },
    { item: "equipment/arrow-bow", count: 20 },
  ]);
  const martial = { oneOf: ["equipment/greataxe", "equipment/longsword"], equip: true };
  assert.deepEqual(fighter.choices[1].options[0].lines, [martial, { item: "equipment/shield", equip: true }]);
  assert.deepEqual(fighter.choices[1].options[1].lines, [martial, martial]);
  assert.deepEqual(fighter.choices[1].options[2].lines, [
    { oneOf: ["equipment/dagger", "equipment/mace", "equipment/shortbow"], equip: true },
  ]);
  assert.deepEqual(acolyte.lines, [
    { item: "equipment/book" },
    { item: "equipment/pouch" },
    { coins: "gp", count: 15 },
  ]);
  assert.equal(acolyte.group, "background");
  assert.equal(acolyte.fits, undefined);
  // An "or" in the background's sentence is a choice.
  assert.deepEqual(
    build("* A greataxe", "A prayer book or prayer wheel")[1].choices[0].options.map((option) => option.label),
    ["A prayer book", "Prayer wheel"],
  );
  // A phrase the table does not know, "any" of one item, and a class the sheet has no level of stop the build.
  assert.throws(() => build("* A lantern of seeing"), /no table entry for "A lantern of seeing"/u);
  assert.throws(() => build("* Any greataxe"), /says "any" of one item/u);
  assert.throws(
    () =>
      buildStartingGear({
        classFeatures: [{ pk: "srd_bard_equipment", desc: "* A dagger", className: "Bard" }],
        classNames: new Set(["fighter"]),
        acolyteText: "A prayer book",
        itemSets,
        equipment,
      }),
    /is for no class the sheet has a level of/u,
  );
  const none = structuredClone(parsedAsset);
  delete none.items.startingGear;
  assert.equal(
    assertRulesetStartingGear({ ...shippedManifest, capabilityApi: { major: 1, minor: 77 } }, none),
    0,
    "no gear, no gate",
  );
}
