// Immune to a track a level reads, not a condition (1.115).
{
  const tracked = (minor) => {
    const document = bestiaryDocument((block) => (block.conditionImmunities = ["exhaustion"]));
    document.combat = {
      ...document.combat,
      levels: [{ track: "exhaustion", at: 1, effects: ["own-checks-disadvantage"] }],
    };
    return () => assertRulesetCreatures({ ...creatureManifest, capabilityApi: { major: 1, minor } }, document);
  };
  assert.throws(tracked(114), /immune to the track "exhaustion" and must declare capability API 1\.115/u);
  assert.doesNotThrow(tracked(115));
}
