// A bestiary shipped as its own asset is read exactly the same way.
{
  const document = bestiaryDocument();
  const inline = document.catalogs[0].entries;
  document.catalogs[0] = { id: "beasts", label: "Beasts", holds: "creatures", asset: "catalogs/beasts.json" };
  const sources = new Map([
    ["catalogs/beasts.json", JSON.stringify({ schemaVersion: 1, catalog: "beasts", entries: inline })],
  ]);
  assert.equal(assertRulesetCreatures(creatureManifest, document, sources), 1);
  // An asset this check cannot read is assertRulesetCatalogs' rejection to make, with a better message.
  assert.equal(assertRulesetCreatures(creatureManifest, document, new Map()), 0);
}

// ── Items (Capability API 1.49) ──
//
// An item catalog writes no rows: each entry carries an item, named in the ruleset's `items` block.

const itemDocument = (edit = () => {}, header = {}) => {
  const document = {
    id: "test",
    version: 1,
    name: "Test",
    sheet: combatSheet,
    items: { categories: [{ id: "weapon", label: "Weapon" }] },
    catalogs: [
      {
        id: "gear",
        label: "Gear",
        holds: "items",
        entries: [{ id: "club", label: "Club", item: { category: "weapon" } }],
        ...header,
      },
    ],
  };
  edit(document);
  return document;
};
const itemManifest = rulesetManifest({ capabilityApi: { major: 1, minor: 49 } });

assert.equal(assertRulesetItems(itemManifest, itemDocument()), 1);
assert.deepEqual(
  assertRulesetCatalogs(itemManifest, itemDocument()).map((summary) => summary.entryCount),
  [1],
  "an item entry writes no rows, and the catalog checks let it",
);
// A ruleset with no item catalog is untouched, and needs no 1.49.
assert.equal(assertRulesetItems(rulesetManifest(), combatDocument(combatBlock)), 0);
assert.throws(
  () =>
    assertRulesetItems(
      rulesetManifest({ capabilityApi: { major: 1, minor: 48 } }),
      itemDocument((document) => delete document.items),
    ),
  /ships items and must declare capability API 1\.49 or newer/u,
);
// The block alone, with no catalog of items, is read by the same Engine.
assert.throws(
  () =>
    assertRulesetItems(
      rulesetManifest({ capabilityApi: { major: 1, minor: 48 } }),
      itemDocument((document) => delete document.catalogs),
    ),
  /declares an items block and must declare capability API 1\.49 or newer/u,
);
assert.equal(
  assertRulesetItems(
    itemManifest,
    itemDocument((document) => delete document.catalogs),
  ),
  0,
);
for (const check of [assertRulesetItems, assertRulesetCatalogs]) {
  assert.throws(
    () =>
      check(
        itemManifest,
        itemDocument(() => {}, { feeds: ["attacks"] }),
      ),
    /catalog "gear" holds items, so it feeds no list/u,
  );
}
assert.throws(
  () =>
    assertRulesetItems(
      itemManifest,
      itemDocument((document) => delete document.items),
    ),
  /catalog "gear" holds items, which need an items block to be written in/u,
);
for (const [edit, message] of [
  [(entry) => delete entry.item, /entry "club" carries no item, and this catalog holds items/u],
  [(entry) => (entry.item = ["weapon"]), /entry "club" carries no item, and this catalog holds items/u],
  [(entry) => (entry.rows = [{ list: "attacks", values: {} }]), /entry "club" has both rows and an item/u],
  [(entry) => (entry.item.category = "wand"), /entry "club" names unknown item category "wand"/u],
]) {
  const document = itemDocument();
  edit(document.catalogs[0].entries[0]);
  assert.throws(() => assertRulesetItems(itemManifest, document), message);
}
// Items and creatures stay in their own catalogs.
assert.throws(
  () =>
    assertRulesetItems(itemManifest, {
      ...itemDocument(),
      catalogs: [
        {
          id: "gear",
          label: "Gear",
          feeds: ["attacks"],
          entries: [
            { id: "club", label: "Club", rows: [{ list: "attacks", values: {} }], item: { category: "weapon" } },
          ],
        },
      ],
    }),
  /catalog "gear" holds rows, so entry "club" cannot carry an item/u,
);
assert.throws(
  () =>
    assertRulesetCreatures(creatureManifest, {
      ...itemDocument(),
      combat: combatBlock,
      catalogs: [{ ...itemDocument().catalogs[0], entries: [{ id: "club", label: "Club", creature: creature() }] }],
    }),
  /catalog "gear" holds items, so entry "club" cannot carry a creature/u,
);

// ── The shipped equipment (P1-1) ──
//
// The SRD 5.1 equipment tables as items, pinned to what the SRD prints, so a converter change that
// moves a number is caught here rather than at somebody's table.
{
  const equipment = JSON.parse(shippedCatalogSources.get("catalogs/equipment.json")).entries;
  const itemCount = parsedAsset.catalogs
    .filter((catalog) => catalog.holds === "items")
    .reduce((total, catalog) => total + JSON.parse(shippedCatalogSources.get(catalog.asset)).entries.length, 0);
  assert.equal(assertRulesetItems(shippedManifest, parsedAsset, shippedCatalogSources), itemCount);
  const byId = new Map(equipment.map((entry) => [entry.id, entry.item]));
  const counts = {};
  for (const item of byId.values()) counts[item.category] = (counts[item.category] ?? 0) + 1;
  assert.deepEqual(counts, {
    gear: 93,
    tool: 35,
    weapon: 37,
    armor: 12,
    ammunition: 4,
    shield: 1,
    poison: 15,
    material: 43,
  });
  // No trade goods, vehicles or poisons, and the fixture's second, free Acid is not the SRD's.
  for (const id of ["cow", "galley", "wagon", "acid"]) assert.equal(byId.has(id), false, id);
  // Armor: base, Dexterity, Strength and Stealth as the Armor table prints them.
  const armor = (id) => byId.get(id);
  assert.deepEqual(armor("plate-armor").stats, { weight: 65, ac_base: 18, dex_cap: 0, dex_floor: 0 });
  assert.deepEqual(armor("plate-armor").requires, [
    { value: { derived: "armor_speed_strength" }, atLeast: 15, otherwise: { modifiers: [{ to: "speed", flat: -10 }] } },
    // Worn without its training, since 0.317.0.
    { value: { derived: "heavy_armor_levels" }, atLeast: 1, otherwise: { keepsOn: ["armor_untrained"] } },
  ]);
  assert.deepEqual(armor("half-plate").stats, { weight: 40, ac_base: 15, dex_cap: 2 });
  assert.deepEqual(armor("half-plate").slots, { body: 1 }, "armor is worn on the body, one suit at a time");
  assert.deepEqual(armor("studded-leather-armor").stats, { weight: 13, ac_base: 12 });
  assert.deepEqual(
    equipment.filter((entry) => entry.item.worn?.effects?.includes("own-checks-disadvantage")).map((entry) => entry.id),
    ["chain-mail", "half-plate", "padded-armor", "plate-armor", "ring-mail", "scale-mail", "splint-armor"],
    "the SRD's seven armors that give disadvantage on Stealth",
  );
  for (const id of ["chain-mail", "splint-armor"])
    assert.equal(armor(id).requires[0].atLeast, id === "chain-mail" ? 13 : 15);
  assert.deepEqual(byId.get("shield"), {
    category: "shield",
    rarity: "common",
    slots: { hands: 1 },
    requires: [{ value: { derived: "shield_levels" }, atLeast: 1, otherwise: { keepsOn: ["armor_untrained"] } }],
    tags: ["mundane"],
    stats: { weight: 6, ac_bonus: 2, unarmored_ac_bonus: 0 },
    cost: { amount: 10, unit: "gp" },
  });
  // Weapons: the attack a held weapon makes.
  assert.deepEqual(byId.get("rapier").attack, {
    budget: "action",
    toHit: { abilities: ["str", "dex"], proficiency: { derived: "prof_named_weapons" } },
    damage: {
      dice: "1d8",
      abilities: ["str", "dex"],
      type: "piercing",
      sheetBonus: { derived: "dueling" },
      oneHanded: true,
      rerollUpTo: { listSum: { list: "features", column: "reroll_two_handed" } },
    },
    reach: 5,
    strikes: { derived: "attacks_per_action_total" },
  });
  assert.deepEqual(byId.get("longbow").attack.ammo, { tag: "arrow", recover: 0.5 });
  assert.deepEqual(byId.get("longbow").slots, { hands: 2 });
  assert.equal(byId.get("crossbow-light").attack.strikes, undefined, "a weapon that loads fires once");
  assert.equal(byId.get("dagger").attack.offHand, true);
  assert.equal(byId.get("handaxe").attack.offHand, true);
  assert.equal(byId.get("crossbow-hand").attack.offHand, undefined, "a light ranged weapon is no off-hand strike");
  assert.deepEqual(byId.get("longbow").attack.toHit.abilities, ["dex"], "a ranged weapon rolls Dexterity");
  assert.deepEqual(byId.get("longbow").attack.damage.abilities, ["dex"]);
  assert.deepEqual(byId.get("dagger").attack.range, { normal: 20, long: 60 });
  assert.deepEqual(byId.get("longsword").attack.versatile, { dice: "1d10" });
  assert.equal(byId.get("glaive").attack.reach, 10);
  // The SRD prints the shortsword piercing where the fixture says slashing, for the item and the row.
  assert.equal(byId.get("shortsword").attack.damage.type, "piercing");
  assert.equal(
    parsedAsset.catalogs.find((catalog) => catalog.id === "weapons").entries.find((entry) => entry.id === "shortsword")
      .rows[0].values.damage_type,
    "piercing",
  );
  assert.equal(byId.get("greataxe").attack.toHit.proficiency.derived, "prof_martial_weapons");
  assert.equal(byId.get("club").attack.toHit.proficiency.derived, "prof_simple_weapons");
  assert.deepEqual(byId.get("lance").slots, { hands: 2 }, "the lance on foot");
  // From 0.254.0 (1.511) the blowgun deals its flat 1 and the net only restrains.
  assert.deepEqual(byId.get("blowgun").attack.damage, { bonus: 1, abilities: ["dex"], type: "piercing" });
  assert.deepEqual(byId.get("net").attack.damage, {});
  // Weights and costs: the SRD's own, the fixture's three missing weights put back.
  assert.equal(byId.get("greatsword").stats.weight, 6);
  assert.equal(byId.get("rod").stats.weight, 2);
  assert.equal(byId.get("blanket").stats.weight, 3);
  assert.deepEqual(byId.get("arrow-bow").cost, { amount: 5, unit: "cp" });
  assert.deepEqual(byId.get("paper-one-sheet").cost, { amount: 2, unit: "sp" });
  assert.deepEqual(byId.get("spyglass").cost, { amount: 1000, unit: "gp" });
  // Metal-headed since 0.296.0, for what corrodes metal.
  assert.deepEqual(byId.get("arrow-bow").tags, ["arrow", "metal", "mundane"]);
  // Spellcasting focuses, from the SRD's own lists of them.
  const focus = (tag) => equipment.filter((entry) => entry.item.tags?.includes(tag)).map((entry) => entry.id);
  assert.deepEqual(focus("arcane_focus"), ["crystal", "orb", "rod", "staff", "wand"]);
  assert.deepEqual(focus("druidic_focus"), ["sprig-of-mistletoe", "totem", "wooden-staff", "yew-wand"]);
  assert.deepEqual(focus("holy_symbol"), ["amulet", "emblem", "reliquary"]);
  // Coins weigh fifty to the pound, at the SRD's exchange.
  assert.deepEqual(
    parsedAsset.items.currencies.map((family) => [family.perWeight, family.units.map((unit) => [unit.id, unit.value])]),
    [
      [
        50,
        [
          ["cp", 1],
          ["sp", 10],
          ["ep", 50],
          ["gp", 100],
          ["pp", 1000],
        ],
      ],
    ],
  );
  // Armor Class reads what is worn, and Sneak Attack names held weapons.
  assert.deepEqual(parsedAsset.combat.defense, { derived: "armor_class" });
  assert.deepEqual(parsedAsset.combat.offHand, {
    budget: "bonus",
    ability: "penalty-only",
    fullWhen: { listSum: { list: "features", column: "offhand_ability" } },
  });
  const features = JSON.parse(shippedCatalogSources.get("catalogs/features.json")).entries;
  assert.deepEqual(features.find((entry) => entry.id === "rogue-sneak-attack").mechanics.rider.weapons, {
    tags: ["finesse", "ranged"],
  });
}

// ── The shipped potions, scrolls and consumables (P1-2) ──
{
  const magic = JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries;
  const byId = new Map(magic.map((entry) => [entry.id, entry.item]));
  const potions = magic.filter((entry) => entry.item.category === "potion");
  const scrolls = magic.filter((entry) => entry.item.category === "scroll");
  assert.equal(potions.length, 38, "the SRD potions and ten resistance choices");
  // Nor a plain entry holding only a spell's choices (0.379.0): each choice has its own scroll.
  const spells = JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries.filter(
    (entry) => entry.filters.kind !== "special function" && !(entry.variants && !entry.mechanics),
  );
  assert.equal(scrolls.length, spells.length, "a scroll of every spell");
  // Healing, read off the SRD's table by each potion's name.
  assert.deepEqual(
    ["potion-of-healing", "potion-of-greater-healing", "potion-of-superior-healing", "potion-of-supreme-healing"].map(
      (id) => [byId.get(id).rarity, byId.get(id).use.amount.dice],
    ),
    [
      ["common", "2d4+2"],
      ["uncommon", "4d4+4"],
      ["rare", "8d4+8"],
      ["very_rare", "10d4+20"],
    ],
  );
  assert.deepEqual(byId.get("potion-of-heroism").use.temporary, { flat: 10 });
  assert.deepEqual(byId.get("potion-of-heroism").use.applies, [{ condition: "blessed", duration: { rounds: 600 } }]);
  assert.deepEqual(byId.get("potion-of-speed").use.applies, [{ condition: "hasted", duration: { rounds: 10 } }]);
  assert.deepEqual(byId.get("potion-of-flying").use.applies, [
    { condition: "potion_flying", duration: { rounds: 600 } },
  ]);
  for (const potion of potions) assert.equal(potion.item.use?.consumes ?? true, true, `${potion.id} is drunk once`);
  // Scrolls: the SRD's table by level, the spell's own mechanics, and a reading check above level 0.
  const fireball = byId.get("spell-scroll-fireball");
  assert.equal(fireball.rarity, "uncommon");
  assert.deepEqual(
    [fireball.use.saveDifficulty, fireball.use.amount, fireball.use.damageType, fireball.use.consumes],
    [15, { dice: "8d6" }, "fire", true],
  );
  assert.deepEqual(fireball.use.gate, {
    check: { value: { abilityModFromField: "spellcasting_ability" } },
    difficulty: 13,
    unless: { value: { derived: "slots_3" }, atLeast: 1 },
  });
  assert.deepEqual(
    [byId.get("spell-scroll-fire-bolt").use.toHit, byId.get("spell-scroll-fire-bolt").use.gate],
    [{ bonus: 5 }, undefined],
    "a cantrip: the scroll's +5 and no check",
  );
  assert.equal(byId.get("spell-scroll-wish").rarity, "legendary");
  assert.deepEqual(
    [
      byId.get("spell-scroll-magic-missile").use.gate.difficulty,
      byId.get("spell-scroll-magic-missile").use.gate.unless,
    ],
    [11, { value: { derived: "slots_1" }, atLeast: 1 }],
    "a 1st-level scroll asks for a 1st-level slot",
  );
  assert.deepEqual(byId.get("spell-scroll-bless").use.applies, [{ condition: "blessed", duration: { rounds: 10 } }]);
  assert.deepEqual(
    [byId.get("potion-of-healing").use.kind, byId.get("potion-of-healing").use.targets],
    ["heal", "ally"],
    "a potion heals whoever drinks it, the drinker or somebody fed it",
  );
  assert.equal(byId.get("spell-scroll-knock").use, undefined, "a utility spell's scroll is text");
  assert.equal(byId.get("spell-scroll-healing-word").use.budget, "action", "a scroll is read with an action");
  // A reaction's scroll is read as its reaction since 0.318.0.
  assert.equal(byId.get("spell-scroll-shield").use.budget, "reaction", "a reaction's scroll is read with a reaction");
  for (const scroll of scrolls) {
    if (scroll.item.use && scroll.item.use.budget !== "reaction") {
      // Concentration rides along since 0.73.0 (Capability API 1.174), checked there.
      for (const key of ["cost", "perCostStep", "scales", "reaction"]) {
        assert.equal(scroll.item.use[key], undefined, `${scroll.id} carries no ${key}`);
      }
    }
  }
  // The thrown consumables, and the poisons as items.
  const equipment = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/equipment.json")).entries.map((entry) => [entry.id, entry.item]),
  );
  assert.deepEqual(without(equipment.get("acid-vial").use, "title"), {
    kind: "attack",
    budget: "action",
    range: 20,
    attackRoll: true,
    toHit: { abilities: ["dex"] },
    amount: { dice: "2d6" },
    damageType: "acid",
    consumes: true,
  });
  assert.deepEqual(
    [equipment.get("alchemists-fire-flask").use.amount, equipment.get("alchemists-fire-flask").use.damageType],
    // Since 0.255.0 its 1d4 burns as each of its target's turns starts (alchemists_fire), not on the hit.
    [{ flat: 0 }, "fire"],
  );
  assert.deepEqual(
    equipment.get("holy-water-flask").use.plus,
    [{ dice: "2d6", type: "radiant", targetIs: { types: ["fiend", "undead"] } }],
    "holy water harms only fiends and undead (0.67.0)",
  );
  assert.equal([...equipment.values()].filter((item) => item.category === "poison").length, 15);
}

// ── The shipped magic arms, armor and wondrous items (P1-3a) ──
{
  const magic = JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries;
  const byId = new Map(magic.map((entry) => [entry.id, entry.item]));
  const counts = {};
  for (const item of byId.values()) counts[item.category] = (counts[item.category] ?? 0) + 1;
  assert.deepEqual(counts, {
    potion: 38,
    // 0.164.0: one more, Produce Flame held, as Enlarge/Reduce has its Reduce; 0.191.0: Plane Shift (Banish); 0.237.0: Glyph of Warding's cold, fire, lightning and thunder runes;
    // 0.238.0: Magic Circle's eleven more; 0.239.0: Symbol's five; 0.240.0: its Fear and Hopelessness;
    // 0.242.0: Bestow Curse's ability scores and Hallow's Extradimensional Interference; 0.244.0: Bestow
    // Curse one scroll again.
    // And Antipathy/Sympathy on an object (0.246.0), a scroll of each; Forcecage's box (0.284.0); True
    // Polymorph's object choices (0.296.0); Alter Self's Natural Weapons (0.297.0); Wish's menu (0.368.0, 0.369.0).
    scroll: 418,
    // The Rod of Lordly Might's three forms (0.270.0).
    // The Berserker Axe's three axes (0.431.0).
    weapon: 220,
    // Armor +1/+2/+3 for the twelve armors and the three typed Armors of Vulnerability (0.431.0).
    armor: 205,
    // Shield +1/+2/+3 (0.431.0).
    shield: 7,
    // The Rings of Elemental Command, each with its elemental slain (0.323.0).
    ring: 40,
    rod: 6,
    staff: 12,
    wand: 15,
    // Bag of Tricks' rust and tan bags (0.266.0); Carpet of Flying's three larger carpets (0.295.0); the
    // Feather Token's whip (0.325.0), two more ivory goats (0.327.0) and Goodberry's berry (0.335.0); the Feather Token's bird (0.352.0); Creation's object (0.369.0).
    // And the Ioun Stone of Fortitude (0.431.0).
    wondrous: 167,
    // An arrow of slaying for each creature type (0.301.0); Ammunition +1/+2/+3 of four kinds (0.431.0).
    ammunition: 27,
  });
  // A +N weapon is its SRD weapon with the bonus to hit and to damage, and is magical.
  const plus = (id, bonus, rarity) => {
    const item = byId.get(id);
    assert.deepEqual(
      [item.attack.toHit.bonus, item.attack.damage.bonus, item.rarity, item.tags.includes("magical")],
      [bonus, bonus, rarity, true],
      id,
    );
  };
  // The fixture files mithral half plate as a weapon and the potion of fire giant strength as wondrous.
  for (const entry of magic) {
    // A shield's training (0.317.0) is no armor's number.
    if (
      entry.item.requires?.some((one) => one.value.derived !== "shield_levels") ||
      entry.item.stats?.ac_base !== undefined
    ) {
      assert.equal(entry.item.category, "armor", `${entry.id} has armor's numbers`);
    }
  }
  assert.equal(byId.get("potion-of-fire-giant-strength").category, "potion");
  plus("longsword-1", 1, "uncommon");
  plus("longsword-2", 2, "rare");
  plus("longsword-3", 3, "very_rare");
  plus("sun-blade", 2, "rare");
  assert.equal(byId.get("flame-tongue-longsword").attack.toHit.bonus, undefined, "a flame tongue's fire is its text");
  // Armor and shields start from the SRD's own.
  assert.deepEqual(byId.get("dwarven-plate").stats, { weight: 65, ac_base: 18, dex_cap: 0, dex_floor: 0, ac_bonus: 2 });
  assert.equal(byId.get("dwarven-plate").requires[0].atLeast, 15);
  assert.deepEqual(
    [byId.get("mithral-armor-plate").requires, byId.get("mithral-armor-plate").worn],
    // Its training still asked since 0.317.0.
    [
      [{ value: { derived: "heavy_armor_levels" }, atLeast: 1, otherwise: { keepsOn: ["armor_untrained"] } }],
      undefined,
    ],
    "mithral: no Strength requirement and no Stealth disadvantage",
  );
  assert.deepEqual(byId.get("animated-shield").stats, { weight: 6, ac_bonus: 2, unarmored_ac_bonus: 0 });
  assert.deepEqual(byId.get("animated-shield").slots, { hands: 1 });
  // Worn numbers, read off each item's sentence.
  assert.deepEqual(
    [byId.get("ring-of-protection").stats.ac_bonus, byId.get("ring-of-protection").worn],
    [1, { modifiers: [{ to: "saves", flat: 1 }] }],
  );
  assert.equal(byId.get("bracers-of-defense").stats.unarmored_ac_bonus, 2);
  assert.equal(byId.get("bracers-of-defense").stats.ac_bonus, undefined, "never in armor");
  // "+2 bonus to AC if you are wearing no armor and using no shield": a shield gives the bonus as 0
  // and the sheet reads the lowest one worn, so a shield takes it away and two pairs give +2.
  const derived = new Map(parsedAsset.sheet.derived.map((value) => [value.id, value]));
  assert.ok(
    derived
      .get("ac_unarmored")
      .of.some(
        (ref) =>
          JSON.stringify(ref) ===
          JSON.stringify({ itemStat: { stat: "unarmored_ac_bonus", from: "worn", pick: "min" } }),
      ),
  );
  const shield = JSON.parse(shippedCatalogSources.get("catalogs/equipment.json")).entries.find(
    (entry) => entry.id === "shield",
  );
  assert.equal(shield.item.stats.unarmored_ac_bonus, 0, "a shield cancels bracers");
  assert.equal(byId.get("animated-shield").stats.unarmored_ac_bonus, 0, "and so does a magic shield");
  // Hit points from the class levels at the SRD's fixed values (0.21.0): the largest die's highest face
  // at 1st level, its average after, Constitution once a level, at least 1; a typed number wins.
  {
    const hp = (fields, con) =>
      evaluateSheet(parsedAsset, { abilities: { con }, skills: {}, saves: {}, bonuses: {}, fields, lists: {} }).derived(
        "hp_max_total",
      );
    assert.equal(hp({ level_fighter: 5 }, 15), 44, "10 + 2, then four times 6 + 2");
    assert.equal(hp({ level_wizard: 5 }, 14), 32, "6 + 2, then four times 4 + 2");
    assert.equal(hp({ level_barbarian: 1 }, 16), 15, "12 + 3");
    assert.equal(hp({ level_fighter: 1, level_wizard: 1 }, 10), 14, "the d10 first, then 4");
    assert.equal(hp({ level_other: 3, hit_die: "d10" }, 12), 25, "the Other class die");
    assert.equal(hp({}, 6), 1, "never below 1");
    assert.equal(hp({ level_fighter: 5, hp_max: 30 }, 15), 30, "rolled low, typed by hand");
    assert.equal(hp({ level_fighter: 20 }, 20), 224);
    // The method: Average ignores a typed number, Rolled reads the Hit point rolls, By hand the typed one.
    const withRolls = (fields, con, rolls) =>
      evaluateSheet(parsedAsset, {
        abilities: { con },
        skills: {},
        saves: {},
        bonuses: {},
        fields,
        lists: { hp_rolls: rolls.map((roll) => ({ roll })) },
      }).derived("hp_max_total");
    assert.equal(hp({ level_fighter: 5, hp_max: 30, hp_method: "average" }, 15), 44, "Average ignores the typed 30");
    assert.equal(
      withRolls({ level_fighter: 5, hp_method: "rolled" }, 15, [3, 10, 1, 7]),
      10 + 21 + 10,
      "10, the rolls, Con",
    );
    assert.equal(withRolls({ level_fighter: 5, hp_method: "rolled" }, 4, []), 1, "rolled never below 1");
    assert.equal(
      withRolls({ level_fighter: 5, hp_method: "auto" }, 15, [1, 1, 1, 1]),
      44,
      "only Rolled reads the rolls",
    );
    assert.equal(hp({ level_fighter: 5, hp_max: 30, hp_method: "by_hand" }, 15), 30);
    assert.equal(hp({ level_fighter: 5, hp_method: "by_hand" }, 15), 1, "by hand with nothing typed is 1");
    // The first class's die where it is not the largest: a Wizard 5 / Fighter 1 who began as a wizard.
    assert.equal(hp({ level_wizard: 5, level_fighter: 1 }, 10), 30, "the largest die by default");
    assert.equal(hp({ level_wizard: 5, level_fighter: 1, hp_first_die: "d6" }, 10), 28, "6 + 4 x 4 + 6");
    // Rolls still to make: one row for each level after 1st.
    const left = (rows) =>
      evaluateSheet(parsedAsset, {
        abilities: { con: 10 },
        skills: {},
        saves: {},
        bonuses: {},
        fields: { level_fighter: 5, hp_method: "rolled" },
        lists: { hp_rolls: rows.map((roll) => ({ roll, counts: 1 })) },
      }).derived("hp_rolls_left");
    assert.deepEqual([left([]), left([5, 5, 5, 5]), left([5, 5, 5, 5, 5])], [4, 0, -1]);
    // The Engine holds an invented creature's hit points through the one field in the pool's sum.
    const total = parsedAsset.sheet.derived.find((value) => value.id === "hp_max_total");
    assert.equal(total.op, "sum");
    assert.deepEqual(
      total.of.filter((ref) => ref.field !== undefined),
      [{ field: "hp_max" }],
    );
    const pool = parsedAsset.sheet.live.pools.find((each) => each.id === "hp");
    assert.deepEqual(pool.max, { derived: "hp_max_total" });
    assert.equal(parsedAsset.sheet.fields.find((field) => field.id === "hp_max").default, 0, "0 means worked out");
  }
  // Extra Attack from the class levels, the highest of them (never a sum), over the typed floor; and
  // every weapon and the attack list read that, not the typed field.
  assert.deepEqual(derived.get("extra_attack_fighter").table, [
    [0, 1],
    [5, 2],
    [11, 3],
    [20, 4],
  ]);
  assert.deepEqual(
    derived.get("extra_attack_martial_level").of,
    ["barbarian", "monk", "paladin", "ranger"].map((cls) => ({ field: `level_${cls}` })),
  );
  assert.deepEqual(derived.get("extra_attack_martial").table, [
    [0, 1],
    [5, 2],
  ]);
  assert.deepEqual(derived.get("attacks_per_action_total"), {
    ...derived.get("attacks_per_action_total"),
    op: "max",
    of: [{ field: "attacks_per_action" }, { derived: "extra_attack_fighter" }, { derived: "extra_attack_martial" }],
  });
  assert.deepEqual(parsedAsset.combat.attacks[0].strikes, { derived: "attacks_per_action_total" });
  assert.ok(
    !JSON.stringify(parsedAsset.combat).includes('"field":"attacks_per_action"'),
    "nothing reads the typed field directly",
  );
  assert.deepEqual(byId.get("gauntlets-of-ogre-power").worn.abilities, { str: { set: 19 } });
  assert.deepEqual(byId.get("headband-of-intellect").worn.abilities, { int: { set: 19 } });
  assert.deepEqual(
    ["hill", "stone", "frost", "fire", "cloud", "storm"].map(
      (giant) => byId.get(`belt-of-${giant}-giant-strength`).worn.abilities.str.set,
    ),
    [21, 23, 23, 25, 27, 29],
  );
  assert.deepEqual(byId.get("stone-of-good-luck-luckstone").worn.modifiers, [
    { to: "saves", flat: 1 },
    { to: "checks", flat: 1 },
  ]);
  assert.deepEqual(byId.get("boots-of-elvenkind").worn, { effects: ["own-checks-advantage"], skills: ["stealth"] });
  assert.equal(byId.get("boots-of-elvenkind").binds, undefined, "no attunement");
  assert.deepEqual(byId.get("ring-of-warmth").worn.resist, ["cold"]);
  assert.deepEqual(byId.get("frost-brand-longsword").worn.resist, ["fire"]);
  assert.equal(byId.get("dragon-scale-mail").worn.resist, undefined, "the kind of dragon decides, which is text");
  assert.deepEqual(byId.get("brooch-of-shielding").worn.resist, ["force"]);
  assert.equal(byId.get("ioun-stone-protection").stats.ac_bonus, 1, "while it orbits your head");
  // Numbers that are not the wearer's, always: none of them.
  assert.equal(byId.get("defender-longsword").stats.ac_bonus, undefined, "a defender moves its +3, never adds to it");
  assert.equal(byId.get("vorpal-sword-longsword").worn, undefined, "a vorpal sword ignores its target's resistance");
  assert.deepEqual(
    [byId.get("rod-of-alertness").stats.ac_bonus, byId.get("rod-of-alertness").worn.modifiers],
    [undefined, undefined],
    "the rod's aura is planted first and shared",
  );
  assert.equal(byId.get("arrow-catching-shield").stats.ac_bonus, 2, "its +2 is only against ranged attacks");
  assert.equal(byId.get("ring-of-elemental-command").worn, undefined, "earned by slaying an elemental");
  // Since 0.322.0 the helm resists fire while worn, its gems' light kept on.
  // Since 0.337.0 only while a ruby, and its light while any gem, is left.
  assert.deepEqual(
    byId.get("helm-of-brilliance").worn,
    {
      resist: ["fire"],
      keepsOn: ["brilliance_radiance"],
      whileLeft: [
        { keys: ["resist"], uses: "Wall of Fire (ruby)" },
        { keys: ["keepsOn"], charges: true },
      ],
    },
    "fire resistance while worn",
  );
  assert.deepEqual(byId.get("periapt-of-proof-against-poison").worn.immune, ["poison"]);
  assert.equal(byId.get("dragon-scale-mail").stats.ac_bonus, 1, "+1 to AC beside a clause about dragons");
  // Attunement, its restriction, and curses.
  // Its class read off the sheet since 0.302.0.
  assert.deepEqual(byId.get("holy-avenger-longsword").binds, {
    restriction: "Requires Attunement by a Paladin",
    needs: [{ value: { field: "level_paladin" }, atLeast: 1 }],
  });
  for (const id of ["armor-of-vulnerability", "demon-armor", "shield-of-missile-attraction"]) {
    assert.equal(byId.get(id).binds.cursed, true, `${id} is cursed`);
  }
  assert.equal(byId.get("ring-of-protection").slots.worn, 1, "a ring is worn");
  assert.deepEqual(byId.get("boots-of-elvenkind").slots, { worn: 1 }, "boots without attunement are worn in a slot");
  assert.equal(byId.get("bag-of-holding").slots, undefined, "a bag is carried");
  // Wands that cast one spell: a charge a cast at the wand's DC, seven charges, back at dawn, a d20 on the last.
  const fireballs = byId.get("wand-of-fireballs");
  assert.deepEqual(fireballs.charges, {
    max: 7,
    recharge: { rests: ["long"], amount: { dice: "1d6+1" } },
    breaksOn: { die: 20, atMost: 1 },
  });
  assert.deepEqual(
    [fireballs.use.charges, fireballs.use.saveDifficulty, fireballs.use.amount, fireballs.stack],
    [1, 15, { dice: "8d6" }, 1],
  );
  assert.equal(byId.get("wand-of-magic-missiles").use.autoHit, true);
  assert.equal(byId.get("wand-of-lightning-bolts").use.area.shape, "line");
  assert.deepEqual(
    magic.filter((entry) => entry.item.charges).map((entry) => entry.id),
    [
      "armor-of-invulnerability",
      "bag-of-tricks",
      "bag-of-tricks-rust",
      "bag-of-tricks-tan",
      // The boots, the robe's stars, the ointment's doses and the fan count theirs since 0.289.0.
      "boots-of-speed",
      // The elemental vessels, the silver horn and the djinni's ring call creatures since 0.283.0.
      "bowl-of-commanding-water-elementals",
      "brazier-of-commanding-fire-elementals",
      "cape-of-the-mountebank",
      "censer-of-controlling-air-elementals",
      "circlet-of-blasting",
      // The cube's faces since 0.298.0.
      "cube-of-force",
      // The Dagger of Venom's coating (0.400.0).
      "dagger-of-venom",
      // The dust's pinches, the gem's, the ring's stars and the robe's flashes since 0.297.0.
      "dust-of-dryness",
      "efreeti-bottle",
      // These lenses, and the helm and the Wand of Polymorph below, cast since 0.285.0.
      "eyes-of-charming",
      "figurine-of-wondrous-power-bronze-griffon",
      // The ebony fly's since 0.358.0.
      "figurine-of-wondrous-power-ebony-fly",
      "figurine-of-wondrous-power-golden-lions",
      // The ivory goats call theirs since 0.327.0.
      "figurine-of-wondrous-power-ivory-goat-of-terror",
      "figurine-of-wondrous-power-ivory-goat-of-traveling",
      "figurine-of-wondrous-power-ivory-goats",
      "figurine-of-wondrous-power-marble-elephant",
      "figurine-of-wondrous-power-obsidian-steed",
      "figurine-of-wondrous-power-onyx-dog",
      "figurine-of-wondrous-power-serpentine-owl",
      "figurine-of-wondrous-power-silver-raven",
      "gem-of-brightness",
      "gem-of-seeing",
      "hammer-of-thunderbolts",
      // The Helm of Brilliance's gems (0.322.0) and the Helm of Telepathy's Suggestion (0.321.0).
      "helm-of-brilliance",
      "helm-of-telepathy",
      "helm-of-teleportation",
      // The brass, bronze and iron horns call theirs since 0.287.0.
      "horn-of-valhalla-brass",
      "horn-of-valhalla-bronze",
      "horn-of-valhalla-iron",
      "horn-of-valhalla-silver",
      "ioun-stone-absorption",
      "ioun-stone-greater-absorption",
      // Once a dawn since 0.294.0.
      "iron-bands-of-binding",
      "javelin-of-lightning",
      // The mace's Terror and the plate's etherealness since 0.311.0.
      "mace-of-terror",
      // The necklace's beads since 0.348.0.
      "necklace-of-fireballs",
      "nine-lives-stealer-greatsword",
      "nine-lives-stealer-longsword",
      "nine-lives-stealer-rapier",
      "nine-lives-stealer-shortsword",
      "oathbow",
      // Once a dawn since 0.301.0.
      "pearl-of-power",
      // The haunting pipes since 0.290.0; the sewers' pipes call their swarms since 0.288.0.
      "pipes-of-haunting",
      "pipes-of-the-sewers",
      "plate-armor-of-etherealness",
      "restorative-ointment",
      // The elemental rings' spells (0.323.0) and the Ring of Animal Influence's (0.315.0).
      "ring-of-air-elemental-command",
      "ring-of-air-elemental-command-elemental-slain",
      "ring-of-animal-influence",
      "ring-of-djinni-summoning",
      "ring-of-earth-elemental-command",
      "ring-of-earth-elemental-command-elemental-slain",
      "ring-of-evasion",
      "ring-of-fire-elemental-command",
      "ring-of-fire-elemental-command-elemental-slain",
      "ring-of-shooting-stars",
      "ring-of-the-ram",
      // Its wishes since 0.295.0.
      "ring-of-three-wishes",
      "ring-of-water-elemental-command",
      "ring-of-water-elemental-command-elemental-slain",
      "robe-of-scintillating-colors",
      "robe-of-stars",
      "rod-of-absorption",
      "rod-of-lordly-might",
      // Once a dawn since 0.290.0.
      "rod-of-rulership",
      // The Scarab of Protection's charges (0.403.0).
      "scarab-of-protection",
      "staff-of-charming",
      "staff-of-fire",
      "staff-of-frost",
      "staff-of-healing",
      "staff-of-power",
      "staff-of-striking",
      "staff-of-swarming-insects",
      "staff-of-the-magi",
      "staff-of-the-woodlands",
      "staff-of-thunder-and-lightning",
      "staff-of-withering",
      "stone-of-controlling-earth-elementals",
      // The talismans' fissures since 0.307.0.
      "talisman-of-pure-good",
      "talisman-of-ultimate-evil",
      // Its Dominate Beast, 0.296.0.
      "trident-of-fish-command",
      "wand-of-binding",
      "wand-of-fear",
      "wand-of-fireballs",
      "wand-of-lightning-bolts",
      "wand-of-magic-missiles",
      "wand-of-paralysis",
      "wand-of-polymorph",
      "wand-of-web",
      "wand-of-wonder",
      "wind-fan",
      "wings-of-flying",
    ],
    "charges only where a use, a slay, a mode or a hit spends them",
  );
  // A staff wielded as a magic quarterstaff is one, with its bonus.
  assert.deepEqual(
    ["staff-of-striking", "staff-of-power", "staff-of-withering"].map((id) => byId.get(id).attack?.toHit.bonus ?? null),
    [3, 2, null],
  );
  assert.equal(byId.get("staff-of-fire").attack, undefined, "a staff that is not a quarterstaff");
  // A magic quarterstaff is made of the quarterstaff, not of the druid's staff that is one too.
  assert.ok(!byId.get("quarterstaff-1").tags.includes("druidic_focus"), "a +1 quarterstaff is no focus");
}

// 0.59.0: SRD item effects use existing Engine primitives, with unsupported effects left as text.
{
  const entries = JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries;
  const items = new Map(entries.map((entry) => [entry.id, entry.item]));
  const damageTypes = [
    "acid",
    "cold",
    "fire",
    "force",
    "lightning",
    "necrotic",
    "poison",
    "psychic",
    "radiant",
    "thunder",
  ];
  const armorKinds = [
    "leather",
    "padded",
    "studded-leather",
    "hide",
    "chain-shirt",
    "scale-mail",
    "half-plate",
    "breastplate",
    "ring-mail",
    "chain-mail",
    "splint",
    "plate",
  ];
  for (const type of damageTypes) {
    assert.deepEqual(items.get(`ring-of-resistance-${type}`).worn.resist, [type]);
    for (const armor of armorKinds) {
      const original = items.get(`armor-of-resistance-${armor}`);
      const variant = items.get(`armor-of-resistance-${armor}-${type}`);
      assert.deepEqual(variant.worn.resist, [type]);
      assert.deepEqual(variant.stats, original.stats, "a resistance variant keeps the armor's AC and weight");
      assert.deepEqual(variant.binds, original.binds);
      assert.deepEqual(variant.slots, original.slots);
    }
  }
  for (const [dragon, type] of Object.entries({
    black: "acid",
    blue: "lightning",
    brass: "fire",
    bronze: "lightning",
    copper: "acid",
    gold: "fire",
    green: "poison",
    red: "fire",
    silver: "cold",
    white: "cold",
  }))
    assert.deepEqual(items.get(`dragon-scale-mail-${dragon}`).worn.resist, [type]);
  assert.equal(items.get("ring-of-resistance").worn, undefined, "a GM's undecided ring never resists every type");
  assert.equal(items.get("potion-of-resistance").use, undefined, "NEEDS ENGINE: typed condition resistance");

  for (const bonus of [1, 2, 3]) {
    const wand = items.get(`wand-of-the-war-mage-${bonus}`);
    assert.equal(wand.stats.spell_attack_bonus, bonus);
    assert.equal(wand.stats.spell_dc_bonus, undefined, "War Mage never raises a save DC");
    assert.deepEqual(wand.slots, { hands: 1 });
  }
  const robe = items.get("robe-of-the-archmagi");
  assert.equal(robe.stats.spell_attack_bonus, 2);
  assert.equal(robe.stats.spell_dc_bonus, 2);
  for (const staff of ["staff-of-power", "staff-of-the-magi", "staff-of-the-woodlands"])
    assert.equal(items.get(staff).stats.spell_attack_bonus, 2);
  assert.equal(items.get("staff-of-power").stats.ac_bonus, 2);
  assert.deepEqual(items.get("staff-of-power").worn.modifiers, [{ to: "saves", flat: 2 }]);
  assert.equal(items.get("staff-of-power").stats.spell_dc_bonus, undefined);

  // Substitute Engine itemStat reads into the existing sheet evaluator, which otherwise deliberately
  // reads an empty inventory. Prove all callers (generic/class/racial spells and movement) see the stats.
  const withWorn = (ids, fields = {}) => {
    const document = structuredClone(parsedAsset);
    const selected = ids.map((id) => items.get(id));
    const replace = (value) => {
      if (!value || typeof value !== "object") return value;
      if (value.itemStat) {
        const ref = value.itemStat;
        const values = selected.map((item) => item.stats?.[ref.stat]).filter((value) => value !== undefined);
        return {
          const:
            ref.pick === "sum"
              ? values.reduce((sum, value) => sum + value, 0)
              : values.length
                ? Math.max(...values)
                : (ref.default ?? 0),
        };
      }
      return Array.isArray(value)
        ? value.map(replace)
        : Object.fromEntries(Object.entries(value).map(([key, child]) => [key, replace(child)]));
    };
    document.sheet.derived = replace(document.sheet.derived);
    return evaluateSheet(document, {
      skills: {},
      saves: {},
      bonuses: {},
      lists: {},
      abilities: { str: 10, dex: 10, con: 10, int: 10, wis: 10, cha: 10 },
      fields: { spellcasting_ability: "int", racial_spell_ability: "int", ...fields },
    });
  };
  const blank = withWorn([]);
  const dressed = withWorn(["robe-of-the-archmagi", "wand-of-the-war-mage-3"]);
  for (const id of ["spell_attack", "spell_attack_int", "spell_attack_wis", "spell_attack_cha", "racial_spell_attack"])
    assert.equal(dressed.derived(id) - blank.derived(id), 5, id);
  for (const id of [
    "spell_save_dc",
    "spell_save_dc_int",
    "spell_save_dc_wis",
    "spell_save_dc_cha",
    "racial_spell_save_dc",
  ])
    assert.equal(dressed.derived(id) - blank.derived(id), 2, id);
  assert.equal(withWorn(["winged-boots"], { speed: 35 }).derived("fly_speed_total"), 35);
  assert.equal(withWorn(["winged-boots"], { speed: 25, fly_speed: 60 }).derived("fly_speed_total"), 60);
  assert.equal(withWorn(["slippers-of-spider-climbing"], { speed: 35 }).derived("climb_speed_total"), 35);
  assert.equal(withWorn(["ring-of-swimming"]).derived("swim_speed_total"), 40);
  assert.equal(withWorn(["cloak-of-the-manta-ray", "ring-of-swimming"]).derived("swim_speed_total"), 60);
  for (const mode of ["fly", "swim", "climb"]) {
    assert.equal(blank.derived(`${mode}_speed_total`), 0, "taking the item off removes its speed");
    assert.deepEqual(
      parsedAsset.combat.economy.movementModes[mode],
      mode === "climb" ? { field: "climb_speed" } : { derived: `${mode}_speed_total` },
    );
  }

  const circlet = items.get("circlet-of-blasting");
  assert.deepEqual(circlet.charges, { max: 1, recharge: { rests: ["long"], amount: { flat: 1 } } });
  assert.deepEqual(
    [circlet.use.charges, circlet.use.attackRoll, circlet.use.toHit, circlet.use.amount, circlet.use.targetCount],
    [1, true, { bonus: 5 }, { dice: "2d6" }, 3],
  );
  const paralysis = items.get("wand-of-paralysis");
  assert.deepEqual(paralysis.charges, {
    max: 7,
    recharge: { rests: ["long"], amount: { dice: "1d6+1" } },
    breaksOn: { die: 20, atMost: 1 },
  });
  assert.equal(paralysis.use.charges, 1);
  assert.equal(paralysis.use.range, 60);
  assert.equal(paralysis.use.saveDifficulty, 15);
  assert.deepEqual(paralysis.use.save, { save: "con_save", onSuccess: "negates" });
  assert.deepEqual(paralysis.use.applies, [
    { condition: "paralyzed", duration: { rounds: 10 }, saveEnds: { save: "con_save", at: "turn-end" } },
  ]);
  const bead = items.get("necklace-of-fireballs-bead");
  assert.deepEqual(
    [bead.use.consumes, bead.use.range, bead.use.saveDifficulty, bead.use.amount, bead.use.area],
    [true, 60, 15, { dice: "8d6" }, { shape: "burst", size: 20 }],
  );
  assert.equal(bead.slots, undefined, "a detached bead is used from the bag");
  // Since 0.348.0 its 1d6 + 3 beads are rolled as it is found (1.573), never a fixed count.
  assert.deepEqual(
    items.get("necklace-of-fireballs").charges,
    { max: 9, rolled: "1d6+3" },
    "never invent a fixed count for 1d6 + 3 beads",
  );
  const power = items.get("staff-of-power");
  assert.deepEqual(power.charges, {
    max: 20,
    recharge: { rests: ["long"], amount: { dice: "2d8+4" } },
    breaksOn: {
      die: 20,
      atMost: 1,
      becomes: "magic_items/quarterstaff-2",
      regains: { atLeast: 20, amount: { dice: "1d8+2" } },
    },
  });
  assert.deepEqual(
    [power.use.charges, power.use.autoHit, power.use.amount, power.use.targetCount],
    [1, true, { dice: "1d4+1" }, 3],
  );
  assert.equal(power.use.save, undefined);
  const lightning = items.get("staff-of-thunder-and-lightning");
  assert.deepEqual(lightning.charges, { max: 1, recharge: { rests: ["long"], amount: { flat: 1 } } });
  assert.deepEqual(
    [lightning.use.charges, lightning.use.amount, lightning.use.area, lightning.use.saveDifficulty, lightning.use.save],
    [1, { dice: "9d6" }, { shape: "line", size: 120 }, 17, { save: "dex_save", onSuccess: "half" }],
  );

  const bracers = items.get("bracers-of-archery");
  assert.equal(bracers.stats.archery_damage, 2);
  assert.equal(bracers.stats.archery_training, 1);
  const equipment = JSON.parse(shippedCatalogSources.get("catalogs/equipment.json")).entries;
  for (const entry of [...equipment, ...entries].filter((entry) => entry.item.attack)) {
    const ref = entry.item.attack.damage.sheetBonus?.itemStat;
    const bow = entry.item.attack.ammo?.tag === "arrow";
    assert.equal(ref?.stat === "archery_damage", bow, entry.id);
    if (bow)
      assert.deepEqual(entry.item.attack.toHit.proficiency, {
        derived: entry.item.attack.range.normal === 150 ? "prof_longbow" : "prof_shortbow",
      });
  }
  for (const bow of ["longbow", "shortbow"]) {
    assert.equal(withWorn(["bracers-of-archery"], { weapon_training: "none" }).derived(`prof_${bow}`), 1);
    assert.equal(withWorn([], { weapon_training: "none" }).derived(`prof_${bow}`), 0);
  }
  for (const id of [
    "belt-of-dwarvenkind",
    "ioun-stone-agility",
    "ioun-stone-insight",
    "ioun-stone-intellect",
    "ioun-stone-leadership",
    "ioun-stone-strength",
  ])
    // A capped add since 0.181.0 (1.313).
    assert.equal(Object.values(items.get(id).worn?.abilities ?? {})[0]?.max, 20, "a +2 to at most 20");
  for (const id of [
    "ring-of-feather-falling",
    // The Dust of Sneezing and Choking chokes since 0.300.0. The Elemental Gem calls its elemental since 0.193.0, and the Trident of Fish Command dominates
    // since 0.296.0.
    // The Broom of Flying flies since 0.193.0.
  ])
    assert.equal(items.get(id).use, undefined, `${id} needs unsupported Engine keys`);
  // Since 0.131.0 (1.264) the Wand of Fear has its Cone of Fear; its Command waits on a use menu.
  assert.equal(items.get("wand-of-fear").use.charges, 2);
  // Since 0.74.0 (1.175) the Wand of Web casts Web at DC 15.
  assert.equal(items.get("wand-of-web").use.zone.terrain.difficult, true);
}

// ── Prices and loot (P1-4) ──
{
  const magic = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries.map((entry) => [entry.id, entry.item]),
  );
  const price = (id) => magic.get(id).cost;
  // By rarity and use (Sane Magical Prices' approach, the package's numbers): fighting 1,500 gp at
  // uncommon and four times a step up, helping 0.4 of that, game-changing four times; creatures by their
  // XP; a tenth for what is used up, times its pieces; scrolls doubling from 25 gp; plus what it is
  // made of. The potion of healing keeps the SRD's 50 gp.
  assert.deepEqual(
    [
      "potion-of-healing",
      "potion-of-greater-healing",
      "potion-of-climbing",
      "spell-scroll-fire-bolt",
      "spell-scroll-magic-missile",
      "spell-scroll-fireball",
      "spell-scroll-meteor-swarm",
      "ring-of-protection",
      "longsword-1",
      "dwarven-plate",
      "arrow-of-slaying",
      "wand-of-fireballs",
      "bag-of-holding",
      "broom-of-flying",
      "cubic-gate",
      "horn-of-valhalla-silver",
      "figurine-of-wondrous-power-onyx-dog",
      "necklace-of-fireballs",
      "staff-of-power",
    ].map((id) => price(id)?.amount),
    [50, 150, 50, 25, 50, 200, 12800, 6000, 1515, 25500, 2400, 6000, 600, 6000, 384000, 15750, 2400, 4200, 24000],
  );
  // The hand lists: an item whose fight is only in its text fights, a wand that only finds helps.
  assert.deepEqual(
    [
      "ring-of-the-ram",
      "potion-of-invisibility",
      "wand-of-secrets",
      "staff-of-charming",
      "belt-of-dwarvenkind",
      "talisman-of-the-sphere",
      "candle-of-invocation",
      "elemental-gem",
    ].map((id) => price(id)?.amount),
    [6000, 2400, 600, 2400, 6000, 96000, 9600, 900],
  );
  // Never for sale: an artifact, a wish (the deck of many things aside), the efreeti bottle, a cursed
  // item with nothing to pass for, and the shield guardian's amulet, which is no SRD item (0.265.0).
  const unpriced = [...magic].filter(([, item]) => !item.cost).map(([id]) => id);
  assert.deepEqual(unpriced, [
    // The cursed Berserker Axe (0.431.0).
    "berserker-axe-battleaxe",
    "berserker-axe-greataxe",
    "berserker-axe-handaxe",
    // Creation's object (0.369.0) and Goodberry's berry (0.335.0), only ever made by the spell.
    "created-object",
    "demon-armor",
    "efreeti-bottle",
    "goodberry",
    "luck-blade-greatsword",
    "luck-blade-longsword",
    "luck-blade-rapier",
    "luck-blade-shortsword",
    "orb-of-dragonkind",
    "ring-of-three-wishes",
    // The Rod of Lordly Might's forms (0.270.0), only ever the rod itself.
    "rod-of-lordly-might-battleaxe",
    "rod-of-lordly-might-flame-tongue",
    "rod-of-lordly-might-spear",
    "shield-guardian-amulet",
    "spell-scroll-wish",
    // And its menu's scrolls (0.368.0, 0.369.0).
    ...[
      "heal",
      "immunity",
      ...[
        "acid",
        "bludgeoning",
        "cold",
        "fire",
        "force",
        "lightning",
        "necrotic",
        "piercing",
        "poison",
        "psychic",
        "radiant",
        "slashing",
        "thunder",
      ].map((type) => `resistance-${type}`),
    ].map((id) => `spell-scroll-wish-${id}`),
  ]);
  // Wild chance: priced, with the warning an honest seller gives. Fakes: what each passes for, at what it
  // is truly worth, always below the price of what it passes for.
  assert.deepEqual(
    ["deck-of-many-things", "wand-of-wonder", "bag-of-beans"].map((id) => [
      price(id)?.amount,
      Boolean(magic.get(id).risky),
    ]),
    [
      [38400, true],
      [6000, true],
      [1920, true],
    ],
  );
  for (const [id, target] of [
    ["bag-of-devouring", "bag-of-holding"],
    ["dust-of-sneezing-and-choking", "dust-of-disappearance"],
    ["potion-of-poison", "potion-of-healing"],
    ["armor-of-vulnerability", "armor-of-resistance-plate"],
    ["shield-of-missile-attraction", "arrow-catching-shield"],
  ]) {
    assert.equal(magic.get(id).passesFor, `magic_items/${target}`);
    assert.ok(price(id).amount < price(target).amount, `${id} is worth less than ${target}`);
  }
  // Every magic item is tagged magical, and ordinary gear is common.
  for (const [id, item] of magic) assert.ok(item.tags?.includes("magical"), `${id} is magical`);
  for (const entry of JSON.parse(shippedCatalogSources.get("catalogs/equipment.json")).entries) {
    assert.equal(entry.item.rarity, "common", `${entry.id} is common`);
  }
  // Four tables by challenge, each line finding something to drop.
  const items = [
    ...magic.values(),
    ...JSON.parse(shippedCatalogSources.get("catalogs/equipment.json")).entries.map((e) => e.item),
  ];
  const matches = (filter) =>
    items.filter(
      (item) =>
        (filter.rarity === undefined || item.rarity === filter.rarity) &&
        (filter.category === undefined || item.category === filter.category) &&
        (filter.tag === undefined || item.tags?.includes(filter.tag)),
    ).length;
  const tables = parsedAsset.items.lootTables;
  assert.deepEqual(
    tables.map((table) => table.id),
    [
      "treasure_low",
      "treasure_mid",
      "treasure_high",
      "treasure_epic",
      "smiths_odd_lot",
      "dealers_odd_lot",
      "fences_odd_lot",
    ],
  );
  // Every item a table names is one of the package's, and the fence's lot names only fakes.
  for (const table of tables) {
    for (const line of table.entries) {
      if (line.item) assert.ok(magic.has(line.item.replace(/^magic_items\//u, "")), `${table.id} names ${line.item}`);
    }
  }
  for (const line of tables.find((table) => table.id === "fences_odd_lot").entries) {
    if (line.item) assert.ok(magic.get(line.item.replace(/^magic_items\//u, "")).passesFor, `${line.item} is a fake`);
  }
  for (const table of tables) {
    for (const line of table.entries) {
      if (line.filter) assert.ok(matches(line.filter) > 0, `${table.id} ${JSON.stringify(line.filter)} finds nothing`);
    }
  }
  // Who carries what: a creature that can use money, by its challenge.
  const creatures = JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries;
  const carries = (id) => creatures.find((entry) => entry.id === id).creature.loot;
  assert.deepEqual(
    [
      "goblin",
      "gladiator",
      "mage",
      "adult-red-dragon",
      "lich",
      "wolf",
      "zombie",
      "ogre",
      "gelatinous-cube",
      "djinni",
    ].map(carries),
    [
      "treasure_low",
      "treasure_mid",
      "treasure_mid",
      "treasure_epic",
      "treasure_epic",
      undefined,
      undefined,
      undefined,
      undefined,
      undefined,
    ],
  );
}

// ── The 5e market (P1-5) ──
{
  const market = parsedAsset.items.market;
  assert.deepEqual(
    market.prices.map((level) => [level.id, level.times, level.default ?? false]),
    [
      ["cheap", 0.75, false],
      ["fair", 1, true],
      ["dear", 1.5, false],
    ],
  );
  assert.deepEqual(
    market.places.map((place) => [place.id, place.purse.amount, place.purse.unit]),
    [
      ["hamlet", 20, "gp"],
      ["village", 100, "gp"],
      ["town", 1000, "gp"],
      ["city", 10000, "gp"],
    ],
  );
  assert.equal(market.buyBack, 0.5);
  assert.deepEqual(
    market.sellers.map((seller) => [
      seller.id,
      seller.place ?? "hamlet",
      seller.stock?.table ?? null,
      seller.honest ?? true,
    ]),
    [
      ["general_store", "hamlet", null, true],
      ["smith", "village", "smiths_odd_lot", true],
      ["temple", "village", null, true],
      ["herbalist", "village", null, true],
      ["alchemist", "town", null, true],
      ["scribe", "town", null, true],
      ["magic_dealer", "city", "dealers_odd_lot", true],
      ["fence", "town", "fences_odd_lot", false],
      ["jeweler", "town", null, true],
    ],
  );
  // Common magic from a town, uncommon from a city a few a day; nothing rarer on any shelf.
  assert.deepEqual(market.sold, [
    { filter: { rarity: "common", tag: "magical" }, place: "town" },
    { filter: { rarity: "uncommon" }, place: "city", limited: "1d2" },
  ]);
  for (const seller of market.sellers) {
    for (const filter of seller.sells) {
      assert.ok(
        !["rare", "very_rare", "legendary", "artifact"].includes(filter.rarity),
        `${seller.id} sells ${filter.rarity}`,
      );
    }
  }
  // Every piece of equipment is mundane, so the smith and the store sell no magic.
  const equipment = JSON.parse(shippedCatalogSources.get("catalogs/equipment.json")).entries;
  for (const entry of equipment) assert.ok(entry.item.tags.includes("mundane"), `${entry.id} is mundane`);
  const magic = JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries;
  for (const entry of magic) assert.ok(!entry.item.tags?.includes("mundane"), `${entry.id} is not`);
  // Ordinary gear is common too, so a rule about common MAGIC says magical: no place rule holds back
  // a piece of equipment (it is sold anywhere), and the magic dealer sells none of it.
  const picks = (filter, item) =>
    (filter.rarity === undefined || item.rarity === filter.rarity) &&
    (filter.category === undefined || item.category === filter.category) &&
    (filter.tag === undefined || item.tags?.includes(filter.tag));
  const dealer = market.sellers.find((seller) => seller.id === "magic_dealer");
  for (const { id, item } of equipment) {
    assert.equal(item.rarity, "common", `${id} is common`);
    assert.ok(!market.sold.some((rule) => picks(rule.filter, item)), `${id} is sold anywhere`);
    assert.ok(!dealer.sells.some((filter) => picks(filter, item)), `${id} is not the magic dealer's`);
  }
  assert.ok(magic.some(({ item }) => item.rarity === "common" && picks(market.sold[0].filter, item)));
}

// ── Positions: a fight on a board (Capability API 1.28) ──
//
// `distance` is what makes a fight positionable at all, and everything else here is a number
// measured in it. The Engine refuses a ruleset that declares one of them without a cell size to
// measure it in, so a package that did would install and then be a fight nobody could stand on.
// These restate the Engine's own rules and are never stricter: a CREATURE action may carry a plain
// reach or range with no `distance` anywhere, which has been legal since 1.27.

const positionsManifest = rulesetManifest({ capabilityApi: { major: 1, minor: 28 } });
// And the ice devil's wall since 0.342.0 (1.728).
const RULESET_AREA_SHAPES_FOR_TEST = ["burst", "cone", "line", "wall"];
/** The shipped block plus a cell size, with one further thing changed. */
const positionsWith = (edit = () => {}) =>
  combatWith((combat) => {
    combat.distance = { label: "ft", perCell: 5 };
    combat.ranged = { long: "disadvantage", adjacentFoe: "disadvantage" };
    combat.cover = { bonus: 2 };
    combat.opportunity = { budget: "bonus" };
    combat.attacks[0].reach = { column: "bonus" };
    combat.attacks[0].range = { normal: { column: "bonus" }, long: { column: "bonus" } };
    edit(combat);
  });

// The whole of it, declared together, is the shape that passes.
assert.equal(assertRulesetCombat(positionsManifest, positionsWith()), true);
// And the package as committed is one of them.
assert.ok(parsedAsset.combat.distance, "the shipped block must declare what one cell is worth");

// A block with no cell size is exactly what it was before any of this existed.
assert.equal(assertRulesetCombat(combatManifest, combatDocument(combatBlock)), true);
assert.throws(
  () => assertRulesetCombat(rulesetManifest({ capabilityApi: { major: 1, minor: 27 } }), positionsWith()),
  /gives a fight positions and must declare capability API 1\.28 or newer/u,
);
assert.doesNotThrow(() =>
  assertRulesetCombat(rulesetManifest({ capabilityApi: { major: 2, minor: 0 } }), positionsWith()),
);

// Each of the four keys, and a weapon distance, without a cell size to measure it in.
for (const [key, edit] of [
  ["ranged", (combat) => delete combat.cover && delete combat.opportunity],
  ["cover", (combat) => delete combat.ranged && delete combat.opportunity],
  ["opportunity", (combat) => delete combat.ranged && delete combat.cover],
]) {
  assert.throws(
    () =>
      assertRulesetCombat(
        positionsManifest,
        positionsWith((combat) => {
          delete combat.distance;
          delete combat.attacks[0].reach;
          delete combat.attacks[0].range;
          edit(combat);
        }),
      ),
    new RegExp(`combat "${key}" is measured in cells, so the block declares "distance" too`, "u"),
    key,
  );
}
for (const key of ["reach", "range"]) {
  assert.throws(
    () =>
      assertRulesetCombat(
        positionsManifest,
        positionsWith((combat) => {
          delete combat.distance;
          delete combat.ranged;
          delete combat.cover;
          delete combat.opportunity;
          delete combat.attacks[0][key === "reach" ? "range" : "reach"];
        }),
      ),
    new RegExp(`combat "attacks\\[0\\]\\.${key}" is measured in cells`, "u"),
    key,
  );
}

// Each of the four is an object or it is not there. A null, an array or a bare number is refused by
// name: reading a key off one of those would either throw or, for `ranged`, quietly pass.
for (const key of ["distance", "ranged", "cover", "opportunity"]) {
  for (const value of [null, [], 5, "yes"]) {
    const wanted = `combat ${key} must be an object, not ${JSON.stringify(value)}`;
    assert.throws(
      () =>
        assertRulesetCombat(
          positionsManifest,
          positionsWith((combat) => (combat[key] = value)),
        ),
      (error) => error.message.includes(wanted),
      `${key} = ${JSON.stringify(value)}`,
    );
  }
}

// The cell size itself.
for (const [perCell, message] of [
  [0, /combat distance perCell is a number above zero, not 0/u],
  [-5, /combat distance perCell is a number above zero, not -5/u],
  ["five", /combat distance perCell is a number above zero, not "five"/u],
]) {
  assert.throws(
    () =>
      assertRulesetCombat(
        positionsManifest,
        positionsWith((combat) => (combat.distance.perCell = perCell)),
      ),
    message,
    String(perCell),
  );
}
for (const label of ["", "a much longer unit"]) {
  assert.throws(
    () =>
      assertRulesetCombat(
        positionsManifest,
        positionsWith((combat) => (combat.distance.label = label)),
      ),
    /combat distance label .* is 1 to 12 characters/u,
    JSON.stringify(label),
  );
}

// What a long shot and a shot beside a foe cost is a closed pair of words.
for (const key of ["long", "adjacentFoe"]) {
  assert.throws(
    () =>
      assertRulesetCombat(
        positionsManifest,
        positionsWith((combat) => (combat.ranged[key] = "harder")),
      ),
    new RegExp(`combat ranged ${key} is disadvantage or normal, not "harder"`, "u"),
  );
  // Either may be left out, and then it costs nothing.
  assert.doesNotThrow(() =>
    assertRulesetCombat(
      positionsManifest,
      positionsWith((combat) => delete combat.ranged[key]),
    ),
  );
}

// Cover is a whole bonus a defense can hold.
for (const bonus of [-1, 2.5, 101, "two"]) {
  assert.throws(
    () =>
      assertRulesetCombat(
        positionsManifest,
        positionsWith((combat) => (combat.cover.bonus = bonus)),
      ),
    /combat cover bonus is a whole number from 0 to 100/u,
    String(bonus),
  );
}

// Cover by degrees (1.74): three-quarters' own whole bonus, saves the sheet declares, and creatures as
// true, each refused below 1.74.
const coverManifest = rulesetManifest({ capabilityApi: { major: 1, minor: 74 } });
const graded = (edit = () => {}) =>
  positionsWith((combat) => {
    combat.cover = { bonus: 2, threeQuarters: 5, saves: ["str_save"], creatures: true };
    edit(combat);
  });
assert.equal(assertRulesetCombat(coverManifest, graded()), true);
for (const key of ["threeQuarters", "saves", "creatures"]) {
  assert.throws(
    () =>
      assertRulesetCombat(
        positionsManifest,
        positionsWith((combat) => (combat.cover = { bonus: 2, [key]: graded().combat.cover[key] })),
      ),
    /grades cover .* and must declare capability API 1\.74 or newer/u,
    key,
  );
}
for (const [edit, refusal] of [
  [(combat) => (combat.cover.threeQuarters = 5.5), /cover threeQuarters bonus is a whole number from 0 to 100/u],
  [(combat) => (combat.cover.saves = ["luck_save"]), /cover names unknown save "luck_save"/u],
  [(combat) => (combat.cover.saves = []), /cover saves is a list of one to twelve saves/u],
  [(combat) => (combat.cover.creatures = false), /cover creatures is true or left out/u],
]) {
  assert.throws(() => assertRulesetCombat(coverManifest, graded(edit)), refusal);
}

// Height (1.75): what a board's levels do, refused below 1.75, with its numbers checked.
const heightManifest = rulesetManifest({ capabilityApi: { major: 1, minor: 75 } });
const withHeight = (elevation) => positionsWith((combat) => (combat.elevation = elevation));
assert.equal(assertRulesetCombat(heightManifest, withHeight({ levelHeight: 5 })), true);
assert.throws(
  () => assertRulesetCombat(coverManifest, withHeight({ levelHeight: 5 })),
  /says what height does and must declare capability API 1\.75 or newer/u,
);
for (const [elevation, refusal] of [
  [{ levelHeight: 0 }, /elevation levelHeight is a number above 0/u],
  [
    { levelHeight: 5, falling: { per: 10, dice: { count: 1, sides: 6 } } },
    /falling needs a per above 0, dice and a max/u,
  ],
  [
    { levelHeight: 5, falling: { per: 10, dice: { count: 1, sides: 6 }, max: 20, prone: "flat" } },
    /falling names unknown condition "flat"/u,
  ],
]) {
  assert.throws(() => assertRulesetCombat(heightManifest, withHeight(elevation)), refusal);
}

// The action economy a condition changes (1.76): Haste's extra action from a budget of no count, its
// lethargy when it ends, and Slow's one of two with its single attack. Refused below 1.76, and every
// budget, standard action and condition it names is one the ruleset has.
const economyManifest = rulesetManifest({ capabilityApi: { major: 1, minor: 76 } });
const withEconomy = (edit = () => {}) =>
  combatWith((combat) => {
    combat.economy.budgets.push({ id: "haste", label: "Haste action", per: "turn", count: 0 });
    combat.conditions.push({
      condition: "stunned",
      effects: [],
      budgets: [{ budget: "haste", flat: 1 }],
      grants: { budget: "haste", standard: ["dodge"], attacks: true, items: true },
      onEnd: { applies: [{ condition: "prone", duration: { rounds: 1 } }] },
    });
    combat.conditions[0].exclusive = ["action", "bonus"];
    combat.conditions[0].attacksPerTurn = 1;
    edit(combat);
  });
assert.equal(assertRulesetCombat(economyManifest, withEconomy()), true);
// Each half of the gate on its own: the condition fields with every budget counted, and a budget of no
// count with no condition fields.
for (const edit of [
  (combat) => (combat.economy.budgets.find((budget) => budget.id === "haste").count = 1),
  (combat) => (combat.conditions = combat.conditions.map(({ condition, effects }) => ({ condition, effects }))),
]) {
  assert.throws(
    () =>
      assertRulesetCombat(
        heightManifest,
        withEconomy((combat) => edit(combat)),
      ),
    /change the action economy, or a budget of no count, and must declare capability API 1\.76 or newer/u,
  );
}
// Without any of it, 1.75 is still enough.
assert.equal(
  assertRulesetCombat(
    heightManifest,
    withEconomy((combat) => {
      combat.conditions = combat.conditions.map(({ condition, effects }) => ({ condition, effects }));
      combat.economy.budgets.pop();
    }),
  ),
  true,
);
for (const [edit, refusal] of [
  [(combat) => (combat.economy.budgets[0].count = 11), /budget "action" hands out a whole number from 0 to 10/u],
  [(combat) => (combat.conditions[1].budgets[0].budget = "luck"), /budgets names unknown budget "luck"/u],
  [(combat) => (combat.conditions[1].budgets[0].flat = 1.5), /changes "haste" by a whole number from -10 to 10/u],
  [(combat) => (combat.conditions[1].budgets = []), /changes 1 to 4 budgets/u],
  [(combat) => (combat.conditions[1].grants.budget = "luck"), /grants names unknown budget "luck"/u],
  [(combat) => (combat.conditions[1].grants.standard = ["fly"]), /grants 1 to 7 standard actions the Engine resolves/u],
  [(combat) => (combat.conditions[1].grants.attacks = false), /grants attacks as true or not at all/u],
  [
    (combat) => (combat.conditions[1].grants = { budget: "haste" }),
    /grants a budget without saying what it may be spent on/u,
  ],
  [(combat) => (combat.conditions[0].exclusive = ["action", "action"]), /makes two different budgets exclusive/u],
  [(combat) => (combat.conditions[0].exclusive = ["action", "luck"]), /exclusive names unknown budget "luck"/u],
  [(combat) => (combat.conditions[0].attacksPerTurn = -1), /caps attacks at a whole number from 0 to 10/u],
  [(combat) => (combat.conditions[1].onEnd.applies[0].condition = "weary"), /leaves behind unknown condition "weary"/u],
  [(combat) => (combat.conditions[1].onEnd = { applies: [] }), /leaves 1 to 4 conditions behind when it ends/u],
  [
    (combat) => (combat.conditions[1].onEnd.applies[0].duration = "until-save"),
    /leaves "prone" behind for some rounds, not "until-save"/u,
  ],
  [
    (combat) => {
      combat.economy.budgets.push({ id: "focus", label: "Focus", per: "round", count: 1 });
      combat.conditions[1].budgets = [{ budget: "focus", flat: 1 }];
    },
    /changes "focus", which refills per round, not per turn/u,
  ],
  [
    (combat) => (combat.conditions[1].grants.standard = ["dash"]),
    /grants the standard action "dash", which this ruleset does not have/u,
  ],
  [(combat) => (combat.conditions[1].grants.budget = "action"), /grants standard actions on "action", which already/u],
  [(combat) => (combat.conditions[1].grants.items = { tags: ["mundane"] }), /grants items of unknown tag "mundane"/u],
  [(combat) => (combat.conditions[1].grants.items = { tags: [] }), /grants items as true or \{ tags: \[\.\.\.\] \}/u],
]) {
  assert.throws(() => assertRulesetCombat(economyManifest, withEconomy(edit)), refusal);
}

// Sheet migrations (1.77): refused below 1.77, and every hop and step read as the Engine reads them.
{
  const migrationsManifest = rulesetManifest({ capabilityApi: { major: 1, minor: 77 } });
  const sheetWith = (edit = () => {}) => {
    const sheet = structuredClone(combatSheet);
    sheet.version = 2;
    sheet.fields = [
      ...(sheet.fields ?? []),
      { id: "level_fighter", type: "number", min: 0, max: 20, default: 0 },
      { id: "level_other", type: "number", min: 0, max: 20, default: 0 },
      { id: "class", type: "text" },
    ];
    sheet.live = { ...sheet.live, pools: [...sheet.live.pools, { id: "dice_d10" }, { id: "dice_other" }] };
    sheet.migrations = [
      {
        from: 1,
        steps: [
          { route: "level", by: "class", cases: [{ words: ["fighter"], to: "level_fighter" }], else: "level_other" },
          { routeLive: "pool", from: "hit_dice", cases: ["dice_d10", "dice_other"], else: "dice_other" },
          { rename: "field", from: "xp", to: "experience_old" },
          {
            route: "experience_old",
            by: "class",
            cases: [{ words: ["fighter"], to: "level_fighter" }],
            else: "level_other",
          },
        ],
      },
    ];
    edit(sheet);
    return { id: "test", version: 1, name: "Test", sheet };
  };
  assert.equal(assertRulesetSheetMigrations(migrationsManifest, sheetWith()), true);
  assert.equal(assertRulesetSheetMigrations(combatManifest, { sheet: combatSheet }), false, "no migrations, no gate");
  const sharedRest = {
    sheet: combatSheet,
    rests: [{ id: "long", restore: [{ poolGroup: "dice", by: { fractionOfMax: 0.5 }, shared: true }] }],
  };
  assert.throws(
    () => assertRulesetSheetMigrations(heightManifest, sharedRest),
    /has a rest that shares a pool group's fraction and must declare capability API 1\.77 or newer/u,
  );
  assert.equal(assertRulesetSheetMigrations(migrationsManifest, sharedRest), false);
  assert.throws(
    () => assertRulesetSheetMigrations(heightManifest, sheetWith()),
    /says how older sheets read on its sheet and must declare capability API 1\.77 or newer/u,
  );
  for (const [edit, refusal] of [
    [(sheet) => (sheet.migrations[0].from = 2), /migration from 2 is not a version below 2/u],
    [
      (sheet) => sheet.migrations.push({ from: 1, steps: [{ rename: "field", from: "a", to: "class" }] }),
      /two sheet migrations from version 1/u,
    ],
    [(sheet) => (sheet.migrations[0].steps[2].from = "class"), /reads "class", still a field of the sheet/u],
    [(sheet) => (sheet.migrations[0].steps[2].to = "nowhere"), /ends at "nowhere", not a field of the sheet/u],
    [(sheet) => (sheet.migrations[0].steps[0].by = "clas"), /reads the text of unknown field "clas"/u],
    [
      (sheet) => {
        sheet.fields.push({ id: "level_one", type: "number", min: 0, max: 20, default: 1 });
        sheet.migrations[0].steps[0].else = "level_one";
      },
      /sends a value to "level_one", which is not a number or text field that starts empty/u,
    ],
    [
      (sheet) => (sheet.migrations[0].steps[0].cases[0].to = "level_bard"),
      /sends a value to unknown field "level_bard"/u,
    ],
    [(sheet) => (sheet.migrations[0].steps[1].from = "hp"), /reads "hp", still a pool of the sheet/u],
    [(sheet) => sheet.migrations[0].steps[1].cases.push("dice_d10"), /lists 1 or more cases, each once/u],
    [(sheet) => (sheet.migrations[0].steps[1].else = "dice_d4"), /sends a value to unknown pool "dice_d4"/u],
    [(sheet) => sheet.migrations[0].steps.push({ swap: "field" }), /is not a rename, a route or a live route/u],
  ]) {
    assert.throws(() => assertRulesetSheetMigrations(migrationsManifest, sheetWith(edit)), refusal);
  }
}

// A strike at somebody walking away is paid out of a budget the economy really declares.
assert.throws(
  () =>
    assertRulesetCombat(
      positionsManifest,
      positionsWith((combat) => (combat.opportunity.budget = "reaction")),
    ),
  /combat opportunity budget names unknown budget "reaction"/u,
);

// A weapon's distance is a number column of its own list, or the same number on every row.
assert.throws(
  () =>
    assertRulesetCombat(
      positionsManifest,
      positionsWith((combat) => (combat.attacks[0].reach = { column: "grip" })),
    ),
  /combat attacks "attacks" reach names unknown column "grip"/u,
);
assert.throws(
  () =>
    assertRulesetCombat(
      positionsManifest,
      positionsWith((combat) => (combat.attacks[0].reach = { column: "name" })),
    ),
  /combat attacks "attacks" reach must name a number column, not text/u,
);
assert.throws(
  () =>
    assertRulesetCombat(
      positionsManifest,
      positionsWith((combat) => (combat.attacks[0].reach = 5)),
    ),
  /combat attacks "attacks" reach names a column or a constant, not 5/u,
);
// An object carrying neither key is not a distance either: the column check lets an absent name
// through, so without its own guard `{}` would be read as a reach and pass.
for (const neither of [{}, { columns: "reach" }]) {
  assert.throws(
    () =>
      assertRulesetCombat(
        positionsManifest,
        positionsWith((combat) => (combat.attacks[0].reach = neither)),
      ),
    /combat attacks "attacks" reach names a column or a constant/u,
    JSON.stringify(neither),
  );
}
for (const fixed of [-1, 10001]) {
  assert.throws(
    () =>
      assertRulesetCombat(
        positionsManifest,
        positionsWith((combat) => (combat.attacks[0].reach = { const: fixed })),
      ),
    /combat attacks "attacks" reach const is a distance from 0 to 10000/u,
    String(fixed),
  );
}
assert.doesNotThrow(() =>
  assertRulesetCombat(
    positionsManifest,
    positionsWith((combat) => (combat.attacks[0].reach = { const: 5 })),
  ),
);
assert.throws(
  () =>
    assertRulesetCombat(
      positionsManifest,
      positionsWith((combat) => (combat.attacks[0].range = { long: { const: 60 } })),
    ),
  /combat attacks "attacks" range names the ordinary distance it is shot at/u,
);
// A range that is not a pair at all is refused by its own sentence: `null` would otherwise throw a
// TypeError, and an array or a number would be told it is missing a normal distance, which is the
// wrong complaint about a value that was never the right shape.
for (const wrong of [null, 30, [30, 120], "30/120"]) {
  assert.throws(
    () =>
      assertRulesetCombat(
        positionsManifest,
        positionsWith((combat) => (combat.attacks[0].range = wrong)),
      ),
    /combat attacks "attacks" range is an ordinary distance and an optional longer one/u,
    JSON.stringify(wrong),
  );
}
assert.throws(
  () =>
    assertRulesetCombat(
      positionsManifest,
      positionsWith((combat) => (combat.attacks[0].range = { normal: { const: 60 }, long: { const: 20 } })),
    ),
  /combat attacks "attacks" range long is at least the ordinary one/u,
);
// Two COLUMNS are the player's own two numbers, and the Engine reads a shorter long distance as no
// long distance rather than refusing the row, so this check does not either.
assert.doesNotThrow(() =>
  assertRulesetCombat(
    positionsManifest,
    positionsWith((combat) => (combat.attacks[0].range = { normal: { column: "bonus" }, long: { column: "bonus" } })),
  ),
);

// A creature's own distances. Both have been legal since 1.27 and need no `distance` beside them.
assert.equal(
  assertRulesetCreatures(
    creatureManifest,
    bestiaryDocument((block) => (block.actions[0].reach = 10)),
  ),
  1,
);
assert.equal(
  assertRulesetCreatures(
    creatureManifest,
    bestiaryDocument((block) => (block.actions[0].range = 60)),
  ),
  1,
);
for (const [what, edit, message] of [
  ["reach", (block) => (block.actions[0].reach = -5), /action "bite" has a reach of -5, not a distance from 0/u],
  ["reach", (block) => (block.actions[0].reach = 10001), /action "bite" has a reach of 10001/u],
  ["range", (block) => (block.actions[0].range = -1), /action "bite" has a range of -1, not a distance from 0/u],
  [
    "range",
    (block) => (block.actions[0].range = "far"),
    /action "bite" has a range of "far", not a distance or a pair/u,
  ],
  ["speed", (block) => (block.speed = -1), /has a speed of -1, not a distance from 0/u],
  ["speed", (block) => (block.speed = "quick"), /has a speed of "quick", not a distance from 0/u],
]) {
  assert.throws(() => assertRulesetCreatures(creatureManifest, bestiaryDocument(edit)), message, what);
}
// The shape an action lands in. A new key in a strict file, so it is the 1.28 gate as well, and the
// Engine's own closed set of three shapes is what it may name.
assert.equal(
  assertRulesetCreatures(
    positionsManifest,
    bestiaryDocument((block) => (block.actions[1].area = { shape: "cone", size: 15, friendlyFire: false })),
  ),
  1,
);
assert.throws(
  () =>
    assertRulesetCreatures(
      creatureManifest,
      bestiaryDocument((block) => (block.actions[1].area = { shape: "cone", size: 15 })),
    ),
  /lands in a shape and must declare capability API 1\.28 or newer/u,
);
for (const [what, area, message] of [
  [
    "a shape nobody draws",
    { shape: "wedge", size: 15 },
    /lands in the shape "wedge", which is not one the Engine draws/u,
  ],
  ["no shape at all", { size: 15 }, /lands in the shape undefined, which is not one the Engine draws/u],
  ["a size of nothing", { shape: "cone", size: 0 }, /has an area of 0, not a size above 0/u],
  ["a size below nothing", { shape: "cone", size: -5 }, /has an area of -5, not a size above 0/u],
  ["a size past the ceiling", { shape: "cone", size: 10001 }, /has an area of 10001, not a size above 0/u],
  ["a size that is not a number", { shape: "cone", size: "wide" }, /has an area of "wide", not a size above 0/u],
  [
    "a friendlyFire that is not a switch",
    { shape: "cone", size: 15, friendlyFire: "no" },
    /says friendlyFire is "no", not true or false/u,
  ],
  ["an area that is not a shape", "cone", /has an area of "cone", not a shape/u],
]) {
  assert.throws(
    () =>
      assertRulesetCreatures(
        positionsManifest,
        bestiaryDocument((block) => (block.actions[1].area = area)),
      ),
    message,
    what,
  );
}
// A sequence is a container, and a shape is one more thing the one budget would have done with
// nothing to say when. The actions it names carry their own.
assert.throws(
  () =>
    assertRulesetCreatures(
      positionsManifest,
      bestiaryDocument((block) => (block.actions[2].area = { shape: "cone", size: 15 })),
    ),
  /action "both" is a sequence, so it carries no area of its own/u,
);
// And the shipped bestiary never writes one.
{
  const bestiary = JSON.parse(shippedCatalogSources.get("catalogs/creatures.json"));
  assert.ok(
    bestiary.entries.every((entry) => entry.creature.actions.every((action) => !(action.sequence && action.area))),
    "no shipped multiattack carries a shape of its own",
  );
}

// ── Reaction moments (Capability API 1.33) ──
//
// An entry may name the moment its reaction waits for. `true` keeps meaning a reaction taken on no
// menu, so only the object is gated, and only what the Engine can open is allowed: harm, or being
// aimed at, pointed back at the source or at whoever the holder picks, and a cancel only on an aim.

const momentManifest = rulesetManifest({ capabilityApi: { major: 1, minor: 33 } });
const momentDocument = (reaction) => {
  const document = bestiaryDocument();
  document.catalogs.push({
    id: "tricks",
    label: "Tricks",
    feeds: ["spells"],
    entries: [
      {
        id: "sear",
        label: "Sear",
        rows: [{ list: "spells", values: { name: "Sear" } }],
        mechanics: { kind: "attack", reaction },
      },
    ],
  });
  return document;
};
// Spiritual Weapon lasts ten rounds and spends the declared bonus action (1.122).
{
  const spells = JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries;
  assert.deepEqual(spells.find((entry) => entry.id === "spiritual-weapon").mechanics.summons, {
    budget: "bonus",
    rounds: 10,
    move: 20,
    reach: 5,
  });
  const document = momentDocument(true);
  const mechanics = document.catalogs.at(-1).entries[0].mechanics;
  mechanics.summons = { budget: "action", rounds: 10, move: 20, reach: 5 };
  const manifest = rulesetManifest({ capabilityApi: { major: 1, minor: 122 } });
  assert.doesNotThrow(() => assertRulesetSheetHooks(manifest, document));
  assert.throws(
    () => assertRulesetSheetHooks({ ...manifest, capabilityApi: { major: 1, minor: 121 } }, document),
    /must declare capability API 1\.122/u,
  );
  for (const [key, value, refusal] of [
    ["kind", "heal", /needs kind "attack"/u],
    ["targets", "ally", /targeting enemies/u],
    ["budget", "missing", /undeclared budget/u],
    ["rounds", 0, /integer from 1 to 100/u],
    ["rounds", 101, /integer from 1 to 100/u],
    ["rounds", 1.5, /integer from 1 to 100/u],
    ["move", -1, /distance from 0/u],
    ["reach", "5", /distance from 0/u],
  ]) {
    const changed = structuredClone(document);
    const mechanics = changed.catalogs.at(-1).entries[0].mechanics;
    if (["kind", "targets"].includes(key)) mechanics[key] = value;
    else mechanics.summons[key] = value;
    assert.throws(() => assertRulesetSheetHooks(manifest, changed), refusal, key);
  }
  for (const rounds of [1, 100]) {
    mechanics.summons.rounds = rounds;
    assert.doesNotThrow(() => assertRulesetSheetHooks(manifest, document));
  }
  const source = new Map([["catalogs/tricks.json", JSON.stringify({ entries: document.catalogs.at(-1).entries })]]);
  document.catalogs.at(-1).asset = "catalogs/tricks.json";
  delete document.catalogs.at(-1).entries;
  assert.doesNotThrow(() => assertRulesetSheetHooks(manifest, document, source));
  assert.throws(
    () => assertRulesetSheetHooks({ ...manifest, capabilityApi: { major: 1, minor: 121 } }, document, source),
    /must declare capability API 1\.122/u,
  );
}

assert.equal(
  assertRulesetReactions(shippedManifest, parsedAsset, shippedCatalogSources),
  25,
  "the shipped package names twenty-five reaction entries (0.424.0 the tiefling's Hellish Rebuke) (Rogue and Hunter Uncanny Dodge): Hellish Rebuke's, Counterspell's, Shield's, Feather Fall's, Uncanny Dodge's, Protection's, Divine Smite's, Stunning Strike's, Quivering Palm's, Hurl Through Hell's, Open Hand Technique's three and Cutting Words', and Counterspell as a signature spell and Shield and Feather Fall by Spell Mastery (0.189.0), and from 0.205.0 Deflect Missiles and Slow Fall, and from 0.208.0 the Deflect Missiles throw back, and from 0.214.0 Retaliation, Giant Killer and Stand Against the Tide",
);
assert.equal(assertRulesetReactions(rulesetManifest(), momentDocument(true)), 0, "true needs no 1.33");

// Feather Fall answers a fall and lands the faller safely (0.53.0, 1.124).
{
  const spells = JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries;
  const featherFall = spells.find((entry) => entry.id === "feather-fall").mechanics;
  assert.deepEqual(featherFall.reaction, { on: "falls" });
  assert.equal(featherFall.targets, "ally");
  assert.deepEqual(featherFall.applies, [{ condition: "feather_fall", duration: { rounds: 10 } }]);
  assert.equal(parsedAsset.combat.conditions.find((entry) => entry.condition === "feather_fall").fallsSafely, true);
  const at = (minor) => rulesetManifest({ capabilityApi: { major: 1, minor } });
  assert.equal(assertRulesetReactions(at(124), momentDocument({ on: "falls" })), 1);
  assert.throws(() => assertRulesetReactions(at(123), momentDocument({ on: "falls" })), /1\.124/u);
  for (const extra of [
    { cancels: true },
    { blow: "melee" },
    { seesSource: true },
    { against: { catalogs: ["spells"] } },
  ]) {
    assert.throws(
      () => assertRulesetReactions(at(124), momentDocument({ on: "falls", ...extra })),
      /"falls" takes no cancels, blow, seesSource or against/u,
      Object.keys(extra)[0],
    );
  }
  assert.throws(
    () =>
      assertRulesetCombat({ ...shippedManifest, capabilityApi: { major: 1, minor: 123 } }, withoutNewerConditions(125)),
    /land a fall safely and must declare capability API 1\.124/u,
  );
}

// Sneak Attack's adjacent-ally branch holds only without disadvantage (0.54.0, 1.126).
{
  const features = JSON.parse(shippedCatalogSources.get("catalogs/features.json")).entries;
  const sneak = features.find((entry) => entry.id === "rogue-sneak-attack").mechanics.rider;
  assert.deepEqual(sneak.when, ["advantage", "ally-adjacent-no-disadvantage"]);
  assert.throws(
    () =>
      assertRulesetSheetHooks(
        { ...shippedManifest, capabilityApi: { major: 1, minor: 125 } },
        parsedAsset,
        shippedCatalogSources,
      ),
    /1\.126/u,
  );
}

// Charm endings and damage saves (0.54.0, 1.125), with the old charm combat behavior preserved.
{
  const spells = JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries;
  const spell = (id) => spells.find((entry) => entry.id === id).mechanics;
  const condition = (id) => parsedAsset.combat.conditions.find((entry) => entry.condition === id);
  const charmed = condition("charmed");
  for (const [id, extra] of [
    // Each counted as charmed (dominated since 0.312.0, the rest since 0.430.0).
    ["charmed_by_person", { endsWhen: ["harmed-by-source-side"], countsAs: ["charmed"] }],
    ["dominated", { saveWhenDamaged: true, controls: true, countsAs: ["charmed"] }],
    ["hypnotized", { endsWhen: ["damaged"], shakeOff: { budget: "action", reach: 5 }, countsAs: ["charmed"] }],
    ["charmed_by_creature", { endsWhen: ["harmed-by-source-side"], countsAs: ["charmed"] }],
  ]) {
    assert.deepEqual(condition(id), { ...charmed, condition: id, ...extra }, id);
    assert.ok(
      parsedAsset.sheet.live.conditions.some((entry) => entry.id === id && entry.label),
      id,
    );
  }
  assert.ok(parsedAsset.combat.economy.budgets.some((entry) => entry.id === condition("hypnotized").shakeOff.budget));
  assert.deepEqual(spell("charm-person").applies, [{ condition: "charmed_by_person", duration: { rounds: 600 } }]);
  assert.throws(
    () =>
      assertRulesetApplies(
        { ...shippedManifest, capabilityApi: { major: 1, minor: 128 } },
        parsedAsset,
        shippedCatalogSources,
      ),
    /save made when damaged and must declare capability API 1\.129/u,
  );
  for (const id of ["dominate-person", "dominate-beast", "dominate-monster"]) {
    // With advantage when fought since 0.309.0.
    assert.deepEqual(spell(id).save, { save: "wis_save", onSuccess: "negates", advantageIfFought: true }, id);
    assert.deepEqual(
      spell(id).applies,
      [
        {
          condition: "dominated",
          duration: { rounds: id === "dominate-monster" ? 600 : 10 },
          saveEnds: { save: "wis_save", at: "damaged" },
        },
      ],
      id,
    );
  }
  assert.deepEqual(spell("hypnotic-pattern").applies, [
    { condition: "hypnotized", duration: { rounds: 10 } },
    { condition: "incapacitated", duration: { rounds: 10 }, endsWith: "hypnotized" },
  ]);
  const creatures = JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries;
  assert.deepEqual(
    creatures.flatMap((entry) =>
      entry.creature.actions
        .filter((action) => action.applies?.some((one) => one.condition === "charmed_by_creature"))
        .map((action) => [entry.id, action.id]),
    ),
    [
      ["dryad", "fey_charm"],
      ["vampire", "charm"],
      ["vampire-bat-form", "charm"],
    ],
  );
  // 0.400.0: the aboleth enslaves (enslaved) and the succubus's Charm is a domination of humanoids.
  for (const [id, action, condition] of [
    ["aboleth", "enslave", "enslaved"],
    ["succubusincubus", "charm", "dominated"],
  ]) {
    assert.equal(
      creatures.find((entry) => entry.id === id).creature.actions.find((entry) => entry.id === action).applies[0]
        .condition,
      condition,
      id,
    );
  }

  // The harpy's song lures since 0.313.0: charmed and drawn in, as harpy_lured.
  assert.equal(
    creatures.find((entry) => entry.id === "harpy").creature.actions.find((entry) => entry.id === "luring_song")
      .applies[0].condition,
    "harpy_lured",
  );

  const at = (minor) => rulesetManifest({ capabilityApi: { major: 1, minor } });
  const ending = (keys) => combatDocument({ ...combatBlock, conditions: [{ condition: "prone", ...keys }] });
  for (const keys of [
    { endsWhen: ["damaged"] },
    { endsWhen: ["harmed-by-source-side"] },
    { endsWhen: ["damaged", "harmed-by-source-side"] },
    { saveWhenDamaged: true },
    { shakeOff: { budget: "action" } },
    { shakeOff: { budget: "action", reach: 5 } },
  ]) {
    assert.equal(assertRulesetCombat(at(125), ending(keys)), true, JSON.stringify(keys));
    assert.throws(
      () => assertRulesetCombat(at(124), ending(keys)),
      /condition ending rules.*1\.125/u,
      JSON.stringify(keys),
    );
  }
  for (const endsWhen of [[], ["hurt"], ["damaged", "damaged"], "damaged", null]) {
    assert.throws(() => assertRulesetCombat(at(125), ending({ endsWhen })), /endsWhen must be 1 to 6 of/u);
  }
  for (const saveWhenDamaged of [false, null, 1]) {
    assert.throws(() => assertRulesetCombat(at(125), ending({ saveWhenDamaged })), /saveWhenDamaged must be true/u);
  }
  for (const [shakeOff, message] of [
    [{ budget: "missing" }, /shakeOff names unknown budget/u],
    [{}, /shakeOff names unknown budget/u],
    [null, /shakeOff must be/u],
    [[], /shakeOff must be/u],
    [{ budget: "action", other: 5 }, /shakeOff must be/u],
    ...[0, -5, "5", null, Infinity, NaN].map((reach) => [
      { budget: "action", reach },
      /reach must be a positive number/u,
    ]),
  ]) {
    assert.throws(() => assertRulesetCombat(at(125), ending({ shakeOff })), message);
  }
}

// Hearing eligibility (1.127), on shipped entries and on both inline and asset catalogs.
{
  const at = (minor) => rulesetManifest({ capabilityApi: { major: 1, minor } });
  assert.ok(shippedManifest.capabilityApi.minor >= 127);
  assert.deepEqual(parsedAsset.combat.conditions.find((entry) => entry.condition === "deafened").lacks, ["hearing"]);
  const spells = JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries;
  assert.deepEqual(
    spells.filter((entry) => entry.mechanics?.needs).map((entry) => [entry.id, entry.mechanics?.needs]),
    // Hypnotic Pattern is seen (0.430.0).
    [
      "compulsion",
      "divine-word",
      "enthrall",
      "hypnotic-pattern",
      "mass-suggestion",
      "suggestion",
      "vicious-mockery",
    ].map((id) => [id, id === "hypnotic-pattern" ? ["sight"] : ["hearing"]]),
  );
  for (const id of ["command-approach", "power-word-kill", "power-word-stun", "shatter", "message", "tongues"]) {
    assert.equal(spells.find((entry) => entry.id === id).mechanics.needs, undefined, id);
  }
  const creatures = JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries;
  assert.deepEqual(
    creatures.flatMap((entry) =>
      entry.creature.actions.filter((action) => action.needs).map((action) => [entry.id, action.id, action.needs]),
    ),
    [
      // The androsphinx's three roars since 0.305.0, each heard.
      ["androsphinx", "roar_1", ["hearing"]],
      ["androsphinx", "roar_2", ["hearing"]],
      ["androsphinx", "roar_3", ["hearing"]],
      ["chain-devil", "unnerving_mask", ["sight"]],
      ["cloaker", "moan", ["hearing"]],
      // The gazes and charms that need the target's sight (0.430.0).
      ["dryad", "fey_charm", ["sight"]],
      // 0.399.0's bursts: "each creature within 60 feet of the ghost that can see it".
      ["ghost", "horrifying_visage", ["sight"]],
      ["harpy", "luring_song", ["hearing"]],
      ["mummy", "dreadful_glare", ["sight"]],
      ["mummy-lord", "dreadful_glare", ["sight"]],
      ["mummy-lord", "attack_dreadful_glare", ["sight"]],
      ["mummy-lord", "blasphemous_word", ["hearing"]],
      ["nalfeshnee", "horror_nimbus", ["sight"]],
      // The sea hag's Death Glare since 0.303.0: "If the target can see the hag".
      ["sea-hag", "death_glare", ["sight"]],
      ["solar", "blinding_gaze", ["sight"]],
      ["vampire", "charm", ["sight"]],
      ["vampire-bat-form", "charm", ["sight"]],
      ["vrock", "stunning_screech", ["hearing"]],
    ],
  );
  assert.doesNotThrow(() => assertRulesetSheetHooks(shippedManifest, parsedAsset, shippedCatalogSources));
  assert.doesNotThrow(() => assertRulesetCreatures(shippedManifest, parsedAsset, shippedCatalogSources));
  assert.doesNotThrow(() => assertRulesetItems(shippedManifest, parsedAsset, shippedCatalogSources));

  const withHearing = (document) => ({
    ...document,
    combat: { ...document.combat, conditions: [{ condition: "prone", lacks: ["hearing"] }] },
  });
  const condition = (lacks) => combatDocument({ ...combatBlock, conditions: [{ condition: "prone", lacks }] });
  // These are validator fixtures, not shipped SRD entries: neither is in the supplied source.
  const whispers = (needs) => {
    const document = withHearing(momentDocument(false));
    const entry = document.catalogs.at(-1).entries[0];
    entry.id = "dissonant-whispers";
    entry.label = "Dissonant Whispers";
    entry.mechanics = { kind: "attack", needs, amount: { dice: "3d6" }, damageType: "psychic" };
    return document;
  };
  const wail = (needs) => {
    const document = withHearing(
      bestiaryDocument((block) => {
        block.actions = [{ ...block.actions[1], id: "wail", name: "Wail", needs }];
      }),
    );
    document.catalogs[0].entries[0].id = "banshee";
    document.catalogs[0].entries[0].label = "Banshee";
    return document;
  };
  for (const [make, check] of [
    [condition, assertRulesetCombat],
    [whispers, assertRulesetSheetHooks],
    [wail, assertRulesetCreatures],
  ]) {
    assert.doesNotThrow(() => check(at(127), make(["hearing"])));
    assert.throws(() => check(at(126), make(["hearing"])), /(?:lacks|needs).*1\.127/u);
    for (const words of [
      [],
      null,
      "hearing",
      ["Hearing"],
      ["hear-ing"],
      ["1hearing"],
      [1],
      ["hearing", "hearing"],
      ["a", "b", "c", "d", "e"],
    ]) {
      assert.throws(() => check(at(127), make(words)), /list of 1 to 4 lowercase sense words, without repeats/u);
    }
  }
  // Four distinct words, including an underscore, are legal and need matching declarations.
  const words = ["hearing", "sight", "smell", "tremor_sense"];
  assert.doesNotThrow(() => assertRulesetCombat(at(127), condition(words)));
  for (const [make, check] of [
    [whispers, assertRulesetSheetHooks],
    [wail, assertRulesetCreatures],
  ]) {
    const document = make(words);
    document.combat.conditions[0].lacks = words;
    assert.doesNotThrow(() => check(at(127), document));
    assert.throws(() => check(at(127), make(["hearin"])), /needs sense "hearin" that no condition lacks/u);
    const catalog = document.catalogs.at(-1);
    const sources = new Map([["catalogs/senses.json", JSON.stringify({ entries: catalog.entries })]]);
    delete catalog.entries;
    catalog.asset = "catalogs/senses.json";
    assert.doesNotThrow(() => check(at(127), document, sources));
    assert.throws(() => check(at(126), document, sources), /needs.*1\.127/u);
  }
  // 1.628: an item use may carry needs, checked against the sheet's senses with the newest (0.295.0).
  assert.doesNotThrow(() =>
    assertRulesetItems(
      at(127),
      itemDocument((document) => {
        document.catalogs[0].entries[0].item.use = { kind: "heal", needs: ["hearing"] };
      }),
    ),
  );
}

// A save that ignores cover (Sacred Flame's) is 1.74's, on a spell, its scroll and its casters alike.
assert.equal(
  assertRulesetCoverlessSaves(shippedManifest, parsedAsset, shippedCatalogSources),
  2,
  "the shipped package has two: Sacred Flame and its spell scroll",
);
const coverless = (ignoresCover) => {
  const document = momentDocument(true);
  document.catalogs.at(-1).entries[0].mechanics.save = { save: "dex_save", onSuccess: "negates", ignoresCover };
  return document;
};
assert.equal(
  assertRulesetCoverlessSaves(rulesetManifest({ capabilityApi: { major: 1, minor: 74 } }), coverless(true)),
  1,
);
assert.throws(
  () => assertRulesetCoverlessSaves(rulesetManifest({ capabilityApi: { major: 1, minor: 72 } }), coverless(true)),
  /entry "sear" has a save that ignores cover and must declare capability API 1\.74 or newer/u,
);
assert.throws(
  () => assertRulesetCoverlessSaves(rulesetManifest({ capabilityApi: { major: 1, minor: 74 } }), coverless(false)),
  /entry "sear" has a save whose ignoresCover is true or left out/u,
);
assert.throws(
  () =>
    assertRulesetReactions(
      rulesetManifest({ capabilityApi: { major: 1, minor: 32 } }),
      momentDocument({ on: "harmed" }),
    ),
  /entry "sear" names the moment it waits for and must declare capability API 1\.33 or newer/u,
);
for (const reaction of [
  { on: "harmed" },
  { on: "harmed", at: "source" },
  { on: "aimed", at: "chosen" },
  { on: "aimed", cancels: true },
]) {
  assert.equal(assertRulesetReactions(momentManifest, momentDocument(reaction)), 1, JSON.stringify(reaction));
}
for (const [reaction, message] of [
  [null, /has a reaction of null, not true or a moment/u],
  ["soon", /has a reaction of "soon", not true or a moment/u],
  [[], /has a reaction of \[\], not true or a moment/u],
  [{ on: "harmed", why: "spite" }, /reaction has an unknown key "why"/u],
  [{ on: "fallen" }, /waits for "fallen", not one of aimed, hit, harmed, used/u],
  [{ at: "source" }, /waits for undefined, not one of aimed, hit, harmed, used/u],
  [{ on: "harmed", at: "everyone" }, /is pointed at "everyone", not one of source, chosen/u],
  [{ on: "aimed", cancels: false }, /reaction cancels must be true when it is given/u],
  [
    { on: "harmed", cancels: true },
    /cancels a moment that has already happened: only an "aimed" or "used" reaction cancels/u,
  ],
]) {
  assert.throws(
    () => assertRulesetReactions(momentManifest, momentDocument(reaction)),
    message,
    JSON.stringify(reaction),
  );
}
// A catalog asset is read too, and a creature's printed reactions are nothing this gate reads.
{
  const document = momentDocument(true);
  const tricks = document.catalogs.pop();
  document.catalogs.push({ ...tricks, entries: undefined, asset: "catalogs/tricks.json" });
  const sources = new Map([
    [
      "catalogs/tricks.json",
      JSON.stringify({ entries: [{ ...tricks.entries[0], mechanics: { reaction: { on: "near" } } }] }),
    ],
  ]);
  assert.throws(() => assertRulesetReactions(momentManifest, document, sources), /waits for "near"/u);
}

// ── Creatures written as sheets (Capability API 1.34) ──
//
// A bestiary creature may carry a sheet in the ruleset's own terms, which a fight builds exactly as it
// builds a party member. The sheet then says every number once, so none of the six it replaces may
// also be given, and it is held to what the ruleset's own sheet declares, value by value.

const sheetManifest = rulesetManifest({ capabilityApi: { major: 1, minor: 34 } });
const sheetRuleset = {
  ...combatSheet,
  abilities: [{ id: "str", label: "Strength", min: 1, max: 30, default: 10 }],
  skills: [{ id: "athletics", label: "Athletics", ability: "str" }],
  saveTiers: ["none", "proficient"],
  bonusRange: { min: -5, max: 5 },
  fields: [
    { id: "ac", label: "Armor Class", type: "number", min: 0, max: 30 },
    { id: "speed", label: "Speed", type: "number", min: 0, max: 120 },
    { id: "mood", label: "Mood", type: "text", maxLength: 10 },
    { id: "calling", label: "Calling", type: "enum", values: ["none", "wizard"] },
  ],
  lists: [
    ...combatSheet.lists.filter((list) => list.id !== "spells"),
    {
      id: "spells",
      label: "Spells",
      maxItems: 2,
      columns: [
        { id: "name", label: "Name", type: "text", maxLength: 80, required: true },
        { id: "level", label: "Level", type: "number", min: 0, max: 9 },
        { id: "prepared", label: "Prepared", type: "boolean" },
      ],
    },
  ],
};
const casterSheet = () => ({
  abilities: { str: 14 },
  skills: { athletics: "expertise" },
  saves: { str_save: "proficient" },
  bonuses: { athletics: -1, str_save: 2 },
  fields: { ac: 15, speed: 30, mood: "grim", calling: "wizard" },
  lists: { spells: [{ name: "Sear", level: 1, prepared: true, _catalog: "tricks/sear" }] },
});
const sheetDocument = (edit = () => {}, sheet = casterSheet()) => {
  const document = momentDocument(true);
  document.sheet = sheetRuleset;
  document.resolution = { proficiencyTiers: [{ id: "none" }, { id: "proficient" }, { id: "expertise" }] };
  const block = document.catalogs[0].entries[0].creature;
  for (const key of ["health", "defense", "initiativeModifier", "speed", "abilities", "saves"]) delete block[key];
  block.sheet = sheet;
  edit(block);
  return document;
};

assert.equal(assertRulesetCreatures(sheetManifest, sheetDocument()), 1);
assert.throws(
  () => assertRulesetCreatures(momentManifest, sheetDocument()),
  /entry "hound" carries a sheet and must declare capability API 1\.34 or newer/u,
);
// Its lists are what it does, so actions of its own are optional; the cap still holds.
assert.equal(
  assertRulesetCreatures(
    sheetManifest,
    sheetDocument((block) => (block.actions = [])),
  ),
  1,
);
assert.equal(
  assertRulesetCreatures(
    sheetManifest,
    sheetDocument((block) => delete block.actions),
  ),
  1,
);
assert.throws(
  () =>
    assertRulesetCreatures(
      sheetManifest,
      sheetDocument((block) => (block.actions = 7)),
    ),
  /carries 0 to \d+ actions, not undefined/u,
);
// And a plain creature still needs its first one.
assert.throws(
  () =>
    assertRulesetCreatures(
      creatureManifest,
      bestiaryDocument((block) => (block.actions = [])),
    ),
  /carries 1 to \d+ actions, not 0/u,
);
for (const key of ["health", "defense", "initiativeModifier", "speed", "abilities", "saves"]) {
  assert.throws(
    () =>
      assertRulesetCreatures(
        sheetManifest,
        sheetDocument((block) => (block[key] = creature()[key] ?? 1)),
      ),
    new RegExp(`carries a sheet, which says its ${key}, so it does not also give one`, "u"),
    key,
  );
}
for (const [what, edit, message] of [
  ["a key", (sheet) => (sheet.feats = {}), /sheet has an unknown key "feats"/u],
  ["an ability", (sheet) => (sheet.abilities = { luck: 3 }), /sheet names unknown ability "luck"/u],
  ["a score", (sheet) => (sheet.abilities = { str: 31 }), /sheet sets str to 31, outside 1 to 30/u],
  ["a fraction", (sheet) => (sheet.abilities = { str: 12.5 }), /sheet sets str to 12\.5, outside 1 to 30/u],
  ["a skill", (sheet) => (sheet.skills = { juggling: "proficient" }), /sheet names unknown skill "juggling"/u],
  ["a save", (sheet) => (sheet.saves = { luck_save: "proficient" }), /sheet names unknown save "luck_save"/u],
  [
    "a narrowed tier",
    (sheet) => (sheet.saves = { str_save: "expertise" }),
    /sheet sets str_save to "expertise", not a tier offered for saves/u,
  ],
  ["a tier", (sheet) => (sheet.skills = { athletics: "legend" }), /sets athletics to "legend", not a tier offered/u],
  ["a bonus", (sheet) => (sheet.bonuses = { luck: 1 }), /gives a bonus to unknown skill or save "luck"/u],
  ["a large bonus", (sheet) => (sheet.bonuses = { athletics: 6 }), /gives athletics a bonus of 6, outside -5 to 5/u],
  ["a field", (sheet) => (sheet.fields = { hue: 1 }), /sheet names unknown field "hue"/u],
  ["a number", (sheet) => (sheet.fields = { ac: "15" }), /sheet field "ac" takes a number, not "15"/u],
  ["a range", (sheet) => (sheet.fields = { ac: 31 }), /sheet field "ac" is 31, outside 0 to 30/u],
  ["a whole number", (sheet) => (sheet.fields = { ac: 1.5 }), /sheet field "ac" takes a whole number, not 1\.5/u],
  ["a length", (sheet) => (sheet.fields = { mood: "grimly jolly" }), /field "mood" is longer than 10 characters/u],
  [
    "a value",
    (sheet) => (sheet.fields = { calling: "bard" }),
    /field "calling" takes one of none, wizard, not "bard"/u,
  ],
  ["a list", (sheet) => (sheet.lists = { feats: [] }), /sheet names unknown list "feats"/u],
  [
    "too many rows",
    (sheet) => (sheet.lists = { spells: [{ name: "A" }, { name: "B" }, { name: "C" }] }),
    /sheet list "spells" holds more than its 2 rows/u,
  ],
  ["a column", (sheet) => (sheet.lists = { spells: [{ name: "A", colour: "red" }] }), /sets unknown column "colour"/u],
  ["a cell", (sheet) => (sheet.lists = { spells: [{ name: "A", level: "one" }] }), /column "level" takes a number/u],
  ["a required cell", (sheet) => (sheet.lists = { spells: [{ level: 1 }] }), /leaves required column "name" empty/u],
  ["a mark", (sheet) => (sheet.lists.spells[0]._catalog = "sear"), /names "sear", not <catalog>\/<entry>/u],
  [
    "a catalog",
    (sheet) => (sheet.lists.spells[0]._catalog = "beasts/hound"),
    /names "beasts\/hound", and no catalog of that name feeds "spells"/u,
  ],
  [
    "an entry",
    (sheet) => (sheet.lists.spells[0]._catalog = "tricks/zap"),
    /names "tricks\/zap", which that catalog does not hold/u,
  ],
]) {
  const sheet = casterSheet();
  edit(sheet);
  assert.throws(
    () =>
      assertRulesetCreatures(
        sheetManifest,
        sheetDocument(() => {}, sheet),
      ),
    message,
    what,
  );
}
// A picked row naming an entry of a catalog FILE is checked against the file, which the Engine
// cannot do from the ruleset alone.
{
  const document = sheetDocument();
  const tricks = document.catalogs.pop();
  document.catalogs.push({ ...tricks, entries: undefined, asset: "catalogs/tricks.json" });
  const sources = new Map([["catalogs/tricks.json", JSON.stringify({ entries: tricks.entries })]]);
  assert.equal(assertRulesetCreatures(sheetManifest, document, sources), 1);
  document.catalogs[0].entries[0].creature.sheet.lists.spells[0]._catalog = "tricks/zap";
  assert.throws(() => assertRulesetCreatures(sheetManifest, document, sources), /which that catalog does not hold/u);
}
// Text is held only to a length the ruleset declares, exactly as the Engine holds a row.
{
  const document = sheetDocument();
  document.sheet = {
    ...sheetRuleset,
    fields: sheetRuleset.fields.map((field) =>
      field.id === "mood" ? { id: "mood", label: "Mood", type: "text" } : field,
    ),
  };
  document.catalogs[0].entries[0].creature.sheet.fields.mood = "grimly jolly";
  assert.equal(assertRulesetCreatures(sheetManifest, document), 1);
}
// The shipped casters: every one a sheet, and every spell row one of the package's own spells.
{
  const bestiary = JSON.parse(srdCatalogSources.get("catalogs/creatures.json"));
  const casters = bestiary.entries.filter((entry) => entry.creature.sheet?.lists?.spells);
  assert.equal(casters.length, 12, "the twelve slot casters of the SRD are sheets");
  // SRD 5.1 prints the Priest's Religion as +4 where the fixture says +5: Intelligence 13 and a 5th
  // level proficiency of 3 make exactly 4, so the corrected sheet carries no bonus there.
  const priest = casters.find((entry) => entry.id === "priest").creature.sheet;
  assert.equal(priest.skills.religion, "proficient");
  assert.equal(priest.bonuses.religion, undefined, "the Priest's Religion is the printed +4");
  for (const entry of casters) {
    assert.ok(entry.creature.sheet.lists.spells.length > 0, `${entry.id} prepares spells`);
    assert.ok(
      entry.creature.sheet.lists.spells.every((row) => row._catalog?.startsWith("spells/")),
      `${entry.id}'s spells are the package's own`,
    );
  }
}

// Creature spell menus use catalog ids, printed daily counts and explicit casting levels (1.123).
{
  const bestiary = JSON.parse(shippedCatalogSources.get("catalogs/creatures.json"));
  const casting = (id) => bestiary.entries.find((entry) => entry.id === id).creature.spellcasting;
  const spell = (id, name) => casting(id).spells.find((entry) => entry.entry === `spells/${name}`);
  // And the oni in its humanoid form (0.400.0).
  assert.equal(bestiary.entries.filter((entry) => entry.creature.spellcasting).length, 27);
  // A slot caster casts its slots from its sheet; its menu holds only what it casts at will outside them.
  assert.equal(casting("lich"), undefined, "the lich casts from its sheet");
  assert.deepEqual(spell("green-hag", "vicious-mockery"), { entry: "spells/vicious-mockery" });
  // The coven's spells spend its shared slots since 0.297.0, at the coven's DC 13.
  assert.deepEqual(spell("green-hag", "hold-person"), {
    entry: "spells/hold-person",
    level: 2,
    coven: true,
    saveDifficulty: 13,
  });
  assert.deepEqual(spell("green-hag", "scrying"), {
    entry: "spells/scrying",
    level: 5,
    coven: true,
    saveDifficulty: 13,
  });
  for (const id of ["green-hag", "night-hag", "sea-hag"]) {
    assert.deepEqual(casting(id).coven, { id: "hag_coven", size: 3, within: 30 });
    assert.equal(casting(id).spells.filter((entry) => entry.coven).length, 11);
    assert.ok(spell(id, "eyebite")?.coven, 'the source\'s "eye bite" is Eyebite');
    // The existing eight-trait cap already leaves the night hag's coven prose out.
    if (id !== "night-hag") {
      assert.ok(
        bestiary.entries
          .find((entry) => entry.id === id)
          .creature.traits.some((trait) => trait.name === "Shared Spellcasting (Coven Only)"),
      );
    }
  }
  assert.equal(casting("green-hag").saveDifficulty, 12, "the printed innate DC takes precedence");
  assert.equal(casting("green-hag").toHit, 5, "the coven supplies the missing spell attack bonus");
  assert.equal(casting("sea-hag").saveDifficulty, 13, "a coven-only hag uses its Intelligence formula");
  // Since 0.80.0 a spell carries the components its trait needs where they differ (1.181), read apart here.
  const bare = (entry) => entry && Object.fromEntries(Object.entries(entry).filter(([key]) => key !== "components"));
  for (const [id, name] of [
    ["dust-mephit", "sleep"],
    ["ice-mephit", "fog-cloud"],
    ["magma-mephit", "heat-metal"],
    ["steam-mephit", "blur"],
  ]) {
    assert.deepEqual(bare(spell(id, name)), { entry: `spells/${name}`, uses: { per: "day", count: 1 } });
  }
  assert.deepEqual(bare(spell("lamia", "geas")), { entry: "spells/geas", uses: { per: "day", count: 1 } });
  assert.deepEqual(bare(spell("deep-gnome-svirfneblin", "nondetection")), { entry: "spells/nondetection" });
  assert.equal(spell("archmage", "mage-armor"), undefined, "the archmage's slots are its sheet's");
  assert.deepEqual(bare(spell("archmage", "disguise-self")), { entry: "spells/disguise-self" });
  // 0.84.0: Dispel Evil and Good rolls no attack, so the planetar's spells need no attack bonus at all.
  assert.equal(casting("planetar").toHit, undefined, "no spell of the planetar's rolls an attack");
}

// Validate the trust boundary using a small spell catalog, independent of the SRD generator.
{
  const manifest = rulesetManifest({ capabilityApi: { major: 1, minor: 123 } });
  const document = (edit = () => {}) => {
    const result = bestiaryDocument((block) => {
      block.actions = [];
      block.spellcasting = {
        saveDifficulty: 13,
        toHit: 5,
        coven: { id: "test_coven", size: 3, within: 30 },
        spells: [
          { entry: "spells/flame", uses: { per: "day", count: 2 }, level: 1, coven: true },
          { entry: "spells/ray" },
        ],
      };
      edit(block.spellcasting, block);
    });
    result.catalogs.push({
      id: "spells",
      label: "Spells",
      feeds: ["spells"],
      entries: [
        { id: "flame", mechanics: { save: { save: "str_save", onSuccess: "half" } } },
        { id: "ray", mechanics: { attackRoll: true } },
      ],
    });
    return result;
  };
  assert.equal(assertRulesetCreatures(manifest, document()), 1, "spellcasting permits empty actions");
  assert.equal(
    assertRulesetCreatures(
      manifest,
      document((casting, block) => {
        delete block.actions;
        casting.spells[0].uses.per = "encounter";
      }),
    ),
    1,
  );
  assert.throws(
    () => assertRulesetCreatures({ ...manifest, capabilityApi: { major: 1, minor: 122 } }, document()),
    /spellcasting and must declare capability API 1\.123/u,
  );
  for (const [edit, message] of [
    [
      (casting) => {
        casting.spells[0].entry = "spells/unknown";
      },
      /no existing spells-catalog entry/u,
    ],
    [
      (casting) => {
        casting.spells[0].entry = "beasts/hound";
      },
      /no existing spells-catalog entry/u,
    ],
    [
      (casting) => {
        delete casting.coven;
      },
      /needs a coven block/u,
    ],
    [
      (casting) => {
        casting.spells[0].uses.count = 0;
      },
      /count >= 1/u,
    ],
    [
      (casting) => {
        casting.spells[0].uses.count = 1.5;
      },
      /count >= 1/u,
    ],
    [
      (casting) => {
        casting.spells[0].uses.per = "week";
      },
      /per day or encounter/u,
    ],
    [
      (casting) => {
        casting.coven.size = 1;
      },
      /size must be 2 to 6/u,
    ],
    [
      (casting) => {
        casting.coven.size = 7;
      },
      /size must be 2 to 6/u,
    ],
    [
      (casting) => {
        casting.coven.within = 0;
      },
      /positive distance/u,
    ],
    [
      (casting) => {
        delete casting.saveDifficulty;
      },
      /needs saveDifficulty without a sheet/u,
    ],
    [
      (casting) => {
        delete casting.toHit;
      },
      /needs toHit without a sheet/u,
    ],
    [
      (casting) => {
        casting.toHit = 1.5;
      },
      /toHit must be a whole number/u,
    ],
    [
      (casting) => {
        casting.spells[0].level = 0;
      },
      /level must be 1 to 9/u,
    ],
    [
      (casting) => {
        casting.spells = [];
      },
      /nonempty spells array/u,
    ],
  ]) {
    assert.throws(() => assertRulesetCreatures(manifest, document(edit)), message);
  }
  // Asset-backed spell catalogs follow the same reference and mechanics checks.
  const external = document();
  const entries = external.catalogs[1].entries;
  delete external.catalogs[1].entries;
  external.catalogs[1].asset = "catalogs/test-spells.json";
  const sources = new Map([["catalogs/test-spells.json", JSON.stringify({ catalog: "spells", entries })]]);
  assert.equal(assertRulesetCreatures(manifest, external, sources), 1);
}

// A shape and a target count live on the same action on purpose: the count is what a fight WITHOUT
// a board reads, and the shape is what one with a board draws.
assert.equal(
  assertRulesetCreatures(
    positionsManifest,
    bestiaryDocument((block) => {
      block.actions[1].area = { shape: "burst", size: 20 };
      block.actions[1].targetCount = 3;
    }),
  ),
  1,
);
// And the package as committed ships both on the same actions.
{
  const bestiary = JSON.parse(shippedCatalogSources.get("catalogs/creatures.json"));
  const shaped = bestiary.entries.flatMap((entry) => entry.creature.actions.filter((action) => action.area));
  assert.ok(shaped.length > 50, "the shipped bestiary must carry the shapes the SRD prints");
  assert.ok(
    shaped.every((action) => RULESET_AREA_SHAPES_FOR_TEST.includes(action.area.shape)),
    "every shipped creature area is one of the shapes the Engine draws",
  );
  assert.ok(
    shaped.every((action) => action.targetCount !== undefined),
    "and keeps the count a fight with no board reads",
  );
}

// A range written as a PAIR is the 1.28 key: an older Engine refuses the whole catalog file holding it.
assert.throws(
  () =>
    assertRulesetCreatures(
      creatureManifest,
      bestiaryDocument((block) => (block.actions[0].range = { normal: 30, long: 120 })),
    ),
  /writes its range as a pair and must declare capability API 1\.28 or newer/u,
);
assert.equal(
  assertRulesetCreatures(
    positionsManifest,
    bestiaryDocument((block) => (block.actions[0].range = { normal: 30, long: 120 })),
  ),
  1,
);
assert.throws(
  () =>
    assertRulesetCreatures(
      positionsManifest,
      bestiaryDocument((block) => (block.actions[0].range = { normal: 120, long: 30 })),
    ),
  /action "bite" has a long range below its ordinary one/u,
);

// ── Contests (1.43), counters (1.44), condition numbers (1.45) and the moment after a hit (1.46) ──
//
// Each key is gated at the Engine that reads it and checked the way that Engine checks it, so a
// package carrying one is refused here rather than at install, where the whole strict file goes.

const apiManifest = (minor) => rulesetManifest({ capabilityApi: { major: 1, minor } });
const combatAt = (minor, edit) => () => assertRulesetCombat(apiManifest(minor), combatWith(edit));

// Contests and the checks they read.
const withContests = (combat) => {
  combat.checks = [{ id: "might", label: "Athletics", value: { abilityMod: "str" } }];
  combat.contests = [
    {
      id: "grab",
      label: "Grab",
      budget: "action",
      strike: true,
      attacker: { checks: ["might"] },
      defender: { checks: ["might"] },
      onWin: { applies: [{ condition: "prone" }] },
    },
    {
      id: "slip",
      label: "Slip free",
      budget: "action",
      attacker: { checks: ["might"] },
      defender: { checks: ["might"] },
      from: { holding: "stunned" },
      onWin: { ends: [{ condition: "stunned", on: "actor" }] },
    },
  ];
};
assert.doesNotThrow(combatAt(43, withContests));
assert.throws(combatAt(42, withContests), /has contests in its fights and must declare capability API 1\.43 or newer/u);
for (const [edit, message] of [
  [
    (combat) => (combat.checks[0].value = { skillMod: "stealth" }),
    /check "might" value names unknown skill "stealth"/u,
  ],
  [(combat) => combat.checks.push({ ...combat.checks[0] }), /repeats the check "might"/u],
  [(combat) => (combat.contests[0].budget = "reaction"), /contest "grab" budget names unknown budget "reaction"/u],
  [(combat) => (combat.contests[0].attacker.checks = ["agility"]), /"grab" attacker names unknown check "agility"/u],
  [(combat) => (combat.contests[0].defender.checks = ["might", "might"]), /"grab" defender repeats the check "might"/u],
  [(combat) => (combat.contests[0].onWin = {}), /"grab" onWin applies, ends, pushes or stabilizes something/u],
  [
    (combat) => (combat.contests[0].onWin.applies = [{ condition: "dazed" }]),
    /onWin applies names unknown condition "dazed"/u,
  ],
  [
    (combat) => (combat.contests[1].onWin.applies = [{ condition: "stunned" }]),
    /"slip" breaks free of "stunned", so it cannot also apply it/u,
  ],
  [
    (combat) => (combat.contests[1].onWin.ends[0].on = "everyone"),
    /ends "stunned" on "everyone", not the actor or the target/u,
  ],
  [
    (combat) => (combat.contests[0].onWin.push = 5),
    /"grab" push is measured in cells, so the block declares "distance" too/u,
  ],
  [
    (combat) => (combat.contests[0].reach = 10),
    /"grab" reach is measured in cells, so the block declares "distance" too/u,
  ],
  [(combat) => (combat.contests[0].ties = "nobody"), /"grab" gives a tie to "nobody"/u],
]) {
  assert.throws(
    combatAt(43, (combat) => {
      withContests(combat);
      edit(combat);
    }),
    message,
    String(message),
  );
}

// Numbers a condition changes, levels of a track, and the effects on a holder's own checks.
const numbersDocument = (edit) => {
  const document = combatWith((combat) => {
    combat.conditions.push({
      condition: "stunned",
      effects: ["own-checks-disadvantage"],
      modifiers: [
        { to: "defense", flat: -2 },
        { to: "attacks", dice: "1d4", minus: true },
        { to: "speed", times: 0.5 },
      ],
    });
    combat.levels = [
      { track: "fatigue", at: 1, effects: ["own-attacks-disadvantage"] },
      { track: "fatigue", at: 2, modifiers: [{ to: "speed", times: 0.5 }] },
    ];
    edit(combat);
  });
  document.sheet = structuredClone(combatSheet);
  document.sheet.live.tracks.push({ id: "fatigue", max: 6 }, { id: "harm", boxes: true });
  return document;
};
const numbersAt =
  (minor, edit = () => {}) =>
  () =>
    assertRulesetCombat(apiManifest(minor), numbersDocument(edit));
const numbersMessage = /conditions that change numbers or count levels and must declare capability API 1\.45 or newer/u;
assert.doesNotThrow(numbersAt(45));
assert.throws(numbersAt(44), numbersMessage);
// Any one of them asks for 1.45 on its own.
assert.throws(
  combatAt(44, (combat) => (combat.conditions[0].effects = ["own-checks-advantage"])),
  numbersMessage,
);
assert.throws(
  combatAt(44, (combat) => (combat.conditions[0].modifiers = [{ to: "defense", flat: 1 }])),
  numbersMessage,
);
assert.throws(
  () =>
    assertRulesetCombat(
      apiManifest(44),
      numbersDocument((combat) => combat.conditions.pop()),
    ),
  numbersMessage,
);
const stunned = (combat) => combat.conditions.at(-1);
for (const [edit, message] of [
  [
    (combat) => (stunned(combat).modifiers[0].to = "luck"),
    /changes "luck", not one of defense, attacks, saves, checks, speed/u,
  ],
  [(combat) => (stunned(combat).modifiers[0] = { to: "defense" }), /changes defense by nothing/u],
  [(combat) => (stunned(combat).modifiers[0].flat = 0), /changes defense by a flat 0, which changes nothing/u],
  [
    (combat) => (stunned(combat).modifiers[0].flat = 1.5),
    /changes defense by 1\.5, not a whole number from -100 to 100/u,
  ],
  [
    (combat) => (stunned(combat).modifiers[0] = { to: "defense", dice: "1d4" }),
    /rolls dice onto defense, and dice change only attacks, saves, checks, damage, damage-taken/u,
  ],
  [(combat) => (stunned(combat).modifiers[1].dice = "0d6"), /rolls "0d6", which is not dice a table has/u],
  [
    (combat) => (stunned(combat).modifiers[1] = { to: "attacks", flat: -1, minus: true }),
    /takes dice off attacks with "minus" but has no dice/u,
  ],
  [
    (combat) => (stunned(combat).modifiers[2].to = "attacks"),
    /multiplies attacks, and "times" changes speed, the health maximum or damage only/u,
  ],
  [(combat) => (stunned(combat).modifiers[2].times = 3), /multiplies speed by 3, not 0\.5 or 2/u],
  [(combat) => (stunned(combat).modifiers[2].why = "cold"), /a modifier has the unknown key "why"/u],
  [(combat) => (stunned(combat).modifiers = []), /changes 1 to 6 numbers/u],
  [(combat) => (stunned(combat).saves = ["str_save"]), /narrows saves with nothing to narrow/u],
  [(combat) => (combat.levels[0].track = "grit"), /level names unknown track "grit"/u],
  [(combat) => (combat.levels[0].track = "harm"), /reads a wound track, and a level reads a plain track's number/u],
  [(combat) => (combat.levels[0].at = 7), /is never reached: the track goes up to 6/u],
  [(combat) => (combat.levels[1].at = 1), /level 1 of "fatigue" is given twice/u],
  [(combat) => (combat.levels[0].effects = ["ends-on-damage"]), /cannot have "ends-on-damage": nobody put it on/u],
  [(combat) => (combat.levels[0].effects = ["glowing"]), /has the unknown effect "glowing"/u],
  [
    (combat) => (combat.levels[0].effects = []),
    /does nothing: a level has effects, modifiers, saves it fails or defeats/u,
  ],
  [(combat) => (combat.levels[0].failsSaves = ["luck_save"]), /names unknown save "luck_save"/u],
]) {
  assert.throws(numbersAt(45, edit), message, String(message));
}
// A modifier to saves is something `saves` narrows, exactly as a save effect is.
assert.doesNotThrow(
  numbersAt(45, (combat) => {
    stunned(combat).modifiers[0] = { to: "saves", flat: -2 };
    stunned(combat).saves = ["str_save"];
  }),
);

// A reaction that answers something being used, or only some catalogs' entries (1.44), and one
// that answers being hit (1.46).
for (const [minor, reaction] of [
  [44, { on: "used", cancels: true }],
  [44, { on: "aimed", against: { catalogs: ["tricks"] } }],
  [46, { on: "hit" }],
  [46, { on: "hit", against: { catalogs: ["tricks", "beasts"] } }],
  [116, { on: "used", cancels: true, upTo: "paid" }],
  [116, { on: "used", cancels: true, upTo: "paid", above: { check: { const: 4 }, dc: 10 } }],
  [117, { on: "hit", also: [{ on: "aimed", against: { entries: ["tricks/sear"] } }] }],
  [117, { on: "aimed", against: { entries: ["tricks/sear"] } }],
]) {
  assert.equal(assertRulesetReactions(apiManifest(minor), momentDocument(reaction)), 1, JSON.stringify(reaction));
  assert.throws(
    () => assertRulesetReactions(apiManifest(minor - 1), momentDocument(reaction)),
    new RegExp(
      `waits for a moment an older Engine does not open and must declare capability API 1\\.${minor} or newer`,
      "u",
    ),
    JSON.stringify(reaction),
  );
}
for (const [reaction, message] of [
  [{ on: "hit", cancels: true }, /only an "aimed" or "used" reaction cancels/u],
  [{ on: "used", against: { catalogs: ["hexes"] } }, /answers unknown catalog "hexes"/u],
  [{ on: "used", against: { catalogs: [] } }, /answers catalogs \[\], not a list of 1 to 12/u],
  [{ on: "used", against: ["tricks"] }, /not \{ catalogs, entries \}/u],
  [{ on: "used", against: { catalogs: ["tricks"], also: 1 } }, /not \{ catalogs, entries \}/u],
  [{ on: "used", against: { entries: ["tricks"] } }, /not "<catalog>\/<entry>"/u],
  [{ on: "used", against: { entries: ["hexes/sear"] } }, /an entry of unknown catalog "hexes"/u],
  [{ on: "used", upTo: "paid" }, /a "used" reaction that cancels/u],
  [{ on: "used", cancels: true, upTo: "all" }, /not "paid"/u],
  [{ on: "used", cancels: true, above: { check: { const: 3 }, dc: 10 } }, /with no "upTo"/u],
  [{ on: "used", cancels: true, upTo: "paid", above: { check: { const: 3 }, dc: -1 } }, /not a DC from 0 to 1000/u],
  [{ on: "used", cancels: true, also: [{ on: "hit" }] }, /cancels, so it answers one moment/u],
  [{ on: "hit", also: [{ on: "falling" }] }, /is also taken at "falling"/u],
  [{ on: "hit", also: [] }, /not a list of 1 to 3 moments/u],
]) {
  assert.throws(
    () => assertRulesetReactions(apiManifest(46), momentDocument(reaction)),
    message,
    JSON.stringify(reaction),
  );
}

// The conditions a catalog entry applies: the sheet's own, and ending after one use or as a turn
// begins only on an Engine that reads it.
assert.ok(assertRulesetApplies(shippedManifest, parsedAsset, shippedCatalogSources) > 20);
const appliesDocument = (applies) => {
  const document = momentDocument(true);
  document.catalogs.at(-1).entries[0].mechanics = { kind: "debuff", applies };
  return document;
};
assert.equal(
  assertRulesetApplies(apiManifest(27), appliesDocument([{ condition: "prone", duration: { rounds: 2 } }])),
  1,
);
assert.equal(
  assertRulesetApplies(apiManifest(27), bestiaryDocument()),
  0,
  "a creature's own actions are not read here",
);
for (const applies of [
  { condition: "prone", duration: { rounds: 1, at: "turn-start" } },
  { condition: "prone", duration: { rounds: 1 }, endsAfter: "own-attack" },
]) {
  assert.equal(assertRulesetApplies(apiManifest(45), appliesDocument([applies])), 1);
  assert.throws(
    () => assertRulesetApplies(apiManifest(44), appliesDocument([applies])),
    /ends "prone" after one use or as a turn begins and must declare capability API 1\.45 or newer/u,
  );
}
for (const [applies, message] of [
  [{ condition: "dazed", duration: "instant" }, /applies unknown condition "dazed"/u],
  [{ condition: "prone", duration: "until-save" }, /applies "prone" until a save it does not name/u],
  [
    { condition: "prone", duration: "until-save", saveEnds: { save: "luck_save", at: "turn-end" } },
    /ends "prone" on unknown save "luck_save"/u,
  ],
  [
    { condition: "prone", duration: { rounds: 1 }, endsAfter: "own-turn" },
    /after "own-turn", not one of own-attack, own-hit, attacked, attacked-by-source, own-save/u,
  ],
  [
    { condition: "prone", duration: { rounds: 1, at: "turn-end" } },
    /counts "prone" down at "turn-end", not "turn-start"/u,
  ],
]) {
  assert.throws(() => assertRulesetApplies(apiManifest(46), appliesDocument([applies])), message, String(message));
}

// A creature's own contest checks (1.43), and its own reaction on itself (1.46).
const contestBestiary = (edit) => {
  const document = bestiaryDocument(edit);
  document.combat = structuredClone(combatBlock);
  withContests(document.combat);
  return document;
};
const creaturesAt = (minor, edit) => () => assertRulesetCreatures(apiManifest(minor), contestBestiary(edit));
const withChecks = (block) => (block.checks = { might: 3 });
assert.equal(creaturesAt(43, withChecks)(), 1);
assert.throws(
  creaturesAt(42, withChecks),
  /gives its own contest checks and must declare capability API 1\.43 or newer/u,
);
assert.throws(
  creaturesAt(43, (block) => (block.checks = { agility: 3 })),
  /names unknown contest check "agility"/u,
);
assert.throws(
  creaturesAt(43, (block) => (block.checks = { might: 3.5 })),
  /check "might" is 3\.5, not a whole number from -100 to 100/u,
);
const parryAction = () => ({
  id: "parry",
  name: "Parry",
  budget: "bonus",
  self: true,
  reaction: { on: "hit" },
  applies: [{ condition: "prone", duration: { rounds: 1 }, endsAfter: "attacked" }],
});
const withParry =
  (edit = () => {}) =>
  (block) => {
    const parry = parryAction();
    block.actions.push(parry);
    edit(parry, block);
  };
assert.equal(creaturesAt(46, withParry())(), 1);
assert.throws(
  creaturesAt(45, withParry()),
  /reacts or acts on the creature itself and must declare capability API 1\.46 or newer/u,
);
assert.throws(
  creaturesAt(
    45,
    withParry((parry) => delete parry.reaction),
  ),
  /reacts or acts on the creature itself and must declare capability API 1\.46 or newer/u,
  "self alone asks for 1.46",
);
assert.throws(
  creaturesAt(
    44,
    withParry((parry) => delete parry.reaction),
  ),
  /ends "prone" after one use or as a turn begins and must declare capability API 1\.45 or newer/u,
);
for (const [edit, message] of [
  [(parry) => (parry.targetCount = 2), /lands on the creature itself, so it takes no targetCount/u],
  [(parry) => (parry.area = { shape: "burst", size: 5 }), /lands on the creature itself, so it takes no area/u],
  [(parry) => (parry.self = false), /self must be true when it is given/u],
  [
    (parry, block) => {
      parry.signature = { cost: 1 };
      block.signaturePoints = 3;
    },
    /is a reaction, so it is not bought with points as well/u,
  ],
  [(parry) => (parry.reaction = { on: "hit", cancels: true }), /only an "aimed" or "used" reaction cancels/u],
  [(parry) => (parry.reaction = { on: "hit", against: { catalogs: ["hexes"] } }), /answers unknown catalog "hexes"/u],
  [(parry) => (parry.reaction = "soon"), /has a reaction of "soon", not a moment/u],
  [
    (parry) => (parry.applies[0].endsAfter = "own-turn"),
    /after "own-turn", not one of own-attack, own-hit, attacked, attacked-by-source, own-save/u,
  ],
  [
    (parry, block) =>
      block.actions.push({ id: "flurry", name: "Flurry", budget: "action", sequence: [{ action: "parry" }] }),
    /names "parry", which is a reaction, so no sequence can make it/u,
  ],
  [
    (parry, block) => (block.actions.find((action) => action.id === "both").self = true),
    /is a sequence, so it carries no self of its own/u,
  ],
]) {
  assert.throws(creaturesAt(46, withParry(edit)), message, String(message));
}

// The published artifact must be reproducible: the same manifest and asset bytes
// have to produce the same zip, or every rebuild would churn the catalog's sha256
// and the Engine would see an "update" that changed nothing.
const assetBuffer = await readFile(join(packageRoot, RULESET_ASSET_PATH));
// Every declared asset rides the ruleset file in declaration order, catalogs included; never a zip.
// Translations (0.439.0) ride it too, read as they are committed.
const fileEntries = await Promise.all(
  shippedManifest.contributions.assets.paths.map(async (path) => ({
    path,
    data:
      path === RULESET_ASSET_PATH
        ? assetBuffer
        : shippedCatalogSources.has(path)
          ? Buffer.from(shippedCatalogSources.get(path))
          : await readFile(join(packageRoot, path)),
  })),
);
const digest = (buffer) => createHash("sha256").update(buffer).digest("hex");
const first = packageFileBuffer(RULESET_FILE_FORMAT, shippedManifest, fileEntries);
const second = packageFileBuffer(RULESET_FILE_FORMAT, shippedManifest, fileEntries);
assert.equal(digest(first), digest(second), "a rebuilt ruleset artifact must be byte-identical");
assert.ok(first.subarray(0, 48).toString("utf8").startsWith('{"format":"marinara-ruleset","version":1,'));

// And it must be the artifact actually committed for this package.
const committedArtifact = await readFile(
  join(repoRoot, "artifacts", rulesetArtifactName(shippedManifest.id, shippedManifest.version)),
);
assert.equal(digest(first), digest(committedArtifact), "the committed artifact must match a fresh build");

// The declared hash and size must describe the committed asset bytes.
const declaredAsset = shippedManifest.files.find((file) => file.path === RULESET_ASSET_PATH);
assert.equal(declaredAsset.sha256, digest(assetBuffer));
assert.equal(declaredAsset.bytes, assetBuffer.byteLength);

console.log("ruleset package contract: OK");

// The SRD's multiclassing tables, read for the builder's second class (no sheet change yet).
{
  const { multiclassData } = await import("../ruleset-5e-builder-data.mjs");
  const classNames = [
    "Barbarian",
    "Bard",
    "Cleric",
    "Druid",
    "Fighter",
    "Monk",
    "Paladin",
    "Ranger",
    "Rogue",
    "Sorcerer",
    "Warlock",
    "Wizard",
  ];
  const table = (head, rows) =>
    `x\n\n| Class | ${head} |\n|---|---|\n${rows.map(([a, b]) => `| ${a} | ${b} |`).join("\n")}`;
  const prereq = classNames.map((name) => [
    name,
    name === "Fighter" ? "Strength 13 or Dexterity 13" : name === "Monk" ? "Dexterity 13 and Wisdom 13" : "Charisma 13",
  ]);
  const gains = classNames.map((name) => [
    name,
    name === "Rogue" ? "Light armor, one skill from the class's skill list, thieves' tools" : "-",
  ]);
  const rules = (gainRows = gains) => [
    { pk: "srd_multiclassing_prerequistes", fields: { desc: table("Ability Score Minimum", prereq) } },
    { pk: "srd_multiclassing_proficiencies", fields: { desc: table("Proficiencies Gained", gainRows) } },
  ];
  const classes = new Map(classNames.map((name) => [name, { armor: "Light armor", skills: { from: ["stealth"] } }]));
  const read = multiclassData(rules(), classes);
  assert.deepEqual(read.get("Fighter").prerequisites, { any: ["str", "dex"] });
  assert.deepEqual(read.get("Monk").prerequisites, { all: ["dex", "wis"] });
  assert.deepEqual(read.get("Rogue").gains, {
    armor: ["light"],
    weapons: [],
    tools: ["thieves-tools"],
    skills: ["class"],
  });
  assert.throws(
    () => multiclassData(rules(gains.map(([name]) => [name, name === "Bard" ? "Heavy armor" : "-"])), classes),
    /Bard gains "Heavy armor", not read/u,
  );
}

// Release 0.58.0: resolve limits only with the existing sheet/catalog vocabulary.
{
  const catalog = (name) => JSON.parse(shippedCatalogSources.get(`catalogs/${name}.json`)).entries;
  const races = new Map(catalog("races").map((entry) => [entry.id, entry]));
  const creatures = new Map(catalog("creatures").map((entry) => [entry.id, entry.creature]));
  const evaluated = (fields = {}, abilities = {}, lists = {}, bonuses = {}) =>
    evaluateSheet(parsedAsset, { fields, abilities, lists, bonuses, skills: {}, saves: {} });

  // 1. The armor speed requirement exempts the dwarf, including magic copies, and nothing else.
  const dwarfRows = races
    .get("dwarf")
    .rows.filter((row) => row.list === "features")
    .map((row) => row.values);
  const dwarf = evaluated({}, { str: 8 }, { features: dwarfRows });
  assert.equal(dwarf.derived("armor_speed_strength"), 15);
  assert.equal(dwarf.derived("speed_total"), 25);
  assert.equal(evaluated({}, { str: 8 }).derived("armor_speed_strength"), 8);
  assert.equal(evaluated({}, { str: 18 }, { features: dwarfRows }).derived("armor_speed_strength"), 18);
  // Training (0.317.0) is its own requirement.
  const strength = (one) => one.value.derived === "armor_speed_strength";
  const armor = [...catalog("equipment"), ...catalog("magic_items")].filter((entry) =>
    entry.item.requires?.some(strength),
  );
  assert.ok(armor.length > 10, "mundane and magic heavy armor use the same root requirement");
  for (const entry of armor) {
    for (const requirement of entry.item.requires.filter(strength)) {
      assert.deepEqual(requirement.value, { derived: "armor_speed_strength" });
      assert.ok(dwarf.derived(requirement.value.derived) >= requirement.atLeast, entry.id);
      const ordinary = evaluated({}, { str: requirement.atLeast - 1 });
      assert.ok(ordinary.derived(requirement.value.derived) < requirement.atLeast);
      assert.deepEqual(requirement.otherwise, { modifiers: [{ to: "speed", flat: -10 }] });
    }
  }
  const plate = catalog("equipment").find((entry) => entry.id === "plate-armor").item;
  assert.deepEqual(plate.worn, { effects: ["own-checks-disadvantage"], skills: ["stealth"] });

  // 2. Each ancestry's action and counter share their catalog mark, so using the action spends
  // one list-row pool, the same path as class resources. No duplicate counter on the parent race.
  const ancestries = [
    ["black", "acid", "line", "dex_save"],
    ["blue", "lightning", "line", "dex_save"],
    ["brass", "fire", "line", "dex_save"],
    ["bronze", "lightning", "line", "dex_save"],
    ["copper", "acid", "line", "dex_save"],
    ["gold", "fire", "cone", "dex_save"],
    ["green", "poison", "cone", "con_save"],
    ["red", "fire", "cone", "dex_save"],
    ["silver", "cold", "cone", "con_save"],
    ["white", "cold", "cone", "con_save"],
  ];
  const featureSource = parsedAsset.combat.abilities.find((source) => source.list === "features");
  assert.deepEqual(featureSource.saveDifficulty, { derived: "breath_save_dc" });
  for (const [dragon, type, shape, save] of ancestries) {
    const entry = races.get(`draconic-${dragon}`);
    assert.equal(entry.rows.filter((row) => row.list === "features").length, 1);
    assert.deepEqual(entry.rows.find((row) => row.list === "counters").values, {
      name: "Breath Weapon",
      max: 1,
      recharge: "short",
    });
    const mechanics = entry.mechanics;
    assert.equal(mechanics.kind, "attack");
    assert.equal(mechanics.budget, "action");
    assert.deepEqual(mechanics.area, { shape, size: shape === "line" ? 30 : 15 });
    assert.equal(mechanics.damageType, type);
    assert.deepEqual(mechanics.save, { save, onSuccess: "half" });
    assert.deepEqual(mechanics.amount, { dice: "2d6" });
    assert.equal(mechanics.cost, undefined, "uses its same-entry counter, never a spell slot");
    assert.deepEqual(mechanics.scales.from, { derived: "level" });
    for (const [level, dice] of [
      [1, 2],
      [5, 2],
      [6, 3],
      [10, 3],
      [11, 4],
      [15, 4],
      [16, 5],
      [20, 5],
    ]) {
      const extra = mechanics.scales.table.filter(([at]) => at <= level).at(-1)[1];
      assert.equal(2 + extra, dice);
      assert.equal(
        evaluated({ level_fighter: level, spell_dc_extra: 5 }, { con: 16 }).derived("breath_save_dc"),
        8 + 3 + evaluated({ level_fighter: level }).derived("proficiency_bonus"),
      );
    }
  }
  for (const rest of ["short", "long"]) {
    assert.ok(
      parsedAsset.rests.find((entry) => entry.id === rest).restore.some((entry) => entry.listPools === "counters"),
    );
  }

  // 3. Damage and an instead-of-damage grab are exclusive actions with the same attack roll.
  for (const [id, strikeId, dc, dice] of [
    ["vampire", "unarmed_strike", 18, "1d8"],
    ["vampire-spawn", "claws", 13, "2d4"],
  ]) {
    const actions = creatures.get(id).actions;
    const strike = actions.find((action) => action.id === strikeId);
    const grab = actions.find((action) => action.id === `${strikeId}_grapple`);
    assert.equal(strike.damage.dice, dice);
    assert.equal(strike.applies, undefined);
    assert.equal(grab.damage, undefined);
    assert.equal(grab.save, undefined, "a hit applies the hold without a second save");
    assert.equal(grab.toHit, strike.toHit);
    assert.equal(grab.reach, strike.reach);
    assert.deepEqual(grab.applies, [{ condition: "grappled", duration: "instant", escapeDc: dc }]);
    assert.ok(actions.some((action) => action.sequence?.some((step) => step.action === grab.id)));
    // The vampire's two grapples are the alternative its full action list drops.
    if (id !== "vampire")
      assert.ok(actions.some((action) => action.sequence?.some((step) => step.action === grab.id && step.times === 2)));
    assert.ok(
      actions
        .filter((action) => action.sequence)
        .every(
          (action) =>
            action.sequence.reduce((sum, step) => sum + step.times, 0) === 2 &&
            action.sequence.filter((step) => step.action === "bite").reduce((sum, step) => sum + step.times, 0) <= 1,
        ),
    );
  }

  // 4. Four printed attacks split into choices; state-dependent alternatives stay prose.
  const actionsOf = (id) => new Map(creatures.get(id).actions.map((action) => [action.id, action]));
  const javelins = actionsOf("bugbear");
  assert.deepEqual(javelins.get("javelin").damage, { dice: "2d6", flat: 2, type: "piercing" });
  assert.equal(javelins.get("javelin").range, undefined);
  assert.equal(javelins.get("javelin").reach, 5);
  assert.deepEqual(javelins.get("javelin_ranged").damage, { dice: "1d6", flat: 2, type: "piercing" });
  assert.deepEqual(javelins.get("javelin_ranged").range, { normal: 30, long: 120 });
  assert.equal(javelins.get("javelin_ranged").reach, undefined);
  for (const [id, strikeId, toHit, baseDice, flat] of [
    ["dryad", "club", 6, "1d4", 4],
    ["druid", "quarterstaff", 4, "1d6", 2],
  ]) {
    const actions = actionsOf(id);
    assert.equal(actions.get(strikeId).toHit, 2);
    assert.equal(actions.get(strikeId).damage.dice, baseDice);
    assert.equal(actions.get(`${strikeId}_shillelagh`).toHit, toHit);
    assert.deepEqual(actions.get(`${strikeId}_shillelagh`).damage, {
      dice: "1d8",
      flat,
      type: "bludgeoning",
      qualities: ["magical", "magic_weapon"],
    });
  }
  const twoHands = actionsOf("druid").get("quarterstaff_two_hands");
  assert.equal(twoHands.toHit, 2);
  assert.deepEqual(twoHands.damage, { dice: "1d8", flat: 2, type: "bludgeoning" });
  const djinni = actionsOf("djinni");
  for (const [id, type] of [
    ["scimitar", "lightning"],
    ["scimitar_thunder", "thunder"],
  ]) {
    assert.deepEqual(djinni.get(id).damage.plus, [{ dice: "1d6", type }]);
    assert.equal(djinni.get(id).damage.dice, "2d6");
    assert.equal(djinni.get(id).damage.flat, 5);
  }
  // The duergar's "while enlarged" is its Enlarge's doubled dice since 0.94.0.
  // The oni's Glaive "in Small or Medium form" is its own action in its humanoid form since 0.400.0.
  assert.ok(
    creatures.get("oni").actions.some((action) => action.id === "glaive_small" && /humanoid form/u.test(action.name)),
  );
  assert.ok(!creatures.get("oni").actions.some((action) => /enlarged|small|medium/iu.test(action.name)));

  // 5. Empty actions are legal on sheets. Preserve each supplied stat block and the Shriek text.
  // And the enchanted object Antipathy/Sympathy is cast on (0.246.0), no SRD stat block of its own.
  // And Mislead's illusory double (0.273.0) and Arcane Hand's hand (0.275.0).
  // And the animated tree a treant wakes (0.288.0), and Animate Objects' five objects (0.291.0).
  // And Carpet of Flying's four carpets (0.295.0), and the object True Polymorph makes (0.296.0).
  // And the five lycanthropes' two forms each (0.297.0), and the Broom of Flying (0.301.0).
  // And Phantom Steed's horse (0.315.0), the Feather Token's whip (0.325.0) and the goat of terror (0.327.0).
  // And the chain devil's animated chain (0.338.0) and the four Dancing Swords in the air (0.343.0).
  // And the Feather Token's bird (0.352.0), and the ebony fly's giant fly and the onyx dog's mastiff (0.358.0).
  // And the imp's, quasit's and oni's seven forms (0.400.0).
  // And the 35 caster archetypes, seven kinds at five ranks (0.434.0).
  assert.equal(creatures.size, 404);
  for (const [id, hp, ac, speed, initiative] of [
    ["donkey", 11, 10, 0, 0],
    ["frog", 1, 11, 20, 1],
    ["sea-horse", 1, 11, 0, 1],
    ["shrieker", 13, 5, 0, -5],
  ]) {
    const creature = creatures.get(id);
    assert.deepEqual(creature.actions, []);
    const build = creature.sheet;
    assert.equal(build.fields.size, id === "frog" || id === "sea-horse" ? 1 : 3);
    const numbers = evaluateSheet(parsedAsset, { fields: {}, skills: {}, saves: {}, bonuses: {}, lists: {}, ...build });
    assert.equal(numbers.derived("hp_max_total"), hp);
    assert.equal(numbers.derived(parsedAsset.combat.defense.derived), ac);
    assert.equal(numbers.derived("speed_total"), speed);
    assert.equal(numbers.derived("initiative"), initiative);
    for (const key of ["health", "defense", "speed", "abilities", "saves", "checks", "initiativeModifier"])
      assert.equal(creature[key], undefined, `${id} takes ${key} only from its sheet`);
  }
  assert.equal(
    evaluateSheet(parsedAsset, { skills: {}, saves: {}, fields: {}, lists: {}, ...creatures.get("frog").sheet }).skill(
      "perception",
    ),
    1,
  );
  assert.deepEqual(creatures.get("sea-horse").speeds, { swim: 20 });
  assert.match(
    creatures.get("shrieker").traits.find((trait) => trait.name === "Shriek").text,
    /shriek audible within 300 feet/u,
  );

  // 6. Counts use the original radius/side/length, before a cube is represented as a board burst.
  const spells = new Map(catalog("spells").map((entry) => [entry.id, entry.mechanics]));
  for (const [id, count] of [
    ["burning-hands", 1],
    ["fireball", 4],
    ["thunderwave", 3],
    ["flame-strike", 2],
    ["lightning-bolt", 3],
  ])
    assert.equal(spells.get(id).targetCount, count, id);
  assert.equal(
    creatures.get("ancient-red-dragon").actions.find((action) => action.id === "fire_breath").targetCount,
    9,
  );
  assert.equal(creatures.get("djinni").actions.find((action) => action.id === "create_whirlwind").targetCount, 1);
  assert.ok(
    catalog("spells")
      .filter((entry) => entry.mechanics?.area && entry.mechanics?.kind !== "utility")
      .every((entry) => entry.mechanics?.targetCount >= 1),
  );
  for (const entry of catalog("magic_items").filter((entry) => entry.id.startsWith("spell-scroll-"))) {
    if (entry.item.use?.area)
      assert.equal(entry.item.use.targetCount, spells.get(entry.id.slice("spell-scroll-".length))?.targetCount);
  }

  // The Engine's count ceiling is 20. Non-resolving utility areas must not acquire invalid
  // counts (Hallucinatory Terrain would otherwise get 30, Antipathy/Sympathy 40).
  for (const entry of catalog("spells")) {
    const count = entry.mechanics?.targetCount;
    assert.ok(count === undefined || (count >= 1 && count <= 20), entry.id);
  }
  assert.equal(spells.get("hallucinatory-terrain").kind, "utility");
  assert.equal(spells.get("hallucinatory-terrain").targetCount, undefined);
  // Antipathy/Sympathy is a target's aura since 0.137.0, never an area's count.
  assert.equal(spells.get("antipathysympathy-antipathy").targetCount, undefined);

  // 7. Existing builder total.max handles 20 and refuses 21; free-edit maxima remain per field.
  const levels = parsedAsset.sheet.builder.steps.find((step) => step.id === "levels");
  const accepts = (fields) => levels.total.fields.reduce((sum, id) => sum + (fields[id] ?? 0), 0) <= levels.total.max;
  assert.equal(accepts({ level_fighter: 10, level_wizard: 10 }), true);
  assert.equal(accepts({ level_fighter: 10, level_wizard: 11 }), false);
  assert.equal(accepts({ level_other: 20, level_rogue: 1 }), false);
  for (const id of levels.total.fields) assert.equal(parsedAsset.sheet.fields.find((field) => field.id === id).max, 20);

  // 8. README limits agree with what the race picks and derived speed already do.
  const readme = await readFile(join(packageRoot, "README.md"), "utf8");
  assert.deepEqual(races.get("elf").grants.trained.skills, ["perception"]);
  assert.ok(!/mark Perception proficient yourself|cannot read a race's speed|Nothing stops class levels/u.test(readme));
  assert.match(readme, /Speed follows the picked race/u);
  assert.match(readme, /and since 0\.302\.0 their combined total too/u);
  assert.match(
    readme,
    /The oni's Glaive "in Small or Medium form" is its own action in its humanoid form since 0\.400\.0/u,
  );
}
console.log("ruleset 0.58.0 supported-limit regression checks passed");

