// Release 0.60.0: condition spell choices, priced standard actions and passive class effects.
{
  const entries = (asset) => JSON.parse(shippedCatalogSources.get(`catalogs/${asset}.json`)).entries;
  const spells = new Map(entries("spells").map((entry) => [entry.id, entry]));
  const features = new Map(entries("features").map((entry) => [entry.id, entry]));
  const sheet = (fields = {}, abilities = {}, lists = {}, saves = {}, definition = parsedAsset) =>
    evaluateSheet(definition, { fields, abilities, lists, saves, skills: {}, bonuses: {} });

  // One choice, one condition: no unconditional blindness, no permanent until-save effect,
  // no concentration on Blindness/Deafness and no spell slot cost doubled by the alternative.
  // SRD: Constitution save, blinded or deafened (choice), one minute, re-save at each turn end.
  for (const [id, condition] of [
    ["blindnessdeafness", "blinded"],
    ["blindnessdeafness-deafened", "deafened"],
  ]) {
    const entry = spells.get(id);
    assert.deepEqual(entry.mechanics, {
      components: ["verbal"],
      seen: true,
      kind: "debuff",
      range: 30,
      qualities: ["magical"],
      save: { save: "con_save", onSuccess: "negates" },
      applies: [{ condition, duration: { rounds: 10 }, saveEnds: { save: "con_save", at: "turn-end" } }],
      cost: [{ pool: "slots_2", amount: 1 }],
      // One more target for each slot level above 2nd (0.70.0).
      targetCount: 1,
      targetsPerCostStep: 1,
    });
    assert.deepEqual(entry.filters, spells.get("blindnessdeafness").filters);
    assert.equal(entry.rows[0].values.level, 2);
    assert.equal(entry.rows[0].values.concentration, false);
  }
  assert.equal(
    spells.get("blindnessdeafness-deafened").rows[0].values.name,
    spells.get("blindnessdeafness-deafened").label,
  );
  assert.match(spells.get("blindnessdeafness").summary, /^Blinded choice\./u);
  assert.deepEqual(spells.get("greater-invisibility").mechanics, {
    components: ["verbal", "somatic"],
    kind: "buff",
    range: 0,
    targets: "any",
    applies: [{ condition: "invisible", duration: { rounds: 10 } }],
    cost: [{ pool: "slots_4", amount: 1 }],
    concentration: true,
  });
  // SRD: invisible until the spell ends; concentration, up to one minute.
  // Since 0.77.0 its advantage and the disadvantage against it are combat.sight's unseen attacks.
  assert.deepEqual(parsedAsset.combat.conditions.find((entry) => entry.condition === "invisible").unseen, {
    pierced: ["blindsight", "tremorsense", "truesight", "see_invisibility"],
  });

  assert.equal(parsedAsset.combat.abilities.find((entry) => entry.list === "spells").budget, "action");
  const scrolls = new Map(entries("magic_items").map((entry) => [entry.id, entry.item]));
  // Since 0.73.0 (Capability API 1.174) an item's use holds concentration.
  assert.equal(scrolls.get("spell-scroll-greater-invisibility").use.concentration, true);
  for (const [id, condition] of [
    ["blindnessdeafness", "blinded"],
    ["blindnessdeafness-deafened", "deafened"],
  ]) {
    assert.deepEqual(scrolls.get(`spell-scroll-${id}`).use.applies, spells.get(id).mechanics.applies);
    assert.equal(scrolls.get(`spell-scroll-${id}`).use.saveDifficulty, 13);
    assert.equal(scrolls.get(`spell-scroll-${id}`).use.applies[0].condition, condition);
  }

  // Ki's own marked companion pool pays one use of Patient Defense. The standard action keeps
  // the Engine's actual Dodge behavior, including its Dexterity saves and loss of Dodge.
  assert.deepEqual(features.get("monk-ki").mechanics, {
    kind: "utility",
    targets: "self",
    standard: { actions: ["dodge"], budget: "bonus" },
  });
  assert.deepEqual(features.get("monk-ki").rows.find((row) => row.list === "counters").values, {
    name: "Ki",
    max: 2,
    recharge: "short",
  });
  // SRD Patient Defense: spend one Ki point for Dodge as a bonus action.
  assert.deepEqual(features.get("ranger-vanish").mechanics, {
    kind: "utility",
    targets: "self",
    standard: { actions: ["hide"], budget: "bonus" },
  });
  assert.ok(!features.get("ranger-vanish").rows.some((row) => row.list === "counters"));

  const whole = features.get("way-of-the-open-hand-wholeness-of-body");
  assert.deepEqual(whole.mechanics, {
    kind: "heal",
    targets: "self",
    budget: "action",
    amount: { flat: 0 },
    amountAdd: { derived: "wholeness_healing" },
    outsideFight: true,
  });
  assert.deepEqual(whole.rows.find((row) => row.list === "counters").values, {
    name: "Wholeness of Body",
    max: 1,
    recharge: "long",
  });
  for (const level of [6, 11, 20]) assert.equal(sheet({ level_monk: level }).derived("wholeness_healing"), 3 * level);
  assert.equal(sheet({ level_monk: 6, level_fighter: 14 }).derived("wholeness_healing"), 18);
  assert.deepEqual(features.get("rogue-slippery-mind").grants, { trained: { saves: ["wis_save"] } });
  assert.deepEqual(
    new Set(features.get("monk-diamond-soul").grants.trained.saves),
    new Set(parsedAsset.sheet.saves.map((save) => save.id)),
  );
  assert.equal(sheet({ level_monk: 14 }, { wis: 16 }, {}, { wis_save: "proficient" }).save("wis_save"), 8);

  const source = parsedAsset.combat.abilities.find((entry) => entry.list === "features");
  assert.deepEqual(source.byColumn, {
    column: "class",
    values: {
      // Intimidating Presence (0.222.0): 8 + proficiency + Charisma.
      Barbarian: { saveDifficulty: { derived: "spell_save_dc_cha" } },
      // The Deflect Missiles throw back (0.208.0) with proficiency and the better of Strength or Dexterity.
      Monk: { toHit: { derived: "deflect_missiles_attack" }, saveDifficulty: { derived: "ki_save_dc" } },
      Cleric: { saveDifficulty: { derived: "spell_save_dc_wis" } },
      Paladin: { saveDifficulty: { derived: "spell_save_dc_cha" } },
      // Draconic Presence (0.190.0) against the sorcerer's spell save DC.
      Sorcerer: { saveDifficulty: { derived: "spell_save_dc_cha" } },
      // Spell Mastery and Signature Spells (0.189.0) cast with the wizard's Intelligence.
      Wizard: { toHit: { derived: "spell_attack_int" }, saveDifficulty: { derived: "spell_save_dc_int" } },
      // The tiefling's Infernal Legacy (0.424.0) at the racial spell attack and DC.
      Tiefling: { toHit: { derived: "racial_spell_attack" }, saveDifficulty: { derived: "racial_spell_save_dc" } },
    },
  });
  assert.deepEqual(source.saveDifficulty, { derived: "breath_save_dc" });
  for (const id of [
    "monk-ki",
    "monk-stunning-strike",
    "way-of-the-open-hand-open-hand-technique",
    "monk-diamond-soul",
  ]) {
    assert.equal(features.get(id).rows[0].values.class, "Monk", id);
  }
  assert.equal(
    sheet(
      { level_monk: 5, level_wizard: 3, spellcasting_ability: "int", spell_dc_extra: 5 },
      { wis: 16, int: 20 },
    ).derived("ki_save_dc"),
    14,
    "Ki uses Wisdom and proficiency, never a spellcasting bonus",
  );

  // The Hunter option reuses the complete reaction while the other choices keep their text.
  const hunter = features.get("hunter-superior-hunters-defense-uncanny-dodge");
  assert.deepEqual(hunter.mechanics, features.get("rogue-uncanny-dodge").mechanics);
  assert.deepEqual(
    [hunter.exclusive, features.get("hunter-superior-hunters-defense").exclusive],
    ["hunter_superior_hunters_defense", undefined],
  );
  assert.equal(features.get("hunter-superior-hunters-defense").mechanics, undefined);
  assert.equal(hunter.rows[0].values.name, hunter.label);

  const fast = features.get("barbarian-fast-movement").rows[0].values;
  const movement = features.get("monk-unarmored-movement").rows[0];
  assert.deepEqual(movement.scaled.unarmored_movement.from, { field: "level_monk" });
  assert.deepEqual(
    movement.scaled.unarmored_movement.table,
    // SRD Monk table, Unarmored Movement column; fixtures are not a shipped dependency.
    [
      [2, 10],
      [3, 10],
      [4, 10],
      [5, 10],
      [6, 15],
      [7, 15],
      [8, 15],
      [9, 15],
      [10, 20],
      [11, 20],
      [12, 20],
      [13, 20],
      [14, 25],
      [15, 25],
      [16, 25],
      [17, 25],
      [18, 30],
      [19, 30],
      [20, 30],
    ],
  );
  assert.deepEqual(parsedAsset.sheet.derived.find((entry) => entry.id === "fast_movement_allowed").from, {
    itemStat: { from: "worn", pick: "count", tag: "heavy_armor" },
  });
  assert.deepEqual(parsedAsset.sheet.derived.find((entry) => entry.id === "movement_armor_count").of, [
    { itemStat: { from: "worn", pick: "count", category: "armor" } },
    { itemStat: { from: "worn", pick: "count", category: "shield" } },
  ]);
  // The package evaluator deliberately has no inventory resolver. Feed the declared item counts
  // into those two references, then exercise the real sheet formulas against armor/shield cases.
  const wearing = (heavy, armor, shield, rows) => {
    const definition = structuredClone(parsedAsset);
    definition.sheet.derived.find((entry) => entry.id === "fast_movement_allowed").from = { const: heavy };
    definition.sheet.derived.find((entry) => entry.id === "movement_armor_count").of = [
      { const: armor },
      { const: shield },
    ];
    return sheet({}, {}, { features: rows }, {}, definition).derived("speed_total");
  };
  assert.equal(wearing(0, 0, 0, []), 30);
  assert.equal(wearing(0, 0, 0, [fast]), 40);
  assert.equal(wearing(0, 1, 0, [fast]), 40, "light/medium armor permits Fast Movement");
  assert.equal(wearing(1, 1, 0, [fast]), 30, "heavy armor forbids Fast Movement");
  assert.equal(wearing(0, 0, 1, [fast]), 40, "a shield does not forbid Fast Movement");
  for (const [level, bonus] of [
    [2, 10],
    [6, 15],
    [10, 20],
    [14, 25],
    [18, 30],
    [20, 30],
  ]) {
    const actual = movement.scaled.unarmored_movement.table.filter(([at]) => at <= level).at(-1)[1];
    assert.equal(actual, bonus);
    const row = { ...movement.values, unarmored_movement: actual };
    assert.equal(wearing(0, 0, 0, [row]), 30 + bonus);
    assert.equal(wearing(0, 1, 0, [row]), 30, "any armor forbids monk movement");
    assert.equal(wearing(0, 0, 1, [row]), 30, "a shield forbids monk movement");
    assert.equal(wearing(0, 0, 0, [fast, row]), 40 + bonus, "multiclass movement bonuses stack");
  }

  const draconic = features.get("draconic-bloodline-draconic-resilience");
  assert.deepEqual(draconic.grants, { sets: { unarmored_defense: "mage_armor" } });
  const rows = { features: [draconic.rows[0].values] };
  for (const sorcerer of [1, 6, 14]) {
    const fields = { level_sorcerer: sorcerer, level_fighter: 20 - sorcerer, ...draconic.grants.sets };
    const base = sheet(fields, { dex: 16 });
    const picked = sheet(fields, { dex: 16 }, rows);
    assert.equal(picked.derived("hp_draconic_resilience"), sorcerer);
    assert.equal(picked.derived("hp_fixed"), base.derived("hp_fixed") + sorcerer);
    assert.equal(picked.derived("hp_rolled"), base.derived("hp_rolled") + sorcerer);
    assert.equal(picked.derived("ac_unarmored"), 16);
  }
  const armored = structuredClone(parsedAsset);
  armored.sheet.derived.find((entry) => entry.id === "ac_armor_worn").of = { const: 1 };
  assert.ok(
    sheet(draconic.grants.sets, { dex: 16 }, rows, {}, armored).derived("ac_unarmored") < 0,
    "Draconic Resilience cannot supply an AC formula while armor is worn",
  );
  assert.equal(sheet({ hp_method: "by_hand", hp_max: 75 }, {}, rows).derived("hp_max_total"), 75);
}
