  // An hour, and since 0.245.0 8 hours at 3rd or 4th level and 24 at 5th (1.482).
  assert.deepEqual(applies("hunters-mark"), [
    { condition: "hunters_mark", duration: { rounds: 600, bySteps: [600, 4800, 4800, 14400] } },
  ]);
  assert.equal(spells.get("hunters-mark").mechanics.targets, "enemy");
  assert.deepEqual(conditions.get("hunters_mark").modifiers, [
    { to: "damage-taken", attacks: "weapon", fromSource: true, dice: "1d6" },
  ]);
  // Ray of Enfeeblement: on a hit, half damage with Strength weapon attacks; Con save each turn end.
