  const mechanics = (id) => spells.get(id).mechanics;
  // "The condition can be blinded, deafened, paralyzed, or poisoned": one of them.
  assert.equal(mechanics("lesser-restoration").kind, "utility");
  assert.equal(mechanics("lesser-restoration").targets, "ally");
  // "one disease or one condition": the kind first, since 0.125.0.
  assert.deepEqual(mechanics("lesser-restoration").ends, {
    conditions: ["disease", "blinded", "deafened", "paralyzed", "poisoned"],
    count: 1,
    chosen: true,
  });
  assert.deepEqual(mechanics("greater-restoration").ends.count, 1);
  assert.ok(mechanics("greater-restoration").ends.conditions.includes("petrified"));
  // "This spell also ends blindness, deafness": all of them, beside its 70 hit points.
  assert.deepEqual(mechanics("heal").ends, { conditions: ["blinded", "deafened", "disease"] });
  assert.deepEqual(mechanics("heal").amount, { flat: 70 });
  assert.deepEqual(mechanics("mass-heal").ends, { conditions: ["disease", "blinded", "deafened"] });
  assert.deepEqual(mechanics("protection-from-poison").ends, { conditions: ["poisoned"], count: 1 });
  assert.equal(mechanics("spare-the-dying").stabilizes, true);
  assert.deepEqual(mechanics("spare-the-dying").targetTypes, { not: { types: ["undead", "construct"] } });
  assert.deepEqual(mechanics("revivify").revives, { withinRounds: 10, health: { flat: 1 } });
  // A scroll of a spell that only cures is a heal with no hit points.
  for (const id of ["lesser-restoration", "greater-restoration", "spare-the-dying", "revivify"]) {
    const use = items.get(`spell-scroll-${id}`).item.use;
    assert.equal(use.kind, "heal", id);
    assert.equal(use.consumes, true, id);
  }
  // "The kit has ten uses. As an action, you can expend one use of the kit to stabilize a creature".
  const kit = read("equipment").get("healers-kit").item;
  assert.deepEqual(kit.charges, { max: 10 });
  assert.deepEqual(without(kit.use, "title"), {
    kind: "heal",
    budget: "action",
    range: 0,
    targets: "ally",
    stabilizes: true,
    charges: 1,
  });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  assert.throws(
    () => assertRulesetSheetHooks(at(175), parsedAsset, shippedCatalogSources),
    /stabilizes the dying, or revives the dead.*1\.176/u,
  );
  for (const [id, edit, message] of [
    ["lesser-restoration", (one) => (one.ends.conditions = ["nope"]), /ends the sheet's conditions/u],
    ["lesser-restoration", (one) => (one.ends.conditions = ["blinded", "blinded"]), /ends the sheet's conditions/u],
    // A kind's count is not held to the names (0.125.0), but is still at most 16.
    ["lesser-restoration", (one) => (one.ends.count = 17), /ends the sheet's conditions/u],
    ["protection-from-poison", (one) => (one.ends.count = 2), /ends the sheet's conditions/u],
    ["spare-the-dying", (one) => (one.stabilizes = false), /stabilizes is true/u],
    ["revivify", (one) => (one.revives.withinRounds = 0), /revives within 1-1000 rounds/u],
    ["revivify", (one) => delete one.revives.health, /revives within 1-1000 rounds/u],
  ]) {
    const sources = new Map(shippedCatalogSources);
    const broken = JSON.parse(sources.get("catalogs/spells.json"));
    edit(broken.entries.find((entry) => entry.id === id).mechanics);
    sources.set("catalogs/spells.json", JSON.stringify(broken));
    assert.throws(() => assertRulesetSheetHooks(at(446), parsedAsset, sources), message, `${id}: ${message}`);
  }
  const undying = structuredClone(parsedAsset);
