// 0.85.0 (Capability API 1.186): actions sharing one recharge, a blow that adds more after a run.
{
  assert.deepEqual(RULESET_GROUPS_MIN, { major: 1, minor: 186 });
  const creatures = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries.map((entry) => [entry.id, entry]),
  );
  const actions = (id) => new Map(creatures.get(id).creature.actions.map((action) => [action.id, action]));
  const grouped = [...creatures.values()].filter((entry) =>
    entry.creature.actions.some((action) => action.recharge?.group === "breath"),
  );
  assert.equal(grouped.length, 20);
  for (const entry of grouped) {
    const breaths = entry.creature.actions.filter((action) => action.recharge?.group === "breath");
    assert.equal(breaths.length, 2, entry.id);
    assert.deepEqual(breaths[0].recharge, breaths[1].recharge, entry.id);
    assert.ok(!(entry.creature.traits ?? []).some((one) => one.name === "Breath Weapons"), entry.id);
  }
  const brass = actions("adult-brass-dragon").get("breath_weapons_sleep_breath");
  assert.deepEqual(
    [brass.save, brass.applies, brass.area, brass.targetCount],
    [
      // A gas since 0.300.0.
      { save: "con_save", difficulty: 18, onSuccess: "negates", against: { qualities: ["gas"] } },
      [{ condition: "asleep", duration: { rounds: 100 } }],
      { shape: "cone", size: 60 },
      6,
    ],
  );
  assert.equal(actions("young-bronze-dragon").get("breath_weapons_repulsion_breath").push, 40);
  assert.deepEqual(actions("copper-dragon-wyrmling").get("breath_weapons_slowing_breath").area, {
    shape: "cone",
    size: 15,
  });
  assert.deepEqual(actions("ancient-silver-dragon").get("breath_weapons_paralyzing_breath").applies, [
    { condition: "paralyzed", duration: { rounds: 10 }, saveEnds: { save: "con_save", at: "turn-end" } },
  ]);
  assert.equal(actions("adult-gold-dragon").get("breath_weapons_weakening_breath").save.save, "str_save");
  for (const id of ["minotaur", "minotaur-skeleton"])
    assert.deepEqual(actions(id).get("gore").charge, {
      atLeast: 10,
      plus: [{ dice: "2d8", type: "piercing" }],
      save: { save: "str_save", difficulty: 14 },
      push: 10,
      applies: [{ condition: "prone", duration: "instant" }],
    });
  const conditions = new Map(parsedAsset.combat.conditions.map((entry) => [entry.condition, entry]));
  assert.deepEqual([conditions.get("asleep").endsWhen, conditions.get("asleep").shakeOff.reach], [["damaged"], 5]);
  assert.equal(conditions.get("slowing_breath").attacksPerTurn, 1);
  assert.ok(creatures.get("iron-golem").creature.tags.includes("inorganic"));
  assert.deepEqual(
    JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries.find((entry) => entry.id === "shatter")
      .mechanics.save.modes,
    [{ is: { tags: ["inorganic"] }, mode: "disadvantage" }],
  );
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  assert.doesNotThrow(() => assertRulesetCreatures(at(446), parsedAsset, shippedCatalogSources));
  assert.throws(() => assertRulesetCreatures(at(185), parsedAsset, shippedCatalogSources), /1\.186/u);
  for (const [id, edit, message] of [
    [
      "adult-brass-dragon",
      (one) => delete one.creature.actions.find((a) => a.id === "breath_weapons").recharge.group,
      /one action only/u,
    ],
    [
      "adult-brass-dragon",
      (one) => (one.creature.actions.find((a) => a.id === "breath_weapons").recharge.from = 6),
      /different dice/u,
    ],
    ["minotaur", (one) => (one.creature.actions.find((a) => a.id === "gore").charge = { atLeast: 10 }), /adds damage/u],
    [
      "minotaur",
      (one) => (one.creature.actions.find((a) => a.id === "gore").charge.save.save = "luck"),
      /unknown save/u,
    ],
    ["minotaur", (one) => (one.creature.actions.find((a) => a.id === "gore").charge.atLeast = 0), /atLeast/u],
  ]) {
    const sources = new Map(shippedCatalogSources);
    const broken = JSON.parse(sources.get("catalogs/creatures.json"));
    edit(broken.entries.find((entry) => entry.id === id));
    sources.set("catalogs/creatures.json", JSON.stringify(broken));
    assert.throws(() => assertRulesetCreatures(at(446), parsedAsset, sources), message, `${id}: ${message}`);
  }
}
