// 0.85.0 (Capability API 1.188): attacks and checks narrowed to an ability, 160 conditions.
{
  assert.deepEqual(RULESET_ABILITY_NARROWING_MIN, { major: 1, minor: 188 });
  const conditions = new Map(parsedAsset.combat.conditions.map((entry) => [entry.condition, entry]));
  assert.ok(parsedAsset.combat.conditions.length > 80);
  assert.deepEqual(conditions.get("weakened_breath").modifiers, [
    { to: "attacks", ability: "str", mode: "disadvantage" },
    { to: "checks", abilities: ["str"], mode: "disadvantage" },
    { to: "saves", saves: ["str_save"], mode: "disadvantage" },
  ]);
  assert.deepEqual(conditions.get("enlarged").modifiers[2], { to: "checks", abilities: ["str"], mode: "advantage" });
  assert.deepEqual(conditions.get("reduced").modifiers[2], { to: "checks", abilities: ["str"], mode: "disadvantage" });
  const spells = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries.map((entry) => [entry.id, entry]),
  );
  for (const [id, condition, ability] of [
    ["enhance-ability", "bears_endurance", "con"],
    ["enhance-ability-bulls-strength", "bulls_strength", "str"],
    ["enhance-ability-cats-grace", "cats_grace", "dex"],
    ["enhance-ability-eagles-splendor", "eagles_splendor", "cha"],
    ["enhance-ability-foxs-cunning", "foxs_cunning", "int"],
    ["enhance-ability-owls-wisdom", "owls_wisdom", "wis"],
  ]) {
    const mechanics = spells.get(id).mechanics;
    assert.deepEqual(
      [mechanics.kind, mechanics.applies[0], mechanics.targetsPerCostStep],
      ["buff", { condition, duration: { rounds: 600 } }, 1],
      id,
    );
    assert.deepEqual(conditions.get(condition).modifiers, [{ to: "checks", abilities: [ability], mode: "advantage" }]);
  }
  assert.deepEqual(spells.get("enhance-ability").mechanics.temporary, { dice: "2d6" });
  assert.equal(spells.get("enhance-ability-owls-wisdom").mechanics.temporary, undefined);
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  assert.equal(assertRulesetCombat(at(446), parsedAsset), true);
  assert.throws(() => assertRulesetCombat(at(187), parsedAsset), /conditions, over 80.*1\.188/u);
  const trimmed = structuredClone(parsedAsset);
  // The first 80 as they stood before True Polymorph's object (0.296.0) came among them.
  trimmed.combat.conditions = trimmed.combat.conditions
    .filter((one) => one.condition !== "polymorphed_object")
    .slice(0, 80);
  trimmed.combat.levels = trimmed.combat.levels.filter((level) => !level.conditionImmunities?.includes("disease"));
  trimmed.combat.conditions[79] = {
    condition: trimmed.combat.conditions[79].condition,
    modifiers: [{ to: "attacks", ability: "str", mode: "disadvantage" }],
  };
  assert.throws(() => assertRulesetCombat(at(187), trimmed), /narrows (?:attacks|checks) to an ability.*1\.188/u);
  for (const [bad, message] of [
    [{ to: "saves", abilities: ["str"], mode: "advantage" }, /only checks are/u],
    [{ to: "checks", abilities: [], mode: "advantage" }, /abilities lists/u],
    [{ to: "checks", abilities: ["luck"], mode: "advantage" }, /unknown ability/u],
    [{ to: "attacks", ability: "luck", mode: "advantage" }, /unknown ability/u],
    [{ to: "speed", ability: "str", flat: 5 }, /narrows damage only/u],
  ]) {
    const broken = structuredClone(parsedAsset);
    broken.combat.conditions.find((entry) => entry.condition === "weakened_breath").modifiers = [bad];
    assert.throws(() => assertRulesetCombat(at(278), broken), message, JSON.stringify(bad));
  }
  assert.throws(() => {
    const many = structuredClone(parsedAsset);
    // 640 since 1.552.
    for (let index = many.combat.conditions.length; index <= 640; index += 1)
      many.combat.conditions.push({ condition: `filler_${index}` });
    assertRulesetCombat(at(278), many);
  }, /over the Engine's 640/u);
}
console.log("ruleset 0.85.0 ability-narrowed attacks and checks regression checks passed");

// 0.86.0 (Capability API 1.187): weapons that know what they hit.
{
  assert.deepEqual(RULESET_SLAY_MIN, { major: 1, minor: 187 });
  const magic = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries.map((entry) => [entry.id, entry]),
  );
  const creatures = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries.map((entry) => [entry.id, entry]),
  );
  const attack = (id) => magic.get(id).item.attack;
  assert.deepEqual(attack("mace-of-smiting").against, [{ is: { types: ["construct"] }, toHit: 2 }]);
  assert.deepEqual(attack("mace-of-smiting").slay, [
    { when: "critical", is: { types: ["construct"] }, healthAtMost: 25 },
  ]);
  assert.deepEqual(
    { ...attack("mace-of-disruption").slay[0], saved: undefined },
    {
      is: { types: ["fiend", "undead"] },
      healthAtMost: 25,
      save: { save: "wis_save", difficulty: 15 },
      saved: undefined,
    },
  );
  for (const id of ["giant-slayer-greataxe", "giant-slayer-handaxe"])
    assert.deepEqual(attack(id).onHit, [
      { condition: "prone", atLeast: 1, save: { save: "str_save", difficulty: 15 }, targetIs: { types: ["giant"] } },
    ]);
  assert.equal(attack("sword-of-life-stealing-rapier").plus[0].tempHp, true);
  assert.deepEqual(attack("dwarven-thrower").range, { normal: 20, long: 60 });
  assert.deepEqual(
    attack("dwarven-thrower").plus.map((clause) => [clause.dice, clause.blow]),
    [
      ["1d8", "ranged"],
      ["2d8", "ranged"],
    ],
  );
  for (const id of ["nine-lives-stealer-greatsword", "nine-lives-stealer-shortsword"]) {
    // Found with 1d8 + 1 charges since 0.431.0.
    assert.deepEqual([magic.get(id).item.charges, magic.get(id).item.stack], [{ max: 9, rolled: "1d8+1" }, 1], id);
    assert.equal(attack(id).slay[0].charges, 1, id);
  }
  const unbeheaded = { types: ["ooze"], tags: ["headless", "legendary"] };
  assert.deepEqual(attack("vorpal-sword-scimitar").slay, [
    { when: "critical", not: unbeheaded, immuneTo: ["slashing"] },
  ]);
  assert.deepEqual(attack("vorpal-sword-scimitar").plus, [
    { dice: "6d8", type: "slashing", when: "critical", targetIs: unbeheaded },
  ]);
  const tags = (id) => creatures.get(id).creature.tags ?? [];
  assert.ok(tags("hydra").includes("headless") && tags("swarm-of-rats").includes("headless"));
  assert.ok(tags("adult-red-dragon").includes("legendary") && !tags("young-red-dragon").includes("legendary"));
  assert.ok(!tags("ogre").includes("headless"));
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  for (const [id, edit, message] of [
    ["mace-of-smiting", (one) => (one.item.attack.against[0].toHit = 0), /toHit is a whole number/u],
    ["mace-of-smiting", (one) => (one.item.attack.against[0].is = { types: ["golem"] }), /"golem"/u],
    ["mace-of-disruption", (one) => (one.item.attack.slay[0].save.save = "luck"), /unknown save/u],
    ["vorpal-sword-longsword", (one) => (one.item.attack.slay[0].immuneTo = ["sharp"]), /unknown damage type/u],
    ["vorpal-sword-longsword", (one) => (one.item.attack.slay[0].when = "sometimes"), /"always" or "critical"/u],
    ["nine-lives-stealer-longsword", (one) => delete one.item.charges, /holds some and stacks one/u],
    ["dwarven-thrower", (one) => (one.item.attack.plus[0].blow = "thrown"), /"melee" or "ranged"/u],
    ["giant-slayer-longsword", (one) => (one.item.attack.onHit[0].oncePerTurn = 1), /oncePerTurn/u],
  ]) {
    const sources = new Map(shippedCatalogSources);
    const broken = JSON.parse(sources.get("catalogs/magic_items.json"));
    edit(broken.entries.find((entry) => entry.id === id));
    sources.set("catalogs/magic_items.json", JSON.stringify(broken));
    assert.throws(() => assertRulesetSheetHooks(at(446), parsedAsset, sources), message, `${id}: ${message}`);
  }
  // An Engine before 1.187 is told so, once the older gates have spoken.
  const sources = new Map(shippedCatalogSources);
  assert.throws(() => assertRulesetSheetHooks(at(186), parsedAsset, sources), /knows what it hits.*1\.187/u);
}
