// 0.87.0 (Capability API 1.189): wounds, sworn enemies, monster attacks by ability.
{
  assert.deepEqual(RULESET_MARKS_MIN, { major: 1, minor: 189 });
  const read = (asset) =>
    new Map(JSON.parse(shippedCatalogSources.get(`catalogs/${asset}.json`)).entries.map((entry) => [entry.id, entry]));
  const creatures = read("creatures");
  const magic = read("magic_items");
  const action = (creature, id) => creatures.get(creature).creature.actions.find((one) => one.id === id);
  // Printed bonuses: an ogre's greatclub +6 (2 + Str 4), a goblin's scimitar +4 (2 + Dex 2), a bat's
  // bite +0 (nearer Str's -2 than Dex's +4), a goblin's shortbow +4 (Dex), a lich's Paralyzing Touch a spell attack.
  assert.equal(action("ogre", "greatclub").ability, "str");
  assert.equal(action("goblin", "scimitar").ability, "dex");
  assert.equal(action("goblin", "shortbow").ability, "dex");
  assert.equal(action("bat", "bite").ability, "str");
  assert.equal(action("lich", "paralyzing_touch").ability, undefined);
  const conditions = new Map(parsedAsset.combat.conditions.map((entry) => [entry.condition, entry]));
  assert.deepEqual(
    [conditions.get("wounded").harms, conditions.get("wounded").stacks],
    [{ at: "turn-start", dice: "1d4", type: "necrotic", healedOnlyByRest: true }, 20],
  );
  assert.equal(conditions.get("sworn_enemy").onePerSource, true);
  assert.deepEqual(magic.get("sword-of-wounding-rapier").item.attack.onHit, [
    {
      condition: "wounded",
      atLeast: 1,
      saveEnds: { save: "con_save", difficulty: 15, at: "turn-start" },
      oncePerTurn: true,
    },
  ]);
  const oathbow = magic.get("oathbow").item;
  assert.deepEqual(oathbow.attack.against, [
    { marked: "sworn_enemy", mode: "advantage", ignoresCover: true, ignoresLongRange: true },
  ]);
  assert.deepEqual(oathbow.attack.plus, [{ dice: "3d6", type: "piercing", marked: "sworn_enemy" }]);
  assert.deepEqual([oathbow.use.free, oathbow.use.charges, oathbow.charges.max, oathbow.stack], [true, 1, 1, 1]);
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  assert.throws(() => assertRulesetSheetHooks(at(188), parsedAsset, shippedCatalogSources), /wielder's mark.*1\.189/u);
  assert.equal(assertRulesetCombat(at(446), parsedAsset), true);
  assert.throws(() => assertRulesetCombat(at(188), parsedAsset), /harms, stacks.*1\.189/u);
  assert.doesNotThrow(() => assertRulesetCreatures(at(446), parsedAsset, shippedCatalogSources));
  assert.throws(
    () => assertRulesetCreatures(at(188), parsedAsset, shippedCatalogSources),
    /ability it attacks with.*1\.189/u,
  );
  for (const [edit, message] of [
    [
      (wounded) => (wounded.harms.at = "dawn"),
      /"turn-start", "turn-end", "source-turn-start", "source-turn-end", "attacks-source", "attacks-source-side", "defies" or "casts"/u,
    ],
    [(wounded) => delete wounded.harms, /only a condition that harms/u],
    [(wounded) => (wounded.harms.type = "bleeding"), /unknown damage type/u],
    [(wounded) => (wounded.stacks = 40), /2 to 20/u],
  ]) {
    const broken = structuredClone(parsedAsset);
    edit(broken.combat.conditions.find((entry) => entry.condition === "wounded"));
    assert.throws(() => assertRulesetCombat(at(278), broken), message);
  }
  for (const [catalog, id, edit, message] of [
    [
      "creatures",
      "ogre",
      (one) => (one.creature.actions.find((a) => a.id === "greatclub").ability = "might"),
      /unknown ability/u,
    ],
    ["magic_items", "oathbow", (one) => (one.item.attack.against[0].marked = "grudge"), /unknown condition/u],
    ["magic_items", "oathbow", (one) => (one.item.attack.against[0] = { marked: "sworn_enemy" }), /changes nothing/u],
    ["magic_items", "oathbow", (one) => (one.item.attack.plus[0].marked = "grudge"), /unknown condition/u],
  ]) {
    const sources = new Map(shippedCatalogSources);
    const broken = JSON.parse(sources.get(`catalogs/${catalog}.json`));
    edit(broken.entries.find((entry) => entry.id === id));
    sources.set(`catalogs/${catalog}.json`, JSON.stringify(broken));
    const check = catalog === "creatures" ? assertRulesetCreatures : assertRulesetSheetHooks;
    assert.throws(() => check(at(278), parsedAsset, sources), message, `${id}: ${message}`);
  }
}
