// 0.99.0 (Capability API 1.202): conditions that end with another put on with them.
{
  assert.deepEqual(RULESET_LINKED_ENDS_MIN, { major: 1, minor: 202 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const catalog = (name) => JSON.parse(shippedCatalogSources.get(`catalogs/${name}.json`));
  const pattern = catalog("spells").entries.find((entry) => entry.id === "hypnotic-pattern").mechanics.applies;
  assert.deepEqual(
    pattern.map((one) => [one.condition, one.endsWith]),
    [
      ["hypnotized", undefined],
      ["incapacitated", "hypnotized"],
    ],
  );
  assert.ok(
    catalog("spells")
      .entries.find((entry) => entry.id === "greater-restoration")
      .mechanics.ends.conditions.includes("hypnotized"),
  );
  const holders = catalog("creatures")
    .entries.filter((entry) =>
      (entry.creature.actions ?? []).some((action) =>
        (action.applies ?? []).some((one) => one.condition === "restrained" && one.endsWith === "grappled"),
      ),
    )
    .map((entry) => entry.id);
  // Since 0.195.0 the marilith, otyugh, tyrannosaurus, shambling mound and water elemental too; since
  // 0.199.0 the rug of smothering; since 0.338.0 the chain devil's animated chain.
  assert.equal(holders.length, 23);
  assert.ok(holders.includes("giant-frog") && holders.includes("roper") && holders.includes("otyugh"));
  const rage = catalog("features").entries.find((entry) => entry.id === "barbarian-rage").mechanics.applies;
  assert.ok(rage.filter((one) => one.condition !== "raging").every((one) => one.endsWith === "raging"));
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  assert.throws(
    () => assertRulesetSheetHooks(at(201), parsedAsset, shippedCatalogSources),
    /a condition that ends with another/u,
  );
  for (const [file, id, edit] of [
    ["spells", "hypnotic-pattern", (one) => (one.mechanics.applies[1].endsWith = "incapacitated")],
    ["spells", "hypnotic-pattern", (one) => (one.mechanics.applies[1].endsWith = "charmed")],
    ["creatures", "roper", (one) => (one.creature.actions.find((a) => a.applies).applies[1].endsWith = "prone")],
    ["features", "barbarian-rage", (one) => (one.mechanics.applies[1].endsWith = "rage")],
  ]) {
    const sources = new Map(shippedCatalogSources);
    const edited = JSON.parse(sources.get(`catalogs/${file}.json`));
    edit(edited.entries.find((entry) => entry.id === id));
    sources.set(`catalogs/${file}.json`, JSON.stringify(edited));
    assert.throws(
      () => assertRulesetSheetHooks(at(446), parsedAsset, sources),
      /endsWith names another condition/u,
      id,
    );
  }
}
console.log("ruleset 0.99.0 linked ending regression checks passed");

