// 0.103.0 (Capability API 1.236): Dispel Evil and Good's special functions and Banishment.
{
  assert.deepEqual(RULESET_DISMISSALS_MIN, { major: 1, minor: 236 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const spells = JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries;
  const spell = (id) => spells.find((entry) => entry.id === id);
  const planar = ["celestial", "elemental", "fey", "fiend", "undead"];
  assert.deepEqual(parsedAsset.combat.conditions.find((one) => one.condition === "dispel_evil_good").actions, [
    "spells/dispel-evil-and-good-break-enchantment",
    "spells/dispel-evil-and-good-dismissal",
  ]);
  const breaks = spell("dispel-evil-and-good-break-enchantment");
  assert.deepEqual(breaks.mechanics.ends.from, { types: planar });
  assert.equal(breaks.mechanics.endsCondition, "dispel_evil_good");
  assert.equal(breaks.filters.kind, "special function");
  assert.deepEqual([breaks.filters.classes, breaks.filters.class_ids], [[], []]);
  const dismissal = spell("dispel-evil-and-good-dismissal").mechanics;
  assert.deepEqual(
    [dismissal.attackRoll, dismissal.save, dismissal.targetTypes, dismissal.dismisses, dismissal.endsCondition],
    [true, { save: "cha_save", onSuccess: "negates" }, { is: { types: planar } }, true, "dispel_evil_good"],
  );
  assert.equal(dismissal.cost, undefined);
  const banishment = spell("banishment").mechanics;
  assert.deepEqual(banishment.dismisses, {
    while: "banished",
    gone: { types: ["celestial", "elemental", "fey", "fiend"] },
  });
  assert.deepEqual(banishment.applies, [{ condition: "banished", duration: { rounds: 10 } }]);
  assert.equal(banishment.targetsPerCostStep, 1);
  const items = JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries;
  assert.deepEqual(
    items.find((entry) => entry.id === "spell-scroll-banishment").item.use.dismisses,
    banishment.dismisses,
  );
  assert.ok(!items.some((entry) => entry.id.startsWith("spell-scroll-dispel-evil-and-good-")));
  assert.equal(assertRulesetCombat(at(446), structuredClone(parsedAsset)), true);
  assert.throws(() => assertRulesetCombat(at(235), structuredClone(parsedAsset)), /give actions .* 1\.236/u);
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  assert.throws(() => assertRulesetSheetHooks(at(235), parsedAsset, shippedCatalogSources), /of 1\.236/u);
  for (const [edit, message] of [
    [
      (one) => (one.actions = ["spells/dispel-evil-and-good-dismissal", "spells/dispel-evil-and-good-dismissal"]),
      /gives/u,
    ],
    [(one) => (one.actions = ["prayers/dismissal"]), /gives/u],
    [(one) => (one.actions = []), /gives/u],
  ]) {
    const document = structuredClone(parsedAsset);
    edit(document.combat.conditions.find((one) => one.condition === "dispel_evil_good"));
    assert.throws(() => assertRulesetCombat(at(278), document), message);
  }
  {
    const document = structuredClone(parsedAsset);
    document.combat.conditions.find((one) => one.condition === "dispel_evil_good").actions = ["spells/harmless"];
    assert.throws(
      () => assertRulesetSheetHooks(at(shippedManifest.capabilityApi.minor), document, shippedCatalogSources),
      /not an entry with mechanics/u,
    );
  }
  for (const [id, edit, message] of [
    ["dispel-evil-and-good-dismissal", (one) => (one.endsCondition = "smitten"), /endsCondition is an entry's/u],
    ["dispel-evil-and-good-dismissal", (one) => (one.dismisses = { gone: { types: ["fiend"] } }), /dismisses is true/u],
    ["banishment", (one) => (one.dismisses.while = "asleep"), /dismisses is true/u],
    ["banishment", (one) => (one.dismisses.gone = { types: ["demon"] }), /creature type "demon"/u],
    ["dispel-evil-and-good-break-enchantment", (one) => (one.ends.from = {}), /ends from needs/u],
  ]) {
    const sources = new Map(shippedCatalogSources);
    const catalog = JSON.parse(sources.get("catalogs/spells.json"));
    edit(catalog.entries.find((entry) => entry.id === id).mechanics);
    sources.set("catalogs/spells.json", JSON.stringify(catalog));
    assert.throws(() => assertRulesetSheetHooks(at(446), parsedAsset, sources), message, id);
  }
}
