  assert.ok(arts.mechanics.grantsStrike.afterAttack.names.includes("Quarterstaff"));
  assert.ok(!arts.mechanics.grantsStrike.afterAttack.names.includes("Greatclub"));
  const flurry = byId("monk-ki-flurry-of-blows");
