// 0.112.0 (Capability API 1.245): Quivering Palm, its two endings, and Hurl Through Hell.
{
  assert.deepEqual(RULESET_QUIVERING_MIN, { major: 1, minor: 245 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const features = JSON.parse(shippedCatalogSources.get("catalogs/features.json")).entries;
  const byId = (id) => features.find((entry) => entry.id === id);
  const palm = byId("way-of-the-open-hand-quivering-palm");
  assert.deepEqual(palm.mechanics, {
    kind: "debuff",
    free: true,
    usesOf: "Ki",
    usesSpent: 3,
    reaction: { on: "hit", by: "self", names: ["Unarmed Strike"], at: "target" },
    // A day since 0.245.0 (1.482 clocks reach 14400 rounds), and the monk's level in days since 0.302.0 (1.663).
    applies: [{ condition: "quivering", duration: "until-dispelled", lastsDays: { field: "level_monk" } }],
  });
  const end = byId("way-of-the-open-hand-quivering-palm-end-the-vibrations");
  assert.deepEqual(end.mechanics, {
    kind: "attack",
    budget: "action",
    targets: "enemy",
    targetHolds: { fromSelf: ["quivering"] },
    amount: { dice: "10d10" },
    damageType: "necrotic",
    save: { save: "con_save", onSuccess: "none" },
    dropsOnFailedSave: true,
    ends: { conditions: ["quivering"] },
  });
  const harmless = byId("way-of-the-open-hand-quivering-palm-end-harmlessly");
  assert.deepEqual(harmless.mechanics, {
    kind: "utility",
    free: true,
    targets: "enemy",
    targetHolds: { fromSelf: ["quivering"] },
    ends: { conditions: ["quivering"] },
  });
  // Both endings are Open Hand features at the palm's level, read with the Monk row's Ki save DC.
  for (const one of [end, harmless]) assert.deepEqual(one.rows[0].values.class_id, palm.rows[0].values.class_id);
  assert.equal(end.rows[0].values.level, palm.rows[0].values.level);
  const hurl = byId("the-fiend-hurl-through-hell");
  assert.deepEqual(hurl.mechanics, {
    kind: "debuff",
    free: true,
    reaction: { on: "hit", by: "self", at: "target" },
    applies: [{ condition: "hurled", duration: { rounds: 1, of: "source" } }],
    dismisses: { while: "hurled" },
  });
  assert.ok(
    hurl.rows.some((row) => row.list === "counters" && row.values.max === 1 && row.values.recharge === "long"),
    "once per long rest",
  );
  const conditions = new Map(parsedAsset.combat.conditions.map((entry) => [entry.condition, entry]));
  assert.deepEqual(conditions.get("quivering"), { condition: "quivering", onePerSource: true });
  assert.deepEqual(conditions.get("hurled").onEnd, {
    harm: { dice: "10d10", type: "psychic", unless: { types: ["fiend"] } },
  });
  assert.equal(assertRulesetCombat(at(446), structuredClone(parsedAsset)), true);
  assert.throws(() => assertRulesetCombat(at(244), structuredClone(parsedAsset)), /harms as it ends .* 1\.245/u);
  for (const edit of [
    (harm) => delete harm.dice,
    (harm) => (harm.type = "sonic-boom"),
    (harm) => (harm.unless = { types: ["dragonish"] }),
    (harm) => (harm.dice = "lots"),
    (harm) => (harm.colour = "red"),
  ]) {
    const document = structuredClone(parsedAsset);
    edit(document.combat.conditions.find((entry) => entry.condition === "hurled").onEnd.harm);
    assert.throws(() => assertRulesetCombat(at(278), document), /harms as it ends with dice/u);
  }
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  assert.throws(() => assertRulesetSheetHooks(at(244), parsedAsset, shippedCatalogSources), /of 1\.245/u);
  // The first reaction named is refused; since 0.115.0 that can be Open Hand Technique's (1.248).
  assert.throws(
    () => assertRulesetReactions(at(244), parsedAsset, shippedCatalogSources),
    /older Engine does not open .* 1\.24[58]/u,
  );
  const broken = (id, edit, message, check = assertRulesetSheetHooks) => {
    const sources = new Map(shippedCatalogSources);
    const catalog = JSON.parse(sources.get("catalogs/features.json"));
    edit(catalog.entries.find((entry) => entry.id === id).mechanics);
    sources.set("catalogs/features.json", JSON.stringify(catalog));
    assert.throws(() => check(at(278), parsedAsset, sources), message);
  };
  const palmId = "way-of-the-open-hand-quivering-palm";
  broken(palmId, (m) => (m.usesSpent = 1), /usesSpent is an entry's whole number from 2 to 20/u);
  broken(palmId, (m) => (m.usesSpent = 2.5), /usesSpent is an entry's whole number from 2 to 20/u);
  broken(`${palmId}-end-the-vibrations`, (m) => delete m.save, /dropsOnFailedSave is true, beside/u);
  broken(`${palmId}-end-the-vibrations`, (m) => (m.dropsOnFailedSave = "yes"), /dropsOnFailedSave is true/u);
  broken(
    palmId,
    (m) => (m.reaction = { on: "aimed", names: ["Unarmed Strike"] }),
    /reaction names lists 1 to 8 distinct attack names/u,
    assertRulesetReactions,
  );
  broken(palmId, (m) => (m.reaction.names = []), /reaction names lists 1 to 8/u, assertRulesetReactions);
  broken(
    palmId,
    (m) => m.reaction.names.push("Unarmed Strike"),
    /reaction names lists 1 to 8/u,
    assertRulesetReactions,
  );
}
