// 0.117.0 (Capability API 1.250): Cutting Words takes the bard's die off an attack roll that hit, and
// Evasion turns a Dexterity half save into nothing or half.
{
  assert.deepEqual(RULESET_CUTTING_WORDS_MIN, { major: 1, minor: 250 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const features = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/features.json")).entries.map((entry) => [entry.id, entry]),
  );
  // 0.124.0 adds its hearing, its charm immunity and its checks and damage.
  const { needs, targetTypes, ...cutting } = features.get("college-of-lore-cutting-words").mechanics;
  const { also, ...lowers } = cutting.lowersRoll;
  assert.deepEqual(
    { ...cutting, lowersRoll: lowers },
    {
      kind: "debuff",
      budget: "reaction",
      usesOf: "Bardic Inspiration",
      reaction: { on: "hit", for: "any", within: 60, seesSource: true },
      lowersRoll: {
        die: {
          from: { field: "level_bard" },
          table: [
            [1, 6],
            [5, 8],
            [10, 10],
            [15, 12],
          ],
        },
      },
    },
  );
  for (const id of ["rogue-evasion", "monk-evasion", "hunter-superior-hunters-defense-evasion"])
    assert.equal(features.get(id).rows[0].values.evasion, 1, id);
  assert.equal(features.get("hunter-superior-hunters-defense-evasion").exclusive, "hunter_superior_hunters_defense");
  assert.equal(features.get("hunter-superior-hunters-defense").rows[0].values.evasion, undefined);
  assert.deepEqual(
    parsedAsset.combat.levels.filter((level) => level.derived === "evasion"),
    [{ derived: "evasion", at: 1, evasion: ["dex_save"] }],
  );
  assert.equal(assertRulesetCombat(at(446), structuredClone(parsedAsset)), true);
  assert.throws(
    () => assertRulesetCombat(at(249), structuredClone(parsedAsset)),
    /must declare capability API 1\.250/u,
  );
  for (const [bad, message] of [
    [["dex"], /unknown save/u],
    [[], /1 to 12 saves/u],
  ]) {
    const document = structuredClone(parsedAsset);
    document.combat.levels.find((level) => level.derived === "evasion").evasion = bad;
    assert.throws(() => assertRulesetCombat(at(278), document), message, JSON.stringify(bad));
  }
  {
    const document = structuredClone(parsedAsset);
    document.combat.levels.find((level) => level.derived === "evasion").evasion = undefined;
    assert.throws(() => assertRulesetCombat(at(278), document), /does nothing/u);
  }
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  assert.throws(() => assertRulesetSheetHooks(at(249), parsedAsset, shippedCatalogSources), /of 1\.25[01]/u);
  const broken = (edit) => {
    const sources = new Map(shippedCatalogSources);
    const catalog = JSON.parse(sources.get("catalogs/features.json"));
    edit(catalog.entries.find((entry) => entry.id === "college-of-lore-cutting-words").mechanics);
    sources.set("catalogs/features.json", JSON.stringify(catalog));
    assert.throws(() => assertRulesetSheetHooks(at(446), parsedAsset, sources), /lowersRoll is/u);
  };
  broken((m) => (m.reaction = { on: "hit", by: "self", at: "target" }));
  broken((m) => (m.reaction.on = "miss"));
  broken((m) => (m.lowersRoll.dice = "1d6"));
  broken((m) => (m.lowersRoll = {}));
  broken((m) => (m.lowersRoll.die.table = [[1]]));
  broken((m) => (m.lowersRoll.extra = 1));
}
