// 0.129.0 (Capability API 1.262): a stat block's own qualities.
{
  assert.deepEqual(RULESET_CREATURE_QUALITIES_MIN, { major: 1, minor: 262 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const creatures = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries.map((entry) => [entry.id, entry.creature]),
  );
  const action = (creature, id) => creatures.get(creature).actions.find((one) => one.id === id);
  const magical = [...creatures.values()].flatMap((one) =>
    one.actions.filter((each) => each.qualities?.includes("magical")),
  );
  // Eight more since 0.143.0: the creatures that magically teleport.
  // And three legendary actions since 0.144.0: Heal Self, Shimmering Shield and the kraken's Lightning Storm.
  // And Channel Negative Energy since 0.149.0, and Whirlwind of Sand since 0.150.0.
  // And the ten Change Shape actions since 0.194.0.
  // And Arcane Hand's three since 0.275.0, and the darkmantle's Darkness Aura, the stone golem's Slow and the
  // lamia's Intoxicating Touch since 0.296.0, the sea hag's Death Glare since 0.303.0, and the nightmare's
  // Ethereal Stride and the phase spider's Ethereal Jaunt since 0.304.0, and the androsphinx's three roars since 0.305.0.
  // And the Feather Token's whip since 0.325.0, and the Dancing Sword's four swords since 0.343.0.
  // And the night hag's and succubus's Etherealness and the oni's two Change Shapes since 0.400.0.
  // And the mummies' glares, the vampire's charm (in both shapes) and the lich's gaze since 0.430.0.
  assert.equal(magical.length, 70);
  for (const [creature, id] of [
    ["unicorn", "healing_touch"],
    ["aboleth", "enslave"],
    ["harpy", "luring_song"],
    ["cockatrice", "bite"],
  ])
    assert.deepEqual(action(creature, id).qualities, ["magical"], `${creature} ${id}`);
  // Another's magic is not the action's own: the bearded devil's glaive closes with "magical healing".
  // A glaive it holds, tagged held (0.133.0).
  assert.deepEqual(action("bearded-devil", "glaive").qualities, ["held"]);
  assert.equal(action("giant-rat-diseased", "bite").qualities, undefined);
  // Its damage is no magic weapon's.
  assert.equal(action("cockatrice", "bite").damage.qualities, undefined);
  assert.ok(assertRulesetCreatures(at(446), parsedAsset, shippedCatalogSources) > 300);
  assert.throws(() => assertRulesetCreatures(at(261), parsedAsset, shippedCatalogSources), /qualities.*1\.262/u);
  const broken = (edit) => {
    const sources = new Map(shippedCatalogSources);
    const catalog = JSON.parse(sources.get("catalogs/creatures.json"));
    edit(
      catalog.entries
        .find((entry) => entry.id === "unicorn")
        .creature.actions.find((one) => one.id === "healing_touch"),
    );
    sources.set("catalogs/creatures.json", JSON.stringify(catalog));
    assert.throws(() => assertRulesetCreatures(at(446), parsedAsset, sources), /qualities are 1 to 8/u);
  };
  broken((one) => (one.qualities = ["holy"]));
  broken((one) => (one.qualities = []));
  broken((one) => (one.qualities = ["magical", "magical"]));
}
console.log("ruleset 0.129.0 magic monster actions regression checks passed");

// 0.130.0 (Capability API 1.263): auras, and conditions kept on all fight.
{
  assert.deepEqual(RULESET_AURAS_MIN, { major: 1, minor: 263 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const conditions = new Map(parsedAsset.combat.conditions.map((entry) => [entry.condition, entry]));
  const read = (asset) =>
    new Map(JSON.parse(shippedCatalogSources.get(`catalogs/${asset}.json`)).entries.map((entry) => [entry.id, entry]));
  const features = read("features");
  assert.deepEqual(features.get("paladin-aura-of-protection").mechanics.keepsOn, [
    "aura_of_protection",
    "aura_of_protection_wide",
    "aura_of_protection_far",
  ]);
  assert.deepEqual(features.get("oath-of-devotion-purity-of-spirit").mechanics.keepsOn, ["protected_from_evil_good"]);
  assert.deepEqual(features.get("oath-of-devotion-holy-nimbus").mechanics.applies, [
    { condition: "holy_nimbus", duration: { rounds: 10 } },
  ]);
  // Every bonus and range opens on exactly one code: the bonus, plus 10 at 18th level.
  const opens = new Map();
  for (const id of ["aura_of_protection", "aura_of_protection_wide", "aura_of_protection_far"])
    for (const aura of conditions.get(id).auras)
      for (let code = 1; code <= 15; code += 1)
        if ((aura.when.atLeast ?? -Infinity) <= code && code <= (aura.when.atMost ?? Infinity))
          opens.set(code, [...(opens.get(code) ?? []), [aura.distance, aura.conditions[0]]]);
  for (const bonus of [1, 2, 3, 4, 5]) {
    assert.deepEqual(opens.get(bonus), [[10, `aura_protection_${bonus}`]], `near ${bonus}`);
    assert.deepEqual(opens.get(bonus + 10), [[30, `aura_protection_${bonus}`]], `far ${bonus}`);
  }
  assert.equal(opens.size, 10);
  assert.deepEqual(
    conditions.get("aura_of_courage").auras.map((aura) => [aura.distance, aura.when]),
    [
      [10, { value: { field: "level_paladin" }, atMost: 17 }],
      [30, { value: { field: "level_paladin" }, atLeast: 18 }],
    ],
  );
  assert.deepEqual(conditions.get("holy_nimbus_light").harms, { at: "turn-start", flat: 10, type: "radiant" });
  assert.deepEqual(read("creatures").get("balor").creature.keepsOn, ["balor_fire_aura", "magic_resistance"]);
  assert.equal(assertRulesetCombat(at(446), structuredClone(parsedAsset)), true);
  assert.throws(() => assertRulesetCombat(at(262), structuredClone(parsedAsset)), /aura.*1\.263/u);
  assert.throws(
    () => assertRulesetApplies(at(262), parsedAsset, shippedCatalogSources),
    /keeps conditions on.*1\.263/u,
  );
  assert.throws(
    () => assertRulesetCreatures(at(262), parsedAsset, shippedCatalogSources),
    /keeps conditions on.*1\.263/u,
  );
  for (const edit of [
    (aura) => (aura.side = "foes"),
    (aura) => ((aura.side = "enemies"), (aura.self = true)),
    (aura) => (aura.conditions = ["nope"]),
    (aura) => (aura.conditions = ["aura_of_courage"]),
    (aura) => (aura.distance = 0),
    (aura) => (aura.when = { value: { field: "level_paladin" } }),
    (aura) => (aura.extra = 1),
  ]) {
    const doc = structuredClone(parsedAsset);
    edit(doc.combat.conditions.find((one) => one.condition === "aura_of_courage").auras[0]);
    assert.throws(() => assertRulesetCombat(at(278), doc), /aura is|is spread by an aura/u);
  }
  const doc = structuredClone(parsedAsset);
  doc.combat.conditions.find((one) => one.condition === "couraged").auras = [
    { distance: 10, side: "allies", conditions: ["devoted"] },
  ];
  assert.throws(() => assertRulesetCombat(at(278), doc), /is spread by an aura/u);
  const keeps = (edit) => {
    const sources = new Map(shippedCatalogSources);
    const catalog = JSON.parse(sources.get("catalogs/features.json"));
    edit(catalog.entries.find((entry) => entry.id === "paladin-aura-of-courage").mechanics);
    sources.set("catalogs/features.json", JSON.stringify(catalog));
    assert.throws(() => assertRulesetApplies(at(278), parsedAsset, sources), /keepsOn is 1 to 4/u);
  };
  keeps((mechanics) => (mechanics.keepsOn = []));
  keeps((mechanics) => (mechanics.keepsOn = ["nope"]));
  keeps((mechanics) => (mechanics.keepsOn = ["a", "b", "c", "d", "e"]));
}
console.log("ruleset 0.130.0 auras regression checks passed");

