// 0.137.0 (Capability API 1.270): Antipathy/Sympathy's chosen kind, auras by kind or sight, far-off saves.
{
  assert.deepEqual(RULESET_KIND_CHOICE_MIN, { major: 1, minor: 270 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const conditions = new Map(parsedAsset.combat.conditions.map((entry) => [entry.condition, entry]));
  const spells = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries.map((entry) => [entry.id, entry]),
  );
  const creatures = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries.map((entry) => [entry.id, entry]),
  );
  assert.equal(spells.has("antipathysympathy"), false);
  for (const effect of ["antipathy", "sympathy"]) {
    const mechanics = spells.get(`antipathysympathy-${effect}`).mechanics;
    assert.deepEqual(
      [mechanics.kindChoice, mechanics.applies, mechanics.save],
      [true, [{ condition: effect, duration: { rounds: 14400 } }], undefined],
    );
    const aura = conditions.get(effect).auras[0];
    assert.deepEqual(
      [aura.distance, aura.side, aura.chosenKind, aura.orSeen, aura.save.difficulty],
      [60, "all", true, true, 18],
    );
    assert.equal(aura.save.applies[effect === "antipathy" ? 0 : 1].saveEnds.beyond, 60);
  }
  assert.deepEqual(
    conditions.get("antipathy").auras[0].save.applies.map((one) => one.condition),
    ["antipathy_frightened", "antipathy_repelled"],
  );
  assert.deepEqual(conditions.get("antipathy_repelled").behavior, { moves: "away" });
  // Kept in reach since 0.141.0.
  assert.deepEqual(conditions.get("sympathy_drawn").behavior, { moves: "toward", keepsIn: 5 });
  const tags = new Set(parsedAsset.combat.creatureTypes.tags.map((tag) => tag.id));
  for (const id of ["vampire", "red_dragon", "goblinoid", "golem", "hag"]) assert.ok(tags.has(id), id);
  assert.ok(creatures.get("adult-red-dragon").creature.tags.includes("red_dragon"));
  assert.ok(creatures.get("goblin").creature.tags.includes("goblinoid"));
  assert.ok(creatures.get("vampire").creature.tags.includes("vampire"));
  assert.equal(creatures.get("half-red-dragon-veteran").creature.tags?.includes("red_dragon") ?? false, false);
  // The scroll names its kind since 0.141.0.
  assert.equal(
    JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries.find(
      (entry) => entry.id === "spell-scroll-antipathysympathy-antipathy",
    ).item.use.kindChoice,
    true,
  );
  assert.equal(assertRulesetCombat(at(446), structuredClone(parsedAsset)), true);
  assert.throws(() => assertRulesetCombat(at(269), structuredClone(parsedAsset)), /1\.270/u);
  assert.throws(() => assertRulesetSheetHooks(at(269), ...shippedUpTo(270)), /1\.270/u);
  for (const edit of [(aura) => (aura.chosenKind = false), (aura) => (aura.orSeen = "yes")]) {
    const doc = structuredClone(parsedAsset);
    edit(doc.combat.conditions.find((one) => one.condition === "antipathy").auras[0]);
    assert.throws(() => assertRulesetCombat(at(278), doc), /aura is/u);
  }
  const far = structuredClone(parsedAsset);
  far.combat.conditions.find((one) => one.condition === "sympathy").auras[0].save.applies[0].saveEnds.beyond = 0;
  assert.throws(() => assertRulesetSheetHooks(at(446), far, shippedCatalogSources), /beyond is/u);
  const sources = new Map(shippedCatalogSources);
  const file = JSON.parse(sources.get("catalogs/spells.json"));
  file.entries.find((entry) => entry.id === "antipathysympathy-antipathy").mechanics.kindChoice = "red";
  sources.set("catalogs/spells.json", JSON.stringify(file));
  assert.throws(() => assertRulesetSheetHooks(at(446), parsedAsset, sources), /kindChoice is true/u);
}
