// 0.142.0 (Capability API 1.275): conditions held off rather than ended.
{
  assert.deepEqual(RULESET_HELD_OFF_MIN, { major: 1, minor: 275 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const conditions = new Map(parsedAsset.combat.conditions.map((entry) => [entry.condition, entry]));
  const spells = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries.map((entry) => [entry.id, entry]),
  );
  const creatures = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries.map((entry) => [entry.id, entry]),
  );
  // Antipathy's own fright: disadvantage in sight, its keeping away in sight or within 60 feet.
  assert.deepEqual(conditions.get("antipathy_frightened"), {
    condition: "antipathy_frightened",
    effects: ["own-attacks-disadvantage", "own-checks-disadvantage"],
    whileSourceInSight: true,
  });
  assert.deepEqual(conditions.get("antipathy_repelled"), {
    condition: "antipathy_repelled",
    effects: ["cannot-approach-source"],
    behavior: { moves: "away" },
    whileSourceInSight: true,
    orSourceWithin: 60,
  });
  assert.deepEqual(
    conditions.get("antipathy").auras[0].save.applies.map((one) => [one.condition, one.saveEnds?.beyond, one.endsWith]),
    [
      ["antipathy_frightened", 60, undefined],
      ["antipathy_repelled", undefined, "antipathy_frightened"],
    ],
  );
  // It is frightened to everything else.
  for (const holder of ["heroic", "couraged", "heroes_feast"])
    assert.deepEqual(
      ["frightened", "antipathy_frightened", "antipathy_repelled"].map((id) =>
        conditions.get(holder).conditionImmunities.includes(id),
      ),
      [true, true, true],
      holder,
    );
  assert.equal(creatures.get("zombie").creature.conditionImmunities.includes("antipathy_frightened"), false);
  const frightImmune = [...creatures.values()].filter((entry) =>
    entry.creature?.conditionImmunities?.includes("frightened"),
  );
  assert.ok(frightImmune.length > 20);
  for (const entry of frightImmune)
    assert.ok(entry.creature.conditionImmunities.includes("antipathy_repelled"), entry.id);
  assert.ok(conditions.get("countercharmed").modifiers[0].against.conditions.includes("antipathy_frightened"));
  // Calm Emotions: suppress, or indifference.
  const held = [
    "frightened",
    "antipathy_frightened",
    "antipathy_repelled",
    "fear_fleeing",
    "fear_cone_fleeing",
    // Symbol's flight from the glyph since 0.240.0.
    "symbol_fleeing",
    "charmed",
    "charmed_by_person",
    "charmed_by_creature",
    "dominated",
    "hypnotized",
    // Geas since 0.265.0.
    "geased",
  ];
  assert.deepEqual(conditions.get("calmed"), { condition: "calmed", suppresses: held });
  // Its source's whole side, and its endings, since 0.145.0.
  assert.deepEqual(conditions.get("calmed_indifferent"), {
    condition: "calmed_indifferent",
    effects: ["cannot-target-source-side"],
    endsWhen: ["attacked", "ally-harmed-in-sight"],
    endsWhenHarmedFrom: ["spells"],
  });
  for (const [id, condition] of [
    ["calm-emotions", "calmed"],
    ["calm-emotions-indifference", "calmed_indifferent"],
  ]) {
    const mechanics = spells.get(id).mechanics;
    assert.deepEqual(
      [
        mechanics.kind,
        mechanics.targets,
        mechanics.save,
        mechanics.targetTypes,
        mechanics.area,
        mechanics.applies,
        mechanics.concentration,
      ],
      [
        "debuff",
        "any",
        { save: "cha_save", onSuccess: "negates", alliesMayFail: true },
        { is: { types: ["humanoid"] } },
        { shape: "burst", size: 20 },
        [{ condition, duration: { rounds: 10 } }],
        true,
      ],
      id,
    );
  }
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  assert.equal(assertRulesetCombat(at(446), structuredClone(parsedAsset)), true);
  assert.throws(() => assertRulesetCombat(at(274), structuredClone(parsedAsset)), /1\.275/u);
  const combatBad = (edit, message) => {
    const doc = structuredClone(parsedAsset);
    edit(new Map(doc.combat.conditions.map((entry) => [entry.condition, entry])));
    assert.throws(() => assertRulesetCombat(at(278), doc), message);
  };
  combatBad((all) => delete all.get("antipathy_repelled").whileSourceInSight, /orSourceWithin/u);
  combatBad((all) => (all.get("antipathy_repelled").orSourceWithin = 0), /orSourceWithin/u);
  combatBad((all) => all.get("calmed").suppresses.push("calmed"), /suppresses/u);
  combatBad((all) => (all.get("calmed").suppresses[0] = "nothing"), /suppresses/u);
}
