  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  assert.throws(() => assertRulesetSheetHooks(at(276), ...shippedUpTo(277)), /1\.277/u);
  const sources = new Map(shippedCatalogSources);
  const doc = JSON.parse(sources.get("catalogs/features.json"));
