  bad((entries) => (port(entries).teleport.strike = 3), /teleport strike names another plain action/u);
  bad((entries) => {
    const bite = entries
      .find((entry) => entry.id === "blink-dog")
      .creature.actions.find((action) => action.id === "bite");
    bite.signature = { cost: 1 };
  }, /teleport strike names another plain action|signature/u);
