  bad("catalogs/spells.json", (entries) => (touch(entries).drain.half = true), /drain is/u);
  bad("catalogs/spells.json", (entries) => delete touch(entries).amount, /drain|amount/u);
  bad("catalogs/creatures.json", (entries) => delete drain(entries).damage, /drain is/u);
