  assert.deepEqual(magic.get("mace-of-disruption").item.worn.light, { bright: 20, dim: 20, magical: true }); // magical from 0.167.0
  const creatures = entries("catalogs/creatures.json");
  assert.deepEqual(creatures.get("fire-elemental").creature.light, { bright: 30, dim: 30 });
