  const bad = (path, id, edit) => {
    const sources = new Map(shippedCatalogSources);
    const parsed = JSON.parse(sources.get(path));
    edit(parsed.entries.find((entry) => entry.id === id));
    sources.set(path, JSON.stringify(parsed));
    assert.throws(
      () => assertRulesetSheetHooks(at(shippedManifest.capabilityApi.minor), parsedAsset, sources),
      /light is/u,
    );
  };
  bad("catalogs/creatures.json", "azer", (entry) => (entry.creature.light.glow = 5));
  bad("catalogs/equipment.json", "torch", (entry) => (entry.item.carried.light.dim = -1));
