// 0.163.0 (Capability API 1.296): lights monsters switch, and light an item sheds switched off.
{
  assert.deepEqual(RULESET_CREATURE_LIGHT_MIN, { major: 1, minor: 296 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const creatures = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries.map((entry) => [entry.id, entry.creature]),
  );
  const magmin = creatures.get("magmin");
  assert.deepEqual(magmin.light, { bright: 10, dim: 10 });
  assert.equal(magmin.unlit, true);
  assert.deepEqual(
    magmin.actions.filter((action) => action.sheds !== undefined),
    [
      { id: "ignited_illumination_ignite", name: "Ignite", budget: "bonus", sheds: { bright: 10, dim: 10 } },
      { id: "ignited_illumination_extinguish", name: "Extinguish", budget: "bonus", sheds: "out" },
    ],
  );
  const wisp = creatures.get("will-o-wisp");
  assert.deepEqual(wisp.light, { bright: 20, dim: 20 });
  assert.equal(wisp.unlit, undefined);
  assert.deepEqual(
    wisp.actions
      .filter((action) => action.sheds !== undefined)
      .map((action) => [action.name, action.budget, action.sheds]),
    [5, 10, 15, 20].map((radius) => [`Light ${radius} ft.`, "bonus", { bright: radius, dim: radius }]),
  );
  const items = new Map(
    ["catalogs/equipment.json", "catalogs/magic_items.json"].flatMap((path) =>
      JSON.parse(shippedCatalogSources.get(path)).entries.map((entry) => [entry.id, entry.item]),
    ),
  );
  assert.deepEqual(items.get("lantern-of-revealing").toggle.offLight, { bright: 0, dim: 5, magical: true }); // magical from 0.167.0
  assert.equal(items.get("gem-of-brightness").toggle.offLight, undefined);
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  assert.throws(() => assertRulesetSheetHooks(at(295), ...shippedUpTo(296)), /1\.296/u);
  const edited = (edit) => {
    const sources = new Map(shippedCatalogSources);
    const catalog = JSON.parse(sources.get("catalogs/creatures.json"));
    edit(new Map(catalog.entries.map((entry) => [entry.id, entry.creature])));
    sources.set("catalogs/creatures.json", JSON.stringify(catalog));
    return sources;
  };
  for (const [edit, message] of [
    [
      (all) => (all.get("magmin").actions.find((a) => a.sheds === "out").damage = { dice: "1d4" }),
      /carries no damage/u,
    ],
    [(all) => (all.get("magmin").actions.find((a) => a.sheds !== "out").sheds = { bright: 0, dim: 0 }), /sheds "out"/u],
    [
      (all) => (all.get("magmin").actions = all.get("magmin").actions.filter((a) => a.name !== "Ignite")),
      /unlit is true/u,
    ],
    [(all) => (all.get("will-o-wisp").unlit = false), /unlit is true/u],
  ])
    assert.throws(
      () => assertRulesetSheetHooks(at(shippedManifest.capabilityApi.minor), parsedAsset, edited(edit)),
      message,
    );
  const dark = structuredClone(parsedAsset);
  delete dark.combat.sight.darkness;
  const lantern = new Map(shippedCatalogSources);
  assert.throws(() => assertRulesetSheetHooks(at(446), dark, lantern), /combat\.sight\.darkness/u);
}
console.log("ruleset 0.163.0 creature light regression checks passed");

