// 0.203.0 (Capability API 1.411): Font of Inspiration, Superior Inspiration and Perfect Self.
{
  assert.deepEqual(RULESET_TEXTS_MIN, { major: 1, minor: 411 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const features = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/features.json")).entries.map((entry) => [entry.id, entry]),
  );
  const inspiration = features.get("bard-bardic-inspiration").rows.find((row) => row.list === "counters");
  assert.deepEqual(inspiration.scaled.recharge, {
    from: { field: "level_bard" },
    texts: [
      [1, "long"],
      [5, "short"],
    ],
  });
  assert.equal(inspiration.values.recharge, "long");
  assert.deepEqual(features.get("bard-superior-inspiration").mechanics, {
    kind: "utility",
    refillsAtInitiative: { pool: "Bardic Inspiration" },
  });
  assert.deepEqual(features.get("monk-perfect-self").mechanics, {
    kind: "utility",
    refillsAtInitiative: { pool: "Ki", amount: 4 },
  });
  assert.throws(() => assertRulesetScaled(at(410), parsedAsset, shippedCatalogSources), /of 1\.411/u);
  assert.throws(() => assertRulesetSheetHooks(at(410), ...shippedUpTo(411)), /of 1\.411/u);
  const [olderDoc, olderSources] = shippedUpTo(410);
  assert.doesNotThrow(() => assertRulesetScaled(at(410), olderDoc, olderSources));
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(410), olderDoc, olderSources));
  const editing = (id, change, check, pattern) => {
    const sources = new Map(shippedCatalogSources);
    const parsed = JSON.parse(sources.get("catalogs/features.json"));
    change(parsed.entries.find((entry) => entry.id === id));
    sources.set("catalogs/features.json", JSON.stringify(parsed));
    assert.throws(() => check(at(shippedManifest.capabilityApi.minor), parsedAsset, sources), pattern);
  };
  const recharge = (texts) => (entry) =>
    (entry.rows.find((row) => row.list === "counters").scaled.recharge.texts = texts);
  editing("bard-bardic-inspiration", recharge([[1, "dawn"]]), assertRulesetScaled, /texts are/u);
  editing(
    "bard-bardic-inspiration",
    recharge([
      [5, "short"],
      [1, "long"],
    ]),
    assertRulesetScaled,
    /texts are/u,
  );
  editing("bard-bardic-inspiration", recharge([]), assertRulesetScaled, /texts are/u);
  editing(
    "bard-bardic-inspiration",
    (entry) => (entry.rows.find((row) => row.list === "counters").scaled.recharge.table = [[1, 1]]),
    assertRulesetScaled,
    /unknown key "table"/u,
  );
  editing(
    "bard-bardic-inspiration",
    (entry) =>
      (entry.rows.find((row) => row.list === "counters").scaled.max = {
        from: { field: "level_bard" },
        texts: [[1, "x"]],
      }),
    assertRulesetScaled,
    /not a text or enum column/u,
  );
  editing(
    "bard-superior-inspiration",
    (entry) => (entry.mechanics.refillsAtInitiative.pool = "Luck"),
    assertRulesetSheetHooks,
    /no live pool or row pool/u,
  );
  editing(
    "monk-perfect-self",
    (entry) => (entry.mechanics.refillsAtInitiative.amount = 0),
    assertRulesetSheetHooks,
    /refillsAtInitiative is/u,
  );
  editing(
    "monk-perfect-self",
    (entry) => (entry.mechanics.refillsAtInitiative.when = "empty"),
    assertRulesetSheetHooks,
    /refillsAtInitiative is/u,
  );
}
console.log("ruleset 0.203.0 Font of Inspiration, Superior Inspiration and Perfect Self regression checks passed");

