// 0.212.0: Fiendish Resilience, past which a magic weapon or a silvered one gets and a spell doesn't.
{
  const catalog = (file) => JSON.parse(shippedCatalogSources.get(`catalogs/${file}.json`)).entries;
  const features = new Map(catalog("features").map((entry) => [entry.id, entry]));
  // Each damage type's choice carries the words; the feature's own row holds none since 0.428.0.
  assert.equal(
    features.get("the-fiend-fiendish-resilience-fire").rows[0].values.resist,
    "fire except magic_weapon silvered",
  );
  assert.equal(features.get("the-fiend-fiendish-resilience").rows[0].values.resist, undefined);
  assert.equal(features.get("the-fiend-fiendish-resilience").exclusive, undefined);
  assert.ok(parsedAsset.items.tags.some((tag) => tag.id === "magic_weapon"));
  const items = catalog("magic_items");
  const tagged = (id) => items.find((entry) => entry.id === id)?.item.tags.includes("magic_weapon");
  assert.ok(items.filter((entry) => entry.item?.tags?.includes("magic_weapon")).length >= 200);
  assert.deepEqual(["longsword-1", "arrow-of-slaying", "staff-of-power", "cloak-of-protection"].map(tagged), [
    true,
    true,
    true,
    false,
  ]);
  assert.ok(items.every((entry) => !entry.item?.tags?.includes("magic_weapon") || entry.item.tags.includes("magical")));
  const actions = catalog("creatures").flatMap((entry) => entry.creature?.actions ?? []);
  const qualities = actions.map((one) => one.damage?.qualities ?? []);
  assert.ok(qualities.filter((one) => one.includes("magic_weapon")).length >= 18);
  assert.ok(qualities.every((one) => !one.includes("magic_weapon") || one.includes("magical")));
  // 0.253.0: the Magic Weapon spell applies its own magic_weapon condition, no item tag.
  assert.ok(
    catalog("spells").every(
      (entry) => entry.id === "magic-weapon" || !JSON.stringify(entry.mechanics ?? {}).includes("magic_weapon"),
    ),
  );
}
console.log("ruleset 0.212.0 Fiendish Resilience regression checks passed");

