// 0.225.0 (Capability API 1.435): Beast Spells and Archdruid.
{
  assert.deepEqual(RULESET_SHAPE_KEEPS_MIN, { major: 1, minor: 435 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const derived = (id) => parsedAsset.sheet.derived.find((one) => one.id === id);
  assert.deepEqual(
    parsedAsset.sheet.derived.slice(-91, -89).map((one) => one.id),
    ["beast_spells", "archdruid"],
    "new derived values go at the end",
  );
  assert.deepEqual(
    [derived("beast_spells").table, derived("archdruid").table],
    [
      [
        [0, 0],
        [18, 1],
      ],
      [
        [0, 0],
        [20, 1],
      ],
    ],
  );
  assert.deepEqual(
    parsedAsset.combat.levels.filter((one) => one.shapeKeeps || one.waives).map(({ rowsWhere, ...one }) => one),
    [
      { derived: "beast_spells", at: 1, shapeKeeps: ["spells/*"] },
      { derived: "archdruid", at: 1, waives: ["verbal", "somatic", "material"] },
    ],
  );
  assert.deepEqual(
    parsedAsset.combat.components.map((one) => one.id),
    ["verbal", "somatic", "material", "material_cost"],
  );
  assert.deepEqual(parsedAsset.combat.conditions.find((one) => one.condition === "wild_shaped").forbids, {
    components: ["material", "material_cost"],
  });
  const spells = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries.map((entry) => [entry.id, entry]),
  );
  // A material with a cost or consumed is material_cost too, the source's flags or the printed material.
  for (const id of ["revivify", "stoneskin", "raise-dead", "identify", "greater-restoration"])
    assert.ok(spells.get(id).mechanics.components.includes("material_cost"), id);
  for (const id of ["fireball", "acid-arrow", "barkskin"])
    assert.ok(!spells.get(id).mechanics.components.includes("material_cost"), id);
  assert.throws(() => assertRulesetSheetHooks(at(434), ...shippedUpTo(435)), /of 1\.435/u);
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(434), ...shippedUpTo(434)));
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(435), ...shippedUpTo(435)));
  const editing = (change, pattern) => {
    const doc = structuredClone(parsedAsset);
    change(
      doc.combat.levels.find((one) => one.shapeKeeps),
      doc.combat.levels.find((one) => one.waives),
    );
    assert.throws(
      () => assertRulesetSheetHooks(at(shippedManifest.capabilityApi.minor), doc, shippedCatalogSources),
      pattern,
    );
  };
  editing((keeps) => (keeps.shapeKeeps = []), /shapeKeeps is a list/u);
  editing((keeps) => (keeps.shapeKeeps = ["no_such_catalog/*"]), /shapeKeeps is a list/u);
  editing((keeps) => (keeps.shapeKeeps = ["spells/*", "spells/*"]), /shapeKeeps is a list/u);
  editing((_, waives) => (waives.waives = ["thought"]), /waives is a list of the fight's components/u);
  editing((_, waives) => (waives.waives = []), /waives is a list of the fight's components/u);
}
