  assert.throws(() => assertRulesetSheetHooks(at(452), ...shippedUpTo(453)), /detonates becomes, of 1\.453/u);
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(452), ...shippedUpTo(452)));
