// 0.241.0 (Capability API 1.458 to 1.462): Magic Circle reversed wards those outside, Hallow frees and
// binds an extra effect, minute-long casting over ten rounds, and glyphs and Hallow set up before a fight.
{
  assert.deepEqual(RULESET_KEEPS_IN_WARDS_MIN, { major: 1, minor: 458 });
  assert.deepEqual(RULESET_FREES_MIN, { major: 1, minor: 459 });
  assert.deepEqual(RULESET_INSIDE_TEST_MIN, { major: 1, minor: 460 });
  assert.deepEqual(RULESET_CASTING_ROUNDS_MIN, { major: 1, minor: 461 });
  assert.deepEqual(RULESET_BEFORE_FIGHT_MIN, { major: 1, minor: 462 });
  assert.ok(shippedManifest.capabilityApi.minor >= 462);
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const spells = JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries;
  const byId = new Map(spells.map((one) => [one.id, one.mechanics]));
  const cantGive = byId.get("magic-circle").zone.keepsOut.cantGive;
  // "preventing a creature of the specified type from leaving the cylinder and protecting targets outside it"
  for (const id of ["magic-circle-reversed", "magic-circle-reversed-fiend"])
    assert.deepEqual(
      [byId.get(id).zone.keepsOut.way, byId.get(id).zone.keepsOut.attacksInto, byId.get(id).zone.keepsOut.cantGive],
      ["out", "disadvantage", cantGive],
      id,
    );
  // "Any creature charmed, frightened, or possessed by such a creature is no longer ... upon entering the area."
  assert.deepEqual(byId.get("hallow").zone.keepsOut.frees, byId.get("hallow").zone.keepsOut.cantGive);
  // Hallow's extra effects, each its own entry, a Charisma save to ignore one until leaving.
  const types = ["acid", "cold", "fire", "force", "lightning", "necrotic", "poison", "psychic", "radiant", "thunder"];
  assert.deepEqual(
    spells.filter((one) => one.id.startsWith("hallow-")).map((one) => one.id),
    [
      "hallow-courage",
      "hallow-darkness",
      "hallow-daylight",
      ...types.map((type) => `hallow-energy-protection-${type}`),
      ...types.map((type) => `hallow-energy-vulnerability-${type}`),
      // Since 0.242.0.
      "hallow-extradimensional-interference",
      "hallow-fear",
      "hallow-silence",
    ],
  );
  // Each on a creature type picked as it is cast since 0.242.0.
  const save = { save: "cha_save", ignoresUntilLeaves: true };
  const chooses = "type";
  assert.deepEqual(byId.get("hallow-courage").zone.inside, { conditions: ["couraged"], save, chooses });
  assert.deepEqual(byId.get("hallow-fear").zone.inside, { conditions: ["frightened"], save, chooses });
  assert.deepEqual(byId.get("hallow-energy-protection-force").zone.inside, {
    conditions: ["resist_force"],
    save,
    chooses,
  });
  assert.deepEqual(byId.get("hallow-energy-vulnerability-fire").zone.inside, {
    conditions: ["hallow_vulnerable_fire"],
    save,
    chooses,
  });
  assert.deepEqual(
    parsedAsset.combat.conditions.find((entry) => entry.condition === "hallow_vulnerable_fire").vulnerable,
    ["fire"],
  );
  assert.deepEqual(byId.get("hallow-darkness").zone.dispelsLight, { upTo: 4 });
  assert.deepEqual(
    [byId.get("hallow-daylight").zone.lights, byId.get("hallow-daylight").zone.dispelsDark],
    [
      { bright: 60, dim: 0 },
      { upTo: 4, within: 60 },
    ],
  );
  assert.deepEqual(byId.get("hallow-silence").zone.forbids, { components: ["verbal"] });
  // A minute to cast is ten rounds; longer, a zone is set up before a fight only.
  for (const id of ["magic-circle", "symbol", "symbol-fear", "conjure-elemental", "foresight", "regenerate"])
    assert.equal(byId.get(id).castingRounds, 10, id);
  assert.equal(byId.get("fireball").castingRounds, undefined);
  // Every other spell that long since 0.242.0.
  for (const one of spells.filter((entry) => /^(glyph-of-warding|hallow)(-|$)/u.test(entry.id)))
    assert.equal(one.mechanics?.beforeFight, true, one.id);
  // SRD 5.1, Spell Scroll: "you can use an action to read the scroll and cast its spell", whatever its
  // casting time: a scroll of Symbol is read in one action, a scroll of Glyph of Warding in a fight.
  const scrolls = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries.map((one) => [one.id, one.item]),
  );
  assert.deepEqual(
    [
      scrolls.get("spell-scroll-symbol").use.castingRounds,
      scrolls.get("spell-scroll-glyph-of-warding").use.beforeFight,
      scrolls.get("spell-scroll-glyph-of-warding").use.budget,
    ],
    [undefined, undefined, "action"],
  );
  assert.throws(() => assertRulesetSheetHooks(at(461), ...shippedUpTo(462)), /beforeFight, of 1\.462/u);
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(461), ...shippedUpTo(461)));
  assert.throws(() => assertRulesetSheetHooks(at(460), ...shippedUpTo(461)), /castingRounds, of 1\.461/u);
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(460), ...shippedUpTo(460)));
  assert.throws(() => assertRulesetSheetHooks(at(459), ...shippedUpTo(460)), /zone inside is or save, of 1\.460/u);
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(459), ...shippedUpTo(459)));
  assert.throws(() => assertRulesetSheetHooks(at(458), ...shippedUpTo(459)), /zone keepsOut frees, of 1\.459/u);
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(458), ...shippedUpTo(458)));
  assert.throws(() => assertRulesetSheetHooks(at(457), ...shippedUpTo(458)), /warding those outside, of 1\.458/u);
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(457), ...shippedUpTo(457)));
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  const changing = (id, change, pattern) => {
    const sources = new Map(shippedCatalogSources);
    const parsed = JSON.parse(sources.get("catalogs/spells.json"));
    change(parsed.entries.find((one) => one.id === id).mechanics);
    sources.set("catalogs/spells.json", JSON.stringify(parsed));
    assert.throws(() => assertRulesetSheetHooks(at(492), parsedAsset, sources), pattern);
  };
  changing("hallow", (mechanics) => (mechanics.zone.keepsOut.frees = ["not_a_condition"]), /up to 12 it frees/u);
  changing("hallow", (mechanics) => (mechanics.zone.keepsOut.frees = []), /up to 12 it frees/u);
  changing(
    "hallow-fear",
    (mechanics) => (mechanics.zone.inside.save = { save: "luck_save", ignoresUntilLeaves: true }),
    /inside is is a target test/u,
  );
  changing(
    "hallow-fear",
    (mechanics) => (mechanics.zone.inside.save = { save: "cha_save" }),
    /inside is is a target test/u,
  );
  changing(
    "hallow-fear",
    (mechanics) => {
      delete mechanics.zone.inside.chooses;
      mechanics.zone.inside.is = { types: ["angel"] };
    },
    /inside is is a target test/u,
  );
  changing("symbol", (mechanics) => (mechanics.castingRounds = 11), /castingRounds is 2 to 10/u);
  changing("symbol", (mechanics) => (mechanics.castingRounds = 1), /castingRounds is 2 to 10/u);
  changing("fireball", (mechanics) => (mechanics.beforeFight = "yes"), /beforeFight is true/u);
  changing("hallow", (mechanics) => (mechanics.beforeFight = "yes"), /beforeFight is true/u);
}
