// 0.248.0 (Capability API 1.487 to 1.490): a familiar's type and only one's own, Pact of the Chain's lent
// attack, the Ring of Free Action's hard going, Holy Aura's flash and Prismatic Wall's layers.
{
  assert.deepEqual(RULESET_FAMILIARS_MIN, { major: 1, minor: 487 });
  assert.deepEqual(RULESET_LENDS_STRIKES_MIN, { major: 1, minor: 488 });
  assert.deepEqual(RULESET_WHEN_HIT_MIN, { major: 1, minor: 489 });
  assert.deepEqual(RULESET_ZONE_LAYERS_MIN, { major: 1, minor: 490 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const catalog = (file) => JSON.parse(shippedCatalogSources.get(`catalogs/${file}.json`)).entries;
  const spells = new Map(catalog("spells").map((one) => [one.id, one.mechanics]));
  const features = new Map(catalog("features").map((one) => [one.id, one]));
  const items = new Map(catalog("magic_items").map((one) => [one.id, one.item]));
  const conditions = new Map(parsedAsset.combat.conditions.map((entry) => [entry.condition, entry]));
  const sheet = new Set(parsedAsset.sheet.live.conditions.map((entry) => entry.id));
  // Find Familiar: "it is a celestial, fey, or fiend (your choice) instead of a beast"; the pact's four
  // special forms keep their own.
  for (const id of ["find-familiar", "spell-mastery-find-familiar"]) {
    const mechanics = id === "find-familiar" ? spells.get(id) : features.get(id).mechanics;
    assert.deepEqual(mechanics.calls.asTypes, ["celestial", "fey", "fiend"], id);
  }
  assert.deepEqual(items.get("spell-scroll-find-familiar").use.calls, spells.get("find-familiar").calls);
  // Since 0.425.0 the pact's copy calls every form, as a celestial, fey or fiend.
  assert.deepEqual(spells.get("find-familiar-pact-of-the-chain").calls.asTypes, ["celestial", "fey", "fiend"]);
  // "You learn the find familiar spell": the pact's own copy, one row since 0.425.0.
  assert.deepEqual(
    features
      .get("pact-of-the-chain")
      .rows.slice(1)
      .map((row) => row.values.name),
    ["Find Familiar (Pact of the Chain)"],
  );
  // "your familiar": seeing through its eyes and Voice of the Chain Master, only one's own.
  assert.deepEqual(spells.get("find-familiar-see").targetTypes, { calledBySelf: true });
  assert.deepEqual(features.get("invocation-voice-of-the-chain-master").mechanics.targetTypes, { calledBySelf: true });
  assert.deepEqual(features.get("invocation-gaze-of-two-minds").mechanics.targetTypes, { is: { types: ["humanoid"] } });
  // Pact of the Chain: "forgo one of your own attacks to allow your familiar to make one attack of its
  // own with its reaction", on the bond while the sheet holds the pact.
  assert.deepEqual(conditions.get("familiar_chain"), {
    condition: "familiar_chain",
    lendsStrikes: { budget: "reaction" },
  });
  assert.ok(sheet.has("familiar_chain"));
  for (const id of ["find-familiar", "find-familiar-pact-of-the-chain"])
    assert.deepEqual(spells.get(id).appliesSelf.at(-1), {
      condition: "familiar_chain",
      duration: { rounds: 14400 },
      when: { value: { derived: "pact_chain" }, atLeast: 1 },
    });
  // Ring of Free Action: "difficult terrain doesn't cost you extra movement".
  assert.equal(items.get("ring-of-free-action").worn.ignoresHardGround, true);
  // Holy Aura: "Creatures of your choice in that radius when you cast this spell", and "when a fiend or
  // an undead hits an affected creature with a melee attack ... Constitution saving throw or be blinded
  // until the spell ends", at the caster's DC: the ward on each chosen, the scroll's at its own DC.
  assert.deepEqual(
    [spells.get("holy-aura").targets, spells.get("holy-aura").range, spells.get("holy-aura").targetCount],
    ["ally", 30, 12],
  );
  assert.equal(items.get("spell-scroll-holy-aura").use.saveDifficulty, 18);
  assert.deepEqual(conditions.get("holy_aura_warded").whenHit, {
    blow: "melee",
    from: { types: ["fiend", "undead"] },
    save: { save: "con_save" },
    applies: [{ condition: "blinded", duration: { rounds: 10 } }],
  });
  // Prismatic Wall: a wall 90 feet long or a sphere 30 across, seven layers each a Dexterity save.
  const wall = spells.get("prismatic-wall");
  assert.deepEqual(
    [wall.kind, wall.area, wall.save, wall.amount, wall.concentration],
    [
      "attack",
      { shape: "wall", size: 90, ring: 30 },
      { save: "dex_save", onSuccess: "half" },
      { dice: "10d6" },
      undefined,
    ],
  );
  assert.deepEqual(wall.applies, spells.get("prismatic-spray").applies);
  assert.deepEqual(
    [wall.zone.rounds, wall.zone.triggers, wall.zone.atCast, wall.zone.lights],
    [100, ["enter"], false, { bright: 100, dim: 100 }],
  );
  // Opaque, and since 0.249.0 its layers say what passes and it spares whom its caster picks.
  const layers = wall.zone.layers;
  assert.deepEqual(
    layers.rows.map((row) => [row.id, row.damageType ?? row.applies?.[0], row.endedBy]),
    [
      ["red", "fire", { damage: { types: ["cold"], atLeast: 25 } }],
      ["orange", "acid", { wind: true }],
      ["yellow", "lightning", { damage: { types: ["force"], atLeast: 60 } }],
      ["green", "poison", { entries: ["spells/passwall"] }],
      ["blue", "cold", { damage: { types: ["fire"], atLeast: 25 } }],
      ["indigo", "restrained", { entries: ["spells/daylight"] }],
      ["violet", "blinded", { entries: ["spells/dispel-magic"] }],
    ],
  );
  assert.deepEqual(layers.flash, {
    within: 20,
    save: "con_save",
    applies: [{ condition: "blinded", duration: { rounds: 10 } }],
    triggers: ["appears", "enter", "turn-start"],
  });
  assert.deepEqual(items.get("spell-scroll-prismatic-wall").use.zone, wall.zone);
  // Each gated at its own minor.
  assert.doesNotThrow(() => assertRulesetCombat(at(492), parsedAsset));
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  for (const [minor, pattern] of [
    [490, /zone of layers, of 1\.490/u],
    [489, /of 1\.489/u],
    [488, /lending strikes, of 1\.488/u],
    [487, /of 1\.487/u],
  ]) {
    assert.throws(() => assertRulesetSheetHooks(at(minor - 1), ...shippedUpTo(minor)), pattern);
    assert.doesNotThrow(() => assertRulesetSheetHooks(at(minor - 1), ...shippedUpTo(minor - 1)));
  }
  const conditionChanging = (condition, change, pattern) => {
    const doc = structuredClone(parsedAsset);
    change(doc.combat.conditions.find((entry) => entry.condition === condition));
    assert.throws(
      () => assertRulesetSheetHooks(at(shippedManifest.capabilityApi.minor), doc, shippedCatalogSources),
      pattern,
    );
  };
  conditionChanging("familiar_chain", (entry) => (entry.lendsStrikes = { budget: "nobody" }), /lendsStrikes is/u);
  conditionChanging("holy_aura_warded", (entry) => (entry.whenHit.from = { types: ["golem"] }), /whenHit is/u);
  conditionChanging("holy_aura_warded", (entry) => (entry.whenHit.save = { save: "luck_save" }), /whenHit is/u);
  conditionChanging("holy_aura_warded", (entry) => (entry.whenHit.applies = []), /whenHit is/u);
  const changing = (file, id, change, pattern) => {
    const sources = new Map(shippedCatalogSources);
    const parsed = JSON.parse(sources.get(`catalogs/${file}.json`));
    change(parsed.entries.find((one) => one.id === id));
    sources.set(`catalogs/${file}.json`, JSON.stringify(parsed));
    assert.throws(
      () => assertRulesetSheetHooks(at(shippedManifest.capabilityApi.minor), parsedAsset, sources),
      pattern,
    );
  };
  changing(
    "spells",
    "find-familiar",
    (entry) => (entry.mechanics.calls.asTypes = ["angel"]),
    /asTypes is 1 to 6 declared creature types/u,
  );
  changing(
    "spells",
    "find-familiar-see",
    (entry) => (entry.mechanics.targetTypes.calledBySelf = false),
    /calledBySelf is true/u,
  );
  changing(
    "magic_items",
    "ring-of-free-action",
    (entry) => (entry.item.worn.ignoresHardGround = 1),
    /ignoresHardGround is true/u,
  );
  changing("spells", "prismatic-wall", (entry) => delete entry.mechanics.save, /zone layers is/u);
  changing(
    "spells",
    "prismatic-wall",
    (entry) => (entry.mechanics.zone.layers.rows[5].applies = ["charmed"]),
    /zone layer "indigo"/u,
  );
  changing(
    "spells",
    "prismatic-wall",
    (entry) => (entry.mechanics.zone.layers.rows[0].endedBy = {}),
    /zone layer "red"/u,
  );
  changing(
    "spells",
    "prismatic-wall",
    (entry) => (entry.mechanics.zone.layers.rows[3].endedBy.entries = ["nowhere/passwall"]),
    /zone layer "green"/u,
  );
  changing(
    "spells",
    "prismatic-wall",
    (entry) => (entry.mechanics.zone.layers.flash.triggers = ["turn-end"]),
    /flash is/u,
  );
}
