// 0.249.0 (Capability API 1.491 to 1.492): Passwall breaks Prismatic Wall's green layer, the wall's
// layers stop arrows, magic and spells passing, and it spares the creatures its caster designates.
{
  assert.deepEqual(RULESET_ENDS_LAYERS_MIN, { major: 1, minor: 491 });
  assert.deepEqual(RULESET_LAYER_BLOCKS_MIN, { major: 1, minor: 492 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const catalog = (file) => JSON.parse(shippedCatalogSources.get(`catalogs/${file}.json`)).entries;
  const spells = new Map(catalog("spells").map((one) => [one.id, one.mechanics]));
  const items = new Map(catalog("magic_items").map((one) => [one.id, one.item]));
  // Passwall: "A passwall spell ... destroys this layer", aimed at a wall within its 30 feet.
  assert.deepEqual(
    [spells.get("passwall").kind, spells.get("passwall").range, spells.get("passwall").endsLayers],
    ["utility", 30, true],
  );
  // An item's use that only breaks a layer was refused on 1.492, so the scroll stayed one of text until
  // 0.250.0 (1.494).
  assert.equal(shippedUpTo(492)[1].get("catalogs/magic_items.json").includes('"endsLayersAs"'), false);
  // Prismatic Wall: opaque, so it obscures and lets its layers say what passes; "nonmagical ranged
  // attacks", "magical ranged attacks" and "spells can't be cast through the wall"; "You and creatures
  // you designate at the time you cast the spell".
  const wall = spells.get("prismatic-wall");
  assert.deepEqual([wall.zone.blocks, wall.zone.obscures], [undefined, {}]);
  assert.deepEqual(wall.zone.layers.spares, { chosen: 20 });
  assert.deepEqual(
    wall.zone.layers.rows.map((row) => [row.id, row.blocks]),
    [
      ["red", ["ranged-nonmagical"]],
      ["orange", ["ranged-magical"]],
      ["yellow", undefined],
      ["green", undefined],
      ["blue", undefined],
      ["indigo", ["spells"]],
      ["violet", undefined],
    ],
  );
  assert.deepEqual(items.get("spell-scroll-prismatic-wall").use.zone, wall.zone);
  // Each gated at its own minor.
  assert.doesNotThrow(() => assertRulesetCombat(at(492), parsedAsset));
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  for (const [minor, pattern] of [
    [492, /block or spare as picked, of 1\.492/u],
    [491, /breaking a wall's layer, of 1\.491/u],
  ]) {
    assert.throws(() => assertRulesetSheetHooks(at(minor - 1), ...shippedUpTo(minor)), pattern);
    assert.doesNotThrow(() => assertRulesetSheetHooks(at(minor - 1), ...shippedUpTo(minor - 1)));
  }
  const changing = (id, change, pattern) => {
    const sources = new Map(shippedCatalogSources);
    const parsed = JSON.parse(sources.get("catalogs/spells.json"));
    change(parsed.entries.find((one) => one.id === id));
    sources.set("catalogs/spells.json", JSON.stringify(parsed));
    assert.throws(
      () => assertRulesetSheetHooks(at(shippedManifest.capabilityApi.minor), parsedAsset, sources),
      pattern,
    );
  };
  changing("passwall", (entry) => (entry.mechanics.endsLayers = "green"), /endsLayers is true/u);
  changing("prismatic-wall", (entry) => (entry.mechanics.zone.layers.rows[0].blocks = ["arrows"]), /zone layer "red"/u);
  changing(
    "prismatic-wall",
    (entry) => (entry.mechanics.zone.layers.rows[5].blocks = ["spells", "spells"]),
    /zone layer "indigo"/u,
  );
  changing("prismatic-wall", (entry) => (entry.mechanics.zone.layers.spares = { chosen: 21 }), /zone layers is/u);
  changing("prismatic-wall", (entry) => (entry.mechanics.zone.layers.spares = "everyone"), /zone layers is/u);
}
