// 0.250.0 (Capability API 1.493 to 1.494): Glibness, Detect Evil and Good, Meteor Swarm's four spheres,
// Sacred Weapon, the scroll of Passwall at a Prismatic Wall, and the rows that stand for their spells.
{
  assert.deepEqual(RULESET_STANDS_FOR_MIN, { major: 1, minor: 493 });
  assert.deepEqual(RULESET_ITEM_ENDS_LAYERS_MIN, { major: 1, minor: 494 });
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const catalog = (file) => JSON.parse(shippedCatalogSources.get(`catalogs/${file}.json`)).entries;
  const spells = new Map(catalog("spells").map((one) => [one.id, one.mechanics]));
  const items = new Map(catalog("magic_items").map((one) => [one.id, one.item]));
  const features = new Map(catalog("features").map((one) => [one.id, one]));
  const conditions = new Map(parsedAsset.combat.conditions.map((one) => [one.condition, one]));
  // Glibness: "you can replace the number you roll with a 15" on a Charisma check, for an hour.
  assert.deepEqual(spells.get("glibness").applies, [{ condition: "glib", duration: { rounds: 600 } }]);
  assert.deepEqual(conditions.get("glib").checkFloor, { face: 15, abilities: ["cha"] });
  // Detect Evil and Good: concentration up to 10 minutes, the six types within 30 feet.
  assert.deepEqual(spells.get("detect-evil-and-good").applies, [
    { condition: "detecting_evil_and_good", duration: { rounds: 100 } },
  ]);
  assert.deepEqual(conditions.get("detecting_evil_and_good").aware.of.types, [
    "aberration",
    "celestial",
    "elemental",
    "fey",
    "fiend",
    "undead",
  ]);
  // Meteor Swarm: "four different points you can see within range" of 1 mile.
  const meteor = spells.get("meteor-swarm");
  assert.deepEqual([meteor.range, meteor.area.copies], [5280, 4]);
  // Sacred Weapon: Channel Divinity, a minute, Charisma modifier (at least +1) to weapon attack rolls.
  const sacred = features.get("oath-of-devotion-channel-divinity-sacred-weapon");
  assert.equal(sacred.mechanics.usesOf, "Channel Divinity");
  assert.deepEqual(sacred.mechanics.applies, [{ condition: "sacred_weapon", duration: { rounds: 10 } }]);
  assert.deepEqual(conditions.get("sacred_weapon").modifiers, [
    { to: "attacks", attacks: "weapon", add: { derived: "sacred_weapon_bonus" } },
  ]);
  assert.ok(parsedAsset.sheet.derived.some((one) => one.id === "sacred_weapon_bonus"));
  // A scroll of Passwall breaks the green layer as the spell does.
  assert.deepEqual(
    [items.get("spell-scroll-passwall").use.endsLayers, items.get("spell-scroll-passwall").use.endsLayersAs],
    [true, "spells/passwall"],
  );
  // Pact of the Chain's Find Familiar (its one row since 0.425.0) and the tiefling's spells stand for the spells they copy.
  const standing = [...catalog("features"), ...catalog("races")]
    .flatMap((one) => (one.rows ?? []).map((row) => row.standsFor))
    .filter(Boolean);
  assert.ok(standing.includes("spells/find-familiar-pact-of-the-chain"));
  assert.ok(standing.includes("spells/thaumaturgy"));
  // Each gated at its own minor.
  assert.doesNotThrow(() => assertRulesetCombat(at(494), parsedAsset));
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  for (const minor of [481, 480]) {
    assert.throws(
      () => assertRulesetSheetHooks(at(minor - 1), ...shippedUpTo(minor)),
      new RegExp(`of 1\\.${minor}`, "u"),
    );
    assert.doesNotThrow(() => assertRulesetSheetHooks(at(minor - 1), ...shippedUpTo(minor - 1)));
  }
}
