  const conditions = new Map(parsedAsset.combat.conditions.map((one) => [one.condition, one]));
  // "you can move through a hostile creature's space only if the creature is at least two sizes larger or
  // smaller than you ... another creature's space is difficult terrain for you."
  assert.deepEqual(parsedAsset.combat.sizes.passing, { apart: 2, crowded: 2 });
  // Halfling Nimbleness, kept on by the race beside Lucky.
  assert.deepEqual(catalog("races").find((one) => one.id === "halfling").mechanics.keepsOn, [
    "lucky",
    "halfling_nimbleness",
  ]);
  assert.equal(conditions.get("halfling_nimbleness").passesCreatures, "larger");
  // Incorporeal Movement: through creatures and objects, 1d10 force ending a turn inside an object.
  assert.deepEqual(
    [conditions.get("incorporeal_movement").passesCreatures, conditions.get("incorporeal_movement").passesObjects],
    ["any", { harm: { dice: "1d10", damageType: "force" } }],
  );
  for (const id of ["ghost", "specter", "wraith", "will-o-wisp"])
    assert.ok(creatures.get(id).keepsOn.includes("incorporeal_movement"), id);
  for (const id of ["air-elemental", "water-elemental"])
    assert.ok(creatures.get(id).keepsOn.includes("elemental_form"), id);
  // 0.253.0: the fire elemental keeps on its own Fire Form, which passes as Elemental Form does.
  assert.ok(creatures.get("fire-elemental").keepsOn.includes("fire_form"));
  // Mounted combat: one size larger, Dash, Disengage and Dodge, a DC 10 Dexterity save or prone.
  assert.deepEqual(parsedAsset.combat.mounts, {
    larger: 1,
    // Riders weighed for Carpet of Flying since 0.295.0.
    weights: {
      bySize: { tiny: 7, small: 40, medium: 150, large: 900, huge: 5400, gargantuan: 32000 },
      sheet: { derived: "rider_weight" },
    },
    controlled: { standard: ["dash", "disengage", "dodge"] },
    fall: { save: "dex_save", difficulty: 10, applies: "prone", when: ["prone"], landsWith: "reaction" },
  });
  // "Intelligent creatures, such as dragons, act independently"; a warhorse is controlled.
  assert.deepEqual(
    ["adult-red-dragon", "pegasus", "warhorse", "riding-horse", "imp"].map(
      (id) => creatures.get(id).mountIndependent ?? false,
    ),
    [true, true, false, false, false],
  );
