  for (const [gate, minor] of gates) assert.deepEqual(gate, { major: 1, minor });
  assert.ok(shippedManifest.capabilityApi.minor >= 616);
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
