  const items = new Map(catalog("magic_items").map((one) => [one.id, one.item]));
  const creatures = new Map(catalog("creatures").map((one) => [one.id, one.creature]));
  const spells = new Map(catalog("spells").map((one) => [one.id, one.mechanics]));
  const conditions = new Map(parsedAsset.combat.conditions.map((one) => [one.condition, one]));
  assert.ok(parsedAsset.combat.conditions.length <= 640);
  assert.deepEqual(conditions.get("water_walking"), { condition: "water_walking", effects: [], walksOnLiquid: true });
  assert.deepEqual(spells.get("water-walk").applies, [{ condition: "water_walking", duration: { rounds: 600 } }]);
  assert.equal(spells.get("water-walk").targetCount, 10);
  assert.deepEqual(items.get("ring-of-water-walking").worn, { keepsOn: ["water_walking"] });
  assert.deepEqual(conditions.get("netted").cutFree, { defense: 10, health: 5, damageTypes: ["slashing"] });
  assert.deepEqual(conditions.get("netted").effects, conditions.get("restrained").effects);
  const formless = [...creatures].filter(([, one]) => one.tags?.includes("formless")).map(([id]) => id);
  assert.deepEqual(formless, [
    "air-elemental",
    "black-pudding",
    "fire-elemental",
    "gray-ooze",
    "ochre-jelly",
    "shadow",
    "water-elemental",
  ]);
  assert.deepEqual(spells.get("antimagic-field").zone.suppresses, {
    catalogs: ["spells"],
    tags: ["magical"],
    setsAsideCalled: true,
  });
  const staff = items.get("staff-of-thunder-and-lightning");
