  changing((doc) => (condition(doc, "water_walking").walksOnLiquid = "yes"), /walksOnLiquid is true/u);
  changing((doc) => (condition(doc, "netted").cutFree.health = 0), /cutFree is/u);
  changing((doc) => (condition(doc, "netted").cutFree.damageTypes = []), /cutFree is/u);
