  assert.equal(spells.get("giant-insect").calls.initiative, "after");
  assert.deepEqual(spells.get("find-steed").calls.asTypes, ["celestial", "fey", "fiend"]);
  assert.equal(spells.get("find-steed").calls.options.length, 5);
