  editing((items) => (items.get("rod-of-absorption").charges.rolled = "d10"), /charges rolled is dice/u);
  editing((items) => (items.get("ring-of-spell-storing").stores.found.levels = "nothing"), /stores is/u);
  editing((items) => (items.get("ring-of-spell-storing").stores.found.from[0].level = 6), /stores is/u);
