  assert.doesNotThrow(() => assertRulesetSheetHooks(at(597), ...shippedUpTo(597)));
  assert.throws(() => assertRulesetSheetHooks(at(596), ...shippedUpTo(597)), /over 12, of 1\.597/u);
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(596), ...shippedUpTo(596)));
  const contests = new Map(parsedAsset.combat.contests.map((one) => [one.id, one]));
  // And breaking the Rope of Entanglement (0.295.0).
