// 0.292.0 (Capability API 1.617 to 1.621): the Pipes of the Sewers played, the Staff of the Python's reach, and
// what a treant or a summoning spell calls set down within range.
{
  assert.ok(shippedManifest.capabilityApi.minor >= 621);
  const items = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries.map((one) => [one.id, one.item]),
  );
  const pipes = items.get("pipes-of-the-sewers");
  const wind = { value: { derived: "wind_instrument_proficiencies" }, atLeast: 1 };
  assert.deepEqual([pipes.use.label, pipes.use.userHolds, pipes.use.usableWhen], ["Call Swarms", ["piping"], wind]);
  const [play, sway] = pipes.moreUses.map((more) => more.use);
  assert.deepEqual(
    [play.budget, play.targets, play.usableWhen, play.applies],
    ["action", "self", wind, [{ condition: "piping", duration: { rounds: 2 } }]],
  );
  assert.deepEqual(
    [sway.free, sway.budget, sway.userHolds, sway.contest.onLose, sway.targetTypes, sway.applies],
    [
      true,
      undefined,
      ["piping"],
      { applies: [{ condition: "pipes_spurned", rounds: 14400 }] },
      { is: { tags: ["rat_swarm"] }, uncontrolled: true, not: { holding: ["pipes_spurned", "piped"] } },
      [{ condition: "piped", duration: "until-dispelled" }],
    ],
  );
  assert.deepEqual(pipes.worn, {
    ignoredBy: { entries: ["creatures/rat", "creatures/giant-rat", "creatures/swarm-of-rats"], untilHarmed: true },
  });
  const piped = parsedAsset.combat.conditions.find((one) => one.condition === "piped");
  assert.deepEqual(
    [piped.endsWhenSource, piped.endsWhenHolder, piped.onEnd],
    [
      { lacks: ["piping"] },
      { cantHearSource: { sense: "hearing" } },
      { when: ["cantHearSource"], applies: [{ condition: "pipes_spurned", duration: { rounds: 14400 } }] },
    ],
  );
  const wanting = parsedAsset.sheet.derived.find((one) => one.id === "wind_instrument_proficiencies");
  assert.deepEqual(
    [wanting.id, wanting.op, wanting.of.map((one) => one.listSum.where.equals)],
    [
      "wind_instrument_proficiencies",
      "sum",
      ["Tools: bagpipes", "Tools: flute", "Tools: horn", "Tools: pan flute", "Tools: shawm"],
    ],
  );
  assert.equal(items.get("staff-of-the-python").use.calls.commandedWithin, 60);
  const treant = JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries.find(
    (one) => one.id === "treant",
  );
  assert.deepEqual(treant.creature.actions.find((one) => one.id === "animate_trees").calls.within, {
    distance: 60,
    seen: true,
  });
  const spells = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries.map((one) => [one.id, one.mechanics]),
  );
  assert.deepEqual(
    ["conjure-animals", "conjure-elemental", "find-steed", "project-image"].map((id) => spells.get(id).calls.within),
    [{ distance: 60, seen: true }, { distance: 100 }, { distance: 30 }, { distance: 500 }],
  );
  const below = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const gated = (minor, pattern) =>
    assert.throws(() => assertRulesetSheetHooks(below(minor), parsedAsset, shippedCatalogSources), pattern);
  gated(619, /of 1\.621/u);
  const changedCatalog = (file, change, pattern) => {
    const sources = new Map(shippedCatalogSources);
    const parsed = JSON.parse(sources.get(`catalogs/${file}.json`));
    change(new Map(parsed.entries.map((one) => [one.id, one])));
    sources.set(`catalogs/${file}.json`, JSON.stringify(parsed));
    assert.throws(() => assertRulesetSheetHooks(shippedManifest, parsedAsset, sources), pattern);
  };
  changedCatalog(
    "magic_items",
    (all) => (all.get("pipes-of-the-sewers").item.use.userHolds = ["no_such_condition"]),
    /userHolds is 1 to 8 conditions/u,
  );
  changedCatalog(
    "magic_items",
    (all) => (all.get("pipes-of-the-sewers").item.moreUses[1].use.contest.onLose.applies[0].rounds = 0),
    /contest onLose is/u,
  );
  changedCatalog(
    "magic_items",
    (all) => (all.get("pipes-of-the-sewers").item.worn.ignoredBy.entries = ["creatures/no-such-rat"]),
    /worn ignoredBy is/u,
  );
  changedCatalog(
    "magic_items",
    (all) => (all.get("staff-of-the-python").item.use.calls.commandedWithin = -60),
    /commandedWithin a distance/u,
  );
  changedCatalog(
    "spells",
    (all) => (all.get("conjure-animals").mechanics.calls.within = { distance: 60, seen: false }),
    /within \{ distance, seen\? \}/u,
  );
}
