// 0.300.0 (Capability API 1.648 to 1.654) and 0.301.0 (1.655 to 1.661): languages, true sight, safe falls,
// choking dust, gases, the Holy Avenger's aura, the robe seen, the Pearl of Power, arrows of slaying, the
// missile-drawing shield, the Cube of Force's first faces, the Broom of Flying and the cleric's gear.
{
  const catalog = (file) =>
    new Map(JSON.parse(shippedCatalogSources.get(`catalogs/${file}.json`)).entries.map((one) => [one.id, one]));
  const creatures = catalog("creatures");
  const items = catalog("magic_items");
  const spells = catalog("spells");
  const conditions = new Map(parsedAsset.combat.conditions.map((one) => [one.condition, one]));
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const both = (manifest, doc, sources) => {
    assertRulesetCombat(manifest, doc);
    assertRulesetSheetHooks(manifest, doc, sources);
  };
  for (const minor of [641, 648]) assert.doesNotThrow(() => both(at(minor), ...shippedUpTo(minor)), String(minor));
  // 0.300.0 reads nothing newer than 1.652.
  assert.throws(() => both(at(651), ...shippedUpTo(654)), /of 1\.652/u);
  assert.throws(() => both(at(654), ...shippedUpTo(661)), /of 1\.(654|655|656|657|658|659|660|661)/u);
  assert.equal(conditions.get("feebleminded").languages, "none");
  assert.equal(conditions.get("tongues").languages, "all");
  assert.deepEqual(conditions.get("cats_grace").fallsSafely, { upTo: 20, unless: ["incapacitated"] });
  assert.equal(conditions.get("sneezing_and_choking").suffocates, true);
  assert.deepEqual(conditions.get("alter_self_natural_weapons").weapon.names, ["unarmed"]);
  assert.equal(conditions.get("scintillating").whenSeen, true);
  assert.ok(parsedAsset.combat.senses.find((one) => one.id === "truesight").seesTrue);
  assert.deepEqual(spells.get("cloudkill").mechanics.save.against, { qualities: ["gas"] });
  const gasBreaths = [...creatures.values()].filter((one) =>
    (one.creature?.actions ?? []).some((action) => action.save?.against?.qualities?.includes("gas")),
  );
  assert.equal(gasBreaths.length, 20);
  assert.deepEqual(items.get("necklace-of-adaptation").item.worn.keepsOn, ["adapted_breathing"]);
  assert.deepEqual(items.get("holy-avenger-longsword").item.worn.keepsOn, ["holy_avenger_aura"]);
  assert.deepEqual(items.get("pearl-of-power").item.use.recovers, {
    group: "slots",
    upTo: { const: 3 },
    most: 3,
    count: 1,
  });
  const arrows = [...items.values()].filter((one) => /^arrow-of-[a-z]+-slaying$/u.test(one.id));
  assert.equal(arrows.length, 14);
  assert.ok(arrows.every((one) => one.item.tags.includes("arrow") && one.item.ammoRider.spentOnUse === true));
  assert.deepEqual(items.get("shield-of-missile-attraction").item.worn.drawsAim, {
    within: 10,
    blow: "ranged",
    weapon: true,
  });
  assert.deepEqual(
    items
      .get("cube-of-force")
      .item.moreUses.slice(0, 2)
      .map((one) => [one.use.charges, one.use.zone.sealsAir, one.use.zone.blocks]),
    [
      [1, true, undefined],
      [2, undefined, ["ranged"]],
    ],
  );
  assert.equal(items.get("broom-of-flying").item.use.calls.creature, "creatures/flying-broom");
  assert.deepEqual(creatures.get("flying-broom").creature.mountCarries, {
    weight: 200,
    slowedUpTo: 400,
    slowedSpeed: 30,
  });
  const cleric = parsedAsset.items.startingGear.find((one) => one.id === "cleric");
  assert.deepEqual(
    cleric.choices
      .flatMap((choice) => choice.options)
      .filter((one) => one.offeredWhen)
      .map((one) => [one.label, one.offeredWhen.derived]),
    [
      ["A warhammer (if proficient)", "prof_martial_weapons"],
      ["Chain mail (if proficient)", "prof_heavy_armor"],
    ],
  );
}
