// 0.302.0 (Capability API 1.662 to 1.674): Bull's Strength, Quivering Palm's days, Armor of Invulnerability,
// attunement by class and Use Magic Device, Teleport's table, the slippers, the level cap and creature saves.
{
  const catalog = (file) =>
    new Map(JSON.parse(shippedCatalogSources.get(`catalogs/${file}.json`)).entries.map((one) => [one.id, one]));
  const creatures = catalog("creatures");
  const items = catalog("magic_items");
  const spells = catalog("spells");
  const features = catalog("features");
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const both = (manifest, doc, sources) => {
    assertRulesetCombat(manifest, doc);
    assertRulesetSheetHooks(manifest, doc, sources);
  };
  assert.doesNotThrow(() => both(at(708), ...shippedUpTo(674)));
  assert.throws(() => both(at(673), ...shippedUpTo(674)), /of 1\.674/u);
  const conditions = new Map(parsedAsset.combat.conditions.map((one) => [one.condition, one]));
  assert.deepEqual(conditions.get("bulls_strength").derivedChanges, { carrying_capacity: { times: 2 } });
  assert.deepEqual(features.get("way-of-the-open-hand-quivering-palm").mechanics.applies[0], {
    condition: "quivering",
    duration: "until-dispelled",
    lastsDays: { field: "level_monk" },
  });
  assert.equal(items.get("armor-of-invulnerability").item.use.applies[0].whileItemWorn, true);
  // Attunement by a class, several classes or a spellcaster; a people or an alignment stays text.
  assert.deepEqual(items.get("holy-avenger-longsword").item.binds.needs, [
    { value: { field: "level_paladin" }, atLeast: 1 },
  ]);
  assert.deepEqual(items.get("staff-of-the-magi").item.binds.needs, [
    { value: { derived: "attunes_by_sor_wlk_wiz" }, atLeast: 1 },
  ]);
  assert.deepEqual(items.get("wand-of-fireballs").item.binds.needs, [
    { value: { derived: "max_spell_level" }, atLeast: 1 },
  ]);
  assert.equal([...items.values()].filter((one) => one.item?.binds?.needs).length, 30); // and the two talismans' alignments since 0.305.0, and the Dwarven Thrower's dwarf since 0.346.0
  assert.ok(parsedAsset.sheet.derived.every((one) => one.id.length <= 40));
  assert.deepEqual(parsedAsset.items.needsWaivedBy, { derived: "use_magic_device" });
  assert.deepEqual(
    parsedAsset.sheet.derived.slice(-70, -60).map((one) => one.id),
    [
      "attunes_by_brd_clr_drd",
      "attunes_by_brd_clr_drd_sor_wlk_wiz",
      "attunes_by_clr_drd_pal",
      "attunes_by_clr_drd_wlk",
      "attunes_by_drd_sor_wlk_wiz",
      "attunes_by_sor_wlk_wiz",
      "use_magic_device",
      "thieves_tools_proficient",
      "thieves_tools_proficiency",
      "thieves_tools_check",
    ],
    "new derived values go at the end",
  );
  // Teleport's table, on the spell, its scroll and the Helm of Teleportation.
  for (const port of [
    spells.get("teleport").mechanics.teleport,
    items.get("spell-scroll-teleport").item.use.teleport,
    items.get("helm-of-teleportation").item.use.teleport,
  ]) {
    assert.deepEqual(
      port.familiarity.map((row) => [row.id, row.mishap, row.similar ?? 0, row.off ?? 0]),
      [
        ["circle", 0, 0, 0],
        ["object", 0, 0, 0],
        ["very", 5, 8, 11],
        ["casual", 33, 10, 10],
        ["once", 43, 10, 20],
        ["described", 43, 10, 20],
        ["false", 50, 50, 0],
      ],
    );
    assert.deepEqual(port.mishap, { dice: "3d10", type: "force" });
  }
  // The slippers climb by a condition kept off Grease's slippery ground; the fight's climb is the typed one.
  assert.deepEqual(items.get("slippers-of-spider-climbing").item.worn, { keepsOn: ["slippers_climbing"] });
  assert.deepEqual(conditions.get("slippers_climbing"), {
    condition: "slippers_climbing",
    speeds: { climb: "walk" },
    climbNotOn: { slippery: true },
  });
  assert.deepEqual(spells.get("grease").mechanics.zone.terrain, { difficult: true, slippery: true });
  assert.deepEqual(parsedAsset.combat.economy.movementModes.climb, { field: "climb_speed" });
  assert.deepEqual(parsedAsset.sheet.totals, [
    {
      fields: [
        "level_barbarian",
        "level_bard",
        "level_cleric",
        "level_druid",
        "level_fighter",
        "level_monk",
        "level_paladin",
        "level_ranger",
        "level_rogue",
        "level_sorcerer",
        "level_warlock",
        "level_wizard",
        "level_other",
      ],
      max: 20,
      label: "Class levels",
    },
  ]);
  // Saves failed badly, and immunity for a day.
  const action = (creature, id) => creatures.get(creature).creature.actions.find((one) => one.id === id);
  assert.deepEqual(action("mummy", "dreadful_glare").save.failedBy, {
    atLeast: 5,
    applies: [
      // On the mummy's clock since 0.309.0.
      { condition: "frightened", duration: { rounds: 1, of: "source" } },
      { duration: { rounds: 1, of: "source" }, condition: "paralyzed" },
    ],
  });
  assert.deepEqual(action("sprite", "shortbow").save.failedBy.resultAtMost, 5);
  assert.deepEqual(
    action("homunculus", "bite").save.failedBy.applies.map((one) => one.condition),
    ["poisoned", "asleep"],
  );
  assert.deepEqual(action("drow", "hand_crossbow").save.failedBy.applies[1], {
    duration: "instant",
    condition: "asleep",
    endsWith: "poisoned",
  });
  assert.deepEqual(action("adult-red-dragon", "frightful_presence").oncePerTarget, {
    whenSaved: true,
    whenEnds: true,
    until: "long",
  });
  assert.deepEqual(action("mummy", "dreadful_glare").oncePerTarget, {
    whenSaved: true,
    until: "long",
    shared: "mummy_glare",
  });
  assert.deepEqual(action("mummy-lord", "dreadful_glare").oncePerTarget.shared, "mummy_lord_glare");
  assert.deepEqual(action("harpy", "luring_song").oncePerTarget, { whenSaved: true, until: "long" });
  assert.equal(
    [...creatures.values()].flatMap((one) => one.creature?.actions ?? []).filter((one) => one.oncePerTarget).length,
    32,
  );
}
