// 0.305.0 (Capability API 1.696): the androsphinx's Roar, the merrow's Harpoon, the ghost's Possession,
// domination, Telekinesis on what a creature holds, the talismans, who reads a scroll, the thrower's sneeze, and
// every fight check a creature gives.
{
  const creatures = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries.map((one) => [one.id, one]),
  );
  const items = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/magic_items.json")).entries.map((one) => [one.id, one]),
  );
  const spells = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries.map((one) => [one.id, one]),
  );
  const action = (creature, id) => creatures.get(creature).creature.actions.find((one) => one.id === id);
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  assert.doesNotThrow(() => assertRulesetSheetHooks(at(749), ...shippedUpTo(749)));
  assert.throws(
    () => assertRulesetSheetHooks(at(695), parsedAsset, shippedCatalogSources),
    /of 1\.(695|696|697|698|699|700|701|702) and must/u,
  );
  for (const minor of [676, 677, 678, 679, 680, 681, 682]) {
    let said = "";
    try {
      assertRulesetCombat(at(minor), parsedAsset);
      assertRulesetSheetHooks(at(minor), parsedAsset, shippedCatalogSources);
    } catch (error) {
      said = String(error.message);
    }
    const named = Number(/of 1\.(\d+) and must declare/u.exec(said)?.[1]);
    assert.ok(named > minor && named <= 695, `${minor}: ${said}`);
  }
  assert.deepEqual(action("androsphinx", "roar"), {
    id: "roar",
    name: "Roar",
    budget: "action",
    uses: { per: "day", count: 3 },
    byUse: ["roar_1", "roar_2", "roar_3"],
  });
  assert.deepEqual(action("androsphinx", "roar_3").damage, { dice: "8d10", type: "thunder" });
  assert.deepEqual(
    [action("merrow", "harpoon").contest, action("merrow", "harpoon").pull],
    [{ attacker: ["strength"], defender: ["strength"] }, 20],
  );
  const possession = action("ghost", "possession");
  assert.deepEqual(
    [possession.dismisses, possession.targetTypes, possession.applies],
    [
      { while: "possessed", possesses: true },
      { is: { types: ["humanoid"] } },
      [{ condition: "possessed", duration: "until-dispelled" }],
    ],
  );
  const conditions = new Map(parsedAsset.combat.conditions.map((one) => [one.condition, one]));
  assert.deepEqual(conditions.get("possessed"), {
    condition: "possessed",
    controls: true,
    endsWhenHolder: { downed: true },
    endable: { budget: "bonus" },
  });
  assert.equal(conditions.get("dominated").controls, true);
  assert.ok(conditions.get("protected_from_evil_good").conditionImmunitiesFrom[0].conditions.includes("possessed"));
  assert.deepEqual(spells.get("telekinesis").mechanics.contest.takesMode, { label: "Object", restLabel: "Creature" });
  assert.deepEqual(items.get("talisman-of-pure-good").item.binds.needs, [
    { value: { derived: "alignment_good_evil" }, atLeast: 1 },
  ]);
  assert.deepEqual(items.get("talisman-of-ultimate-evil").item.binds.needs, [
    { value: { derived: "alignment_good_evil" }, atMost: -1 },
  ]);
  const words = parsedAsset.sheet.derived.find((one) => one.id === "alignment_good_evil");
  assert.deepEqual([words.op, words.from, words.table], ["wordsTable", { field: "alignment" }, { good: 1, evil: -1 }]);
  const missile = items.get("spell-scroll-magic-missile").item;
  assert.deepEqual(
    [missile.userNeeds.map((one) => one.value.field), missile.userNeedsAny],
    [["level_sorcerer", "level_wizard"], true],
  );
  assert.equal(items.get("spell-scroll-hunters-mark").item.userNeedsAny, undefined);
  const dust = items.get("dust-of-sneezing-and-choking").item.use;
  assert.deepEqual(
    [dust.appliesSelfSaves, dust.appliesSelf.map((one) => one.condition)],
    [true, ["sneezing_and_choking"]],
  );
  // Every creature without a sheet gives every check.
  const checkIds = parsedAsset.combat.checks.map((one) => one.id).filter((one) => one !== "spellcasting");
  for (const [id, entry] of creatures)
    if (!entry.creature.sheet)
      assert.deepEqual(
        checkIds.filter((one) => entry.creature.checks?.[one] === undefined),
        [],
        id,
      );
  assert.deepEqual(
    [creatures.get("merrow").creature.checks.strength, creatures.get("merrow").creature.checks.thieves_tools],
    [4, 0],
  );
}
console.log(
  "ruleset 0.305.0 Roar, Harpoon, Possession, domination, Telekinesis, talismans, scrolls, dust and creature checks regression checks passed",
);

// 0.306.0 (Capability API 1.696, no new keys): Echolocation and a creature's spellcasting ability check.
{
  const creatures = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries.map((one) => [one.id, one.creature]),
  );
  const conditions = new Map(parsedAsset.combat.conditions.map((one) => [one.condition, one]));
  // "The bat can't use its blindsight while deafened": the blindsight is a condition held off while deafened.
  for (const range of [60, 120]) {
    assert.deepEqual(conditions.get(`echolocation_${range}`), {
      condition: `echolocation_${range}`,
      senses: { blindsight: range },
      heldOffWhile: { conditions: ["deafened"] },
    });
    assert.ok(parsedAsset.sheet.live.conditions.some((one) => one.id === `echolocation_${range}`));
  }
  const echo = [...creatures]
    .filter(([, one]) => one.keepsOn?.some((id) => id.startsWith("echolocation_")))
    .map(([id, one]) => [id, one.keepsOn.find((each) => each.startsWith("echolocation_")), one.senses?.blindsight]);
  assert.deepEqual(echo.sort(), [
    ["bat", "echolocation_60", undefined],
    ["darkmantle", "echolocation_60", undefined],
    ["giant-bat", "echolocation_60", undefined],
    ["killer-whale", "echolocation_120", undefined],
    ["swarm-of-bats", "echolocation_60", undefined],
  ]);
  // "The pit fiend's spellcasting ability is Charisma": its Spellcasting ability check is Charisma's +7.
  assert.equal(creatures.get("pit-fiend").checks.spellcasting, 7);
  assert.equal(creatures.get("goblin").checks.spellcasting, undefined);
  // And the oni in its humanoid form (0.400.0).
  assert.equal(
    [...creatures.values()].filter((one) => !one.sheet && one.checks?.spellcasting !== undefined).length,
    23,
  );
}
console.log("ruleset 0.306.0 Echolocation and creature spellcasting checks regression checks passed");

