{
  const read = (file) =>
    new Map(JSON.parse(shippedCatalogSources.get(`catalogs/${file}.json`)).entries.map((one) => [one.id, one]));
  const items = read("magic_items");
  const creatures = read("creatures");
  const equipment = read("equipment");
  const spells = read("spells");
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  for (const id of [
    "assassins-blood",
    "crawler-mucus",
    "midnight-tears",
    "oil-of-taggit",
    "pale-tincture",
    "torpor",
    "truth-serum",
  ]) {
    const use = equipment.get(id).item.use;
    assert.deepEqual([use.kind, use.range, use.targets, use.consumes], ["debuff", 5, "any", true], id);
  }
  assert.deepEqual(equipment.get("torpor").item.use.applies[0].duration, { rounds: 600, times: "4d6" });
  assert.deepEqual(equipment.get("pale-tincture").item.use.applies[0].saveEnds, {
    save: "con_save",
    at: "days",
    days: 1,
    successes: 7,
    harmsOnFail: { dice: "1d6", type: "poison" },
  });
  assert.deepEqual(equipment.get("midnight-tears").item.use.applies, [
    { condition: "midnight_tears", duration: "until-dispelled", lastsDays: "midnight" },
  ]);
  assert.equal(equipment.get("midnight-tears").item.use.save, undefined);
  const conditions = new Map(parsedAsset.combat.conditions.map((one) => [one.condition, one]));
  assert.deepEqual(conditions.get("midnight_tears").onEnd, {
    harm: { dice: "9d6", type: "poison", save: { save: "con_save", difficulty: 17, onSuccess: "half" } },
    when: ["expired"],
  });
  assert.equal(conditions.get("pale_tincture").keepsDamage, true);
  const dust = creatures.get("mummy-lord").creature.actions.find((one) => one.id === "blinding_dust");
  assert.deepEqual(
    [dust.area, dust.targetCount, dust.range],
    [{ shape: "burst", size: 5, around: true }, 2, undefined],
  );
  assert.ok(parsedAsset.gmReference.includes("False Appearance") && parsedAsset.gmReference.length <= 16000);
  const ward = spells.get("forbiddance").mechanics;
  assert.deepEqual(
    [ward.area, ward.zone, ward.targetTypes, ward.beforeFight],
    [
      { shape: "box", size: 200 },
      { rounds: 1000, triggers: ["enter", "turn-start"], atCast: false, outlasts: true, forbids: { teleport: "into" } },
      { is: { types: ["celestial", "elemental", "fey", "fiend", "undead"] } },
      true,
    ],
  );
  assert.deepEqual(items.get("contingency-statuette-downed").item.stores, {
    catalogs: ["spells"],
    levels: 5,
    count: 1,
    castsOn: { on: "down" },
  });
  assert.deepEqual(items.get("contingency-statuette-harmed").item.stores.castsOn, { on: "harmed" });
  assert.deepEqual(items.get("gloves-of-swimming-and-climbing").item.worn.modifiers, [
    { to: "checks", skills: ["athletics"], flat: 5, for: ["climb", "swim"] },
  ]);
  // The new keys are checked: a day save's count, a harm's save, a purpose, a statuette's moment.
  const broken = (file, change, pattern) => {
    const sources = new Map(shippedCatalogSources);
    const parsed = JSON.parse(sources.get(`catalogs/${file}.json`));
    change(new Map(parsed.entries.map((one) => [one.id, one])));
    sources.set(`catalogs/${file}.json`, JSON.stringify(parsed));
    // A worn modifier's purposes are an item's, checked with the items.
    assert.throws(() => {
      assertRulesetSheetHooks(shippedManifest, parsedAsset, sources);
      assertRulesetItems(shippedManifest, parsedAsset, sources);
    }, pattern);
  };
  broken(
    "equipment",
    (all) => (all.get("pale-tincture").item.use.applies[0].saveEnds.successes = 11),
    /saveEnds successes is a whole number from 2 to 10/u,
  );
  broken(
    "magic_items",
    (all) => (all.get("gloves-of-swimming-and-climbing").item.worn.modifiers[0].to = "saves"),
    /for is 1 to 8 distinct purposes/u,
  );
  broken(
    "magic_items",
    (all) => (all.get("contingency-statuette-downed").item.stores.castsOn = { on: "hit" }),
    /castsOn\?: \{ on: "harmed" \| "down"/u,
  );
  const doc = structuredClone(parsedAsset);
  doc.combat.conditions.find((one) => one.condition === "midnight_tears").onEnd.harm.save.onSuccess = "negates";
  assert.throws(() => assertRulesetCombat(at(752), doc), /harms as it ends/u);
}
console.log(
  "ruleset 0.365.0 the poisons, Blinding Dust, the rules reference, Forbiddance, Contingency and the gloves regression checks passed",
);

// 0.366.0 to 0.367.0 (Capability API 1.753 to 1.755): Magic Jar, Forbiddance's choices, Magic Circle's ward and the
// vampire's forms.
{
  const read = (file) =>
    new Map(JSON.parse(shippedCatalogSources.get(`catalogs/${file}.json`)).entries.map((one) => [one.id, one]));
  const spells = read("spells");
  const creatures = read("creatures");
  const conditions = new Map(parsedAsset.combat.conditions.map((one) => [one.condition, one]));
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  assert.deepEqual(spells.get("magic-jar").mechanics.applies, [
    { condition: "magic_jar_soul", duration: "until-dispelled" },
  ]);
  assert.deepEqual(conditions.get("magic_jar_soul").actions, ["spells/magic-jar-possess", "spells/magic-jar-return"]);
  assert.deepEqual(conditions.get("magic_jarred"), {
    condition: "magic_jarred",
    controls: true,
    holderDies: { save: "cha_save", difficulty: { derived: "spell_save_dc" } },
    endable: { budget: "action" },
  });
  const possess = spells.get("magic-jar-possess").mechanics;
  assert.deepEqual(possess.targetTypes.is.outsideZoneOf, [
    "magic-circle",
    "magic-circle-celestial",
    "magic-circle-elemental",
    "magic-circle-fey",
    "magic-circle-fiend",
    "magic-circle-undead",
  ]);
  assert.deepEqual(possess.targetTypes.is.except, { holding: ["protected_from_evil_good"] });
  assert.deepEqual(
    [possess.unlessImposing, spells.get("magic-jar-return").mechanics.unlessImposing],
    [["magic_jarred"], ["magic_jarred"]],
  );
  const forbiddance = spells.get("forbiddance").mechanics;
  assert.deepEqual(
    [forbiddance.kindChoice, forbiddance.damageTypeChoice, forbiddance.zone.forbids],
    ["many", ["radiant", "necrotic"], { teleport: "into" }],
  );
  const vampire = creatures.get("vampire").creature;
  assert.equal(vampire.actions.length, 15);
  assert.deepEqual(vampire.hangsOn, {
    uses: 1,
    label: "Misty Escape",
    becomes: { action: "shapechange_mist", form: "creatures/vampire-mist-form" },
  });
  assert.deepEqual(
    creatures.get("vampire-mist-form").creature.actions.map((one) => one.id),
    ["shapechange_bat", "shapechange_mist"],
  );
  assert.equal(creatures.get("vampire-bat-form").creature.size, "tiny");
  // The new keys are checked and gated.
  const broken = (file, change, pattern) => {
    const sources = new Map(shippedCatalogSources);
    const parsed = JSON.parse(sources.get(`catalogs/${file}.json`));
    change(new Map(parsed.entries.map((one) => [one.id, one])));
    sources.set(`catalogs/${file}.json`, JSON.stringify(parsed));
    assert.throws(() => assertRulesetSheetHooks(at(755), parsedAsset, sources), pattern);
  };
  broken(
    "spells",
    (all) => (all.get("forbiddance").mechanics.damageTypeChoice = ["radiant"]),
    /damageTypeChoice is 2 to 8 declared damage types/u,
  );
  broken("spells", (all) => delete all.get("forbiddance").mechanics.zone, /kindChoice "many" goes with a zone/u);
  broken(
    "spells",
    (all) => (all.get("magic-jar-possess").mechanics.targetTypes.is.outsideZoneOf = []),
    /outsideZoneOf is 1 to 8 entry ids or names/u,
  );
  broken(
    "spells",
    (all) => (all.get("magic-jar-possess").mechanics.targetTypes.is.except.holding = ["unknown_condition"]),
    /except is \{ types\?, tags\?, upToSize\?, atLeastSize\?, holding\? \}/u,
  );
  assert.throws(() => assertRulesetSheetHooks(at(754), parsedAsset, shippedCatalogSources), /of 1\.755 and must/u);
  assert.throws(
    () => assertRulesetSheetHooks(at(753), parsedAsset, shippedCatalogSources),
    /entry "tarrasque" carrying 13 actions, more than twelve, of 1\.754 and must/u,
  );
  assert.ok(assertRulesetCreatures(at(754), parsedAsset, shippedCatalogSources) > 300);
}
