// 0.368.0 and 0.369.0 (Capability API 1.756 to 1.760): Wish's menu and its stress, Wish's immunity to one spell,
// X-ray Vision's limits by material, Creation's object and Goodberry's day.
{
  const read = (file) =>
    new Map(JSON.parse(shippedCatalogSources.get(`catalogs/${file}.json`)).entries.map((one) => [one.id, one]));
  const spells = read("spells");
  const items = read("magic_items");
  const conditions = new Map(parsedAsset.combat.conditions.map((one) => [one.condition, one]));
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const wishes = [...spells.keys()].filter((id) => id.startsWith("wish-"));
  assert.equal(wishes.length, 15);
  assert.deepEqual(
    conditions.get("wish_lost").forbids.entries,
    ["wish", ...wishes].map((id) => `spells/${id}`),
  );
  const heal = spells.get("wish-heal").mechanics;
  assert.deepEqual([heal.kind, heal.healsAll, heal.targetCount, heal.unseals], ["heal", true, 20, true]);
  assert.deepEqual(
    heal.appliesSelf.map((one) => one.condition),
    ["wish_stressed", "wish_weakened", "wish_lost"],
  );
  assert.deepEqual(conditions.get("wish_weakened").abilities, { str: { atMost: 3 } });
  assert.deepEqual(spells.get("wish-resistance-fire").mechanics.applies, [
    { condition: "resist_fire", duration: "until-dispelled" },
  ]);
  const ward = spells.get("wish-immunity").mechanics;
  assert.deepEqual(
    [ward.wardPick, ward.targetCount, ward.applies],
    [true, 10, [{ condition: "wished_ward", duration: { rounds: 4800 } }]],
  );
  assert.ok(!parsedAsset.gmReference.includes("immune to a single spell"));
  assert.deepEqual(parsedAsset.rests.find((one) => one.id === "long").clear.conditions, [
    "tranquility",
    "wish_stressed",
    "strength_drained",
  ]);
  assert.deepEqual(spells.get("wall-of-stone").mechanics.zone.material, { of: "stone", inches: 6 });
  const creation = spells.get("creation").mechanics;
  assert.deepEqual(
    [creation.area, creation.makesItems.item, creation.makesItems.lasts.map((one) => one.minutes)],
    [undefined, "magic_items/created-object", [1440, 720, 60, 10, 1]],
  );
  assert.deepEqual(items.get("spell-scroll-creation").item.use.makesItems, creation.makesItems);
  assert.deepEqual(spells.get("goodberry").mechanics.makesItems.lasts, [{ minutes: 1440 }]);
  assert.ok(items.get("created-object").item);
  // The new keys are checked.
  const broken = (file, change, pattern) => {
    const sources = new Map(shippedCatalogSources);
    const parsed = JSON.parse(sources.get(`catalogs/${file}.json`));
    change(new Map(parsed.entries.map((one) => [one.id, one])));
    sources.set(`catalogs/${file}.json`, JSON.stringify(parsed));
    assert.throws(() => assertRulesetSheetHooks(shippedManifest, parsedAsset, sources), pattern);
  };
  broken(
    "spells",
    (all) => (all.get("wish-immunity").mechanics.wardPick = "yes"),
    /wardPick is true, on mechanics that put something on/u,
  );
  broken(
    "spells",
    (all) => delete all.get("wish-immunity").mechanics.applies,
    /wardPick is true, on mechanics that put something on/u,
  );
  broken(
    "spells",
    (all) => (all.get("creation").mechanics.makesItems.lasts = [{ minutes: 1 }, { minutes: 2 }]),
    /makesItems is \{ item: "<catalog>\/<entry>", count 1 to 100, lasts\?/u,
  );
  broken(
    "spells",
    (all) => (all.get("creation").mechanics.makesItems.lasts = [{ label: "A", minutes: 0 }]),
    /lasts\?: 1 to 8/u,
  );
  broken(
    "magic_items",
    (all) => (all.get("spell-scroll-goodberry").item.use.makesItems.lasts = []),
    /lasts\?: \[\{ label\?, minutes \}\]/u,
  );
  broken(
    "spells",
    (all) => (all.get("wall-of-stone").mechanics.zone.material = { of: "Stone", inches: 6 }),
    /zone material is \{ of, inches \}, on a wall blocking sight/u,
  );
  broken(
    "spells",
    (all) => (all.get("wall-of-stone").mechanics.zone.blocks = ["move"]),
    /zone material is \{ of, inches \}, on a wall blocking sight/u,
  );
  const sensing = (through) => {
    const doc = structuredClone(parsedAsset);
    doc.combat.senses.find((one) => one.id === "xray").throughWalls = through;
    return doc;
  };
  assert.throws(
    () => assertRulesetSheetHooks(shippedManifest, sensing({ stone: 0 }), shippedCatalogSources),
    /throughWalls is true or \{ material: inches \}/u,
  );
  assert.throws(
    () => assertRulesetSheetHooks(shippedManifest, sensing({}), shippedCatalogSources),
    /throughWalls is true or \{ material: inches \}/u,
  );
  assert.doesNotThrow(() => assertRulesetSheetHooks(shippedManifest, parsedAsset, shippedCatalogSources));
  assert.throws(
    () => assertRulesetSheetHooks(at(759), parsedAsset, shippedCatalogSources),
    /made items that vanish, of 1\.760 and must/u,
  );
  assert.throws(() => assertRulesetSheetHooks(at(758), parsedAsset, shippedCatalogSources), /of 1\.759 and must/u);
  assert.throws(
    () => assertRulesetSheetHooks(at(757), parsedAsset, shippedCatalogSources),
    /a ward against one spell or effect picked as it is cast, of 1\.758 and must/u,
  );
}
