// 0.370.0 (Capability API 1.761): how much thought each creature puts into a fight.
{
  const creatures = new Map(
    JSON.parse(srdCatalogSources.get("catalogs/creatures.json")).entries.map((one) => [one.id, one.creature]),
  );
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  assert.deepEqual(parsedAsset.combat.minds, {
    ability: "int",
    tiers: [
      { atLeast: 0, mind: "mindless" },
      { atLeast: 3, mind: "cunning" },
      { atLeast: 8, mind: "tactical" },
      { atLeast: 15, mind: "genius" },
    ],
  });
  assert.deepEqual(
    parsedAsset.combat.creatureTypes.types.filter((one) => one.mind).map((one) => [one.id, one.mind]),
    [
      ["beast", "instinct"],
      ["construct", "mindless"],
      ["ooze", "mindless"],
      ["object", "mindless"],
    ],
  );
  assert.deepEqual(
    [...creatures]
      .filter(([, one]) => one.mind && one.mind !== "instinct" && one.mind !== "cunning")
      .map(([id, one]) => [id, one.mind]),
    [
      ["minotaur-skeleton", "mindless"],
      ["ogre-zombie", "mindless"],
      ["skeleton", "mindless"],
      ["warhorse-skeleton", "mindless"],
      ["zombie", "mindless"],
    ],
  );
  const minded = (change) => {
    const doc = structuredClone(parsedAsset);
    change(doc);
    return doc;
  };
  assert.throws(
    () =>
      assertRulesetSheetHooks(
        shippedManifest,
        minded((doc) => (doc.combat.minds.tiers[1].atLeast = 0)),
        shippedCatalogSources,
      ),
    /combat\.minds is \{ ability, tiers: 1 to 5/u,
  );
  assert.throws(
    () =>
      assertRulesetSheetHooks(
        shippedManifest,
        minded((doc) => (doc.combat.minds.tiers[0].mind = "clever")),
        shippedCatalogSources,
      ),
    /combat\.minds is \{ ability, tiers/u,
  );
  assert.throws(
    () =>
      assertRulesetSheetHooks(
        shippedManifest,
        minded((doc) => (doc.combat.creatureTypes.types[1].mind = "feral")),
        shippedCatalogSources,
      ),
    /creature type "beast" mind is one of/u,
  );
  const sources = new Map(shippedCatalogSources);
  const parsed = JSON.parse(sources.get("catalogs/creatures.json"));
  parsed.entries.find((one) => one.id === "zombie").creature.mind = "dull";
  sources.set("catalogs/creatures.json", JSON.stringify(parsed));
  assert.throws(() => assertRulesetSheetHooks(shippedManifest, parsedAsset, sources), /entry "zombie" mind is one of/u);
  assert.throws(
    () => assertRulesetSheetHooks(at(760), parsedAsset, shippedCatalogSources),
    /has combat\.minds, of 1\.761 and must/u,
  );
}
