// 0.371.0 (Capability API 1.762): morale, the Dungeon Master's optional variant.
{
  const creatures = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries.map((one) => [one.id, one.creature]),
  );
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  assert.deepEqual(parsedAsset.combat.morale, {
    check: { save: "wis_save", difficulty: 10 },
    on: ["surprised", "hurt", "helpless", "leader-down", "half-down"],
    halfDownUnanswered: true,
    hurtBelow: 0.5,
    surrenders: ["cunning", "tactical", "genius"],
    neverSurrender: ["undead", "fiend"],
    unlessImmune: "frightened",
  });
  assert.deepEqual(
    [...creatures].filter(([, one]) => one.leader).map(([id]) => id),
    ["archmage", "bandit-captain", "cult-fanatic", "knight", "noble", "priest", "veteran"],
  );
  const moraled = (change) => {
    const doc = structuredClone(parsedAsset);
    change(doc.combat.morale);
    return doc;
  };
  for (const change of [
    (morale) => (morale.on = ["dawn"]),
    (morale) => (morale.check = { save: "luck_save", difficulty: 10 }),
    (morale) => (morale.hurtBelow = 1),
    (morale) => (morale.surrenders = ["clever"]),
    (morale) => (morale.unlessImmune = "unafraid"),
  ])
    assert.throws(
      () => assertRulesetSheetHooks(shippedManifest, moraled(change), shippedCatalogSources),
      /combat\.morale is \{ check/u,
    );
  const sources = new Map(shippedCatalogSources);
  const parsed = JSON.parse(sources.get("catalogs/creatures.json"));
  parsed.entries.find((one) => one.id === "knight").creature.leader = "yes";
  sources.set("catalogs/creatures.json", JSON.stringify(parsed));
  assert.throws(() => assertRulesetSheetHooks(shippedManifest, parsedAsset, sources), /entry "knight" leader is true/u);
  assert.doesNotThrow(() => assertRulesetSheetHooks(shippedManifest, parsedAsset, shippedCatalogSources));
  assert.throws(
    () => assertRulesetSheetHooks(at(761), parsedAsset, shippedCatalogSources),
    /has combat\.morale, of 1\.762 and must/u,
  );
}
console.log("ruleset 0.371.0 morale regression checks passed");

// 0.372.0 (Capability API 1.763): how a creature goes about a fight.
{
  const creatures = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/creatures.json")).entries.map((one) => [one.id, one.creature]),
  );
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  assert.deepEqual(creatures.get("wolf").behavior, { targets: ["wounded"], pack: true });
  assert.deepEqual(creatures.get("goblin").behavior, { temperament: "cowardly", targets: ["weakest"] });
  assert.deepEqual(creatures.get("hobgoblin").behavior, { temperament: "disciplined", pack: true });
  assert.deepEqual(creatures.get("kobold").behavior, { pack: true });
  assert.deepEqual(creatures.get("adult-red-dragon").behavior, {
    temperament: "arrogant",
    shifts: [
      { on: "bloodied", to: "methodical" },
      { on: "ally-down", to: "methodical" },
      { on: "cornered", to: "reckless" },
    ],
    targets: ["casters"],
    opens: ["fire_breath"],
  });
  assert.deepEqual(creatures.get("adult-brass-dragon").behavior, {
    temperament: "honourable",
    targets: ["casters"],
    opens: ["breath_weapons"],
  });
  assert.deepEqual(creatures.get("hell-hound").behavior, { opens: ["fire_breath"], pack: true });
  for (const id of ["ghoul", "grick", "darkmantle", "mimic", "gargoyle", "doppelganger", "bugbear"])
    assert.equal(creatures.get(id).behavior?.ambush, true, id);
  assert.deepEqual(creatures.get("mage").behavior, { role: "controller", targets: ["casters"] });
  assert.deepEqual(creatures.get("priest").behavior, { role: "supporter" });
  assert.equal(creatures.get("bandit").behavior, undefined);
  const behaved = (id, behavior) => {
    const sources = new Map(shippedCatalogSources);
    const parsed = JSON.parse(sources.get("catalogs/creatures.json"));
    parsed.entries.find((one) => one.id === id).creature.behavior = behavior;
    sources.set("catalogs/creatures.json", JSON.stringify(parsed));
    return sources;
  };
  for (const behavior of [
    {},
    { temperament: "grumpy" },
    { role: "tank" },
    { targets: ["nearest", "nearest"] },
    { targets: ["nearest", "weakest", "wounded", "strongest", "casters"] },
    { opens: ["sneeze"] },
    { pack: false },
    { hunts: true },
  ])
    assert.throws(
      () => assertRulesetSheetHooks(shippedManifest, parsedAsset, behaved("wolf", behavior)),
      /entry "wolf" behavior is \{ temperament/u,
      JSON.stringify(behavior),
    );
  assert.doesNotThrow(() =>
    assertRulesetSheetHooks(shippedManifest, parsedAsset, behaved("wolf", { opens: ["spells/fireball"] })),
  );
  const typed = structuredClone(parsedAsset);
  typed.combat.creatureTypes.types[0].behavior = { role: "brawler" };
  assert.throws(
    () => assertRulesetSheetHooks(shippedManifest, typed, shippedCatalogSources),
    /creature type "aberration" behavior is/u,
  );
  const fought = structuredClone(parsedAsset);
  fought.combat.behavior = { targets: ["anyone"] };
  assert.throws(() => assertRulesetSheetHooks(shippedManifest, fought, shippedCatalogSources), /combat\.behavior is/u);
  assert.doesNotThrow(() => assertRulesetSheetHooks(shippedManifest, parsedAsset, shippedCatalogSources));
  assert.throws(
    () => assertRulesetSheetHooks(at(762), parsedAsset, shippedCatalogSources),
    /a behavior, of 1\.763 and must|combat\.behavior, of 1\.763 and must/u,
  );
}
