// 0.376.0 (Capability API 1.767): a wizard prepares from the spellbook.
{
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  const steps = parsedAsset.sheet.builder.steps;
  const ids = steps.map((one) => one.id);
  assert.deepEqual(ids.slice(ids.indexOf("spells"), ids.indexOf("spells") + 3), ["spells", "spellbook", "prepared"]);
  const byId = new Map(steps.map((one) => [one.id, one]));
  assert.deepEqual(byId.get("spells").within, { step: "class", filter: "known_ids" });
  assert.deepEqual(
    byId.get("spellbook").within,
    { step: "class", filter: "granted_ids" },
    "spellbook_ids until 0.378.0",
  );
  assert.deepEqual(byId.get("spellbook").stamp, { class: { fromWithin: "spell_class" }, prepared: false });
  assert.deepEqual(byId.get("spellbook").countFrom, { derived: "wizard_spellbook" });
  const mark = byId.get("prepared");
  assert.deepEqual(
    { kind: mark.kind, list: mark.list, column: mark.column, where: mark.where, countFrom: mark.countFrom },
    {
      kind: "mark",
      list: "spells",
      column: "prepared",
      where: { level: { atLeast: 1 }, class: "wizard" },
      countFrom: { derived: "spells_prepared_wizard" },
    },
  );
  const spells = new Map(
    JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries.map((one) => [one.id, one.filters]),
  );
  assert.deepEqual(spells.get("magic-missile").known_ids, ["sorcerer", "sorcerer-multiclass", "sorcerer-third-class"]);
  assert.deepEqual(spells.get("magic-missile").granted_ids, ["wizard", "wizard-multiclass", "wizard-third-class"]);
  assert.deepEqual(spells.get("fire-bolt").granted_ids, [], "a cantrip is never in the spellbook step");
  assert.equal([...spells.values()].filter((one) => one.known_ids.some((id) => id.startsWith("wizard"))).length, 0);
  const marked = (change) => {
    const doc = structuredClone(parsedAsset);
    change(doc.sheet.builder.steps.find((one) => one.id === "prepared"));
    return doc;
  };
  for (const change of [
    (one) => (one.column = "level"),
    (one) => (one.list = "nowhere"),
    (one) => (one.where = {}),
    (one) => (one.where = { colour: "red" }),
    (one) => (one.where = { class: { atLeast: 1 } }),
    (one) => (one.max = 3),
    (one) => delete one.countFrom,
  ])
    assert.throws(
      () => assertRulesetSheetHooks(shippedManifest, marked(change), shippedCatalogSources),
      /marks a boolean column of a list/u,
      String(change),
    );
  assert.doesNotThrow(() => assertRulesetSheetHooks(shippedManifest, parsedAsset, shippedCatalogSources));
  assert.equal(
    steps.length,
    29,
    "the Domain, oath and circle spells step since 0.378.0, Subclass since 0.382.0, Class choices since 0.404.0, Hit point rolls since 0.407.0",
  );
  const spellbook = (max) => {
    const doc = structuredClone(parsedAsset);
    doc.sheet.builder.steps.find((one) => one.id === "spellbook").max = max;
    return doc;
  };
  assert.throws(
    () => assertRulesetSheetHooks(shippedManifest, spellbook(61), shippedCatalogSources),
    /asks for at most 60/u,
  );
  const crowded = structuredClone(parsedAsset);
  for (let i = 0; i < 8; i += 1)
    crowded.sheet.builder.steps.push({
      ...structuredClone(crowded.sheet.builder.steps.find((one) => one.id === "cantrips")),
      id: `more_${i}`,
    });
  assert.throws(() => assertRulesetSheetHooks(shippedManifest, crowded, shippedCatalogSources), /at most 32 steps/u);
  assert.throws(() => assertRulesetSheetHooks(at(766), parsedAsset, shippedCatalogSources), /of 1\.767 and must/u);
  assert.throws(() => assertRulesetSheetHooks(at(767), parsedAsset, shippedCatalogSources), /of 1\.768 and must/u);
  assert.throws(
    () => assertRulesetSheetHooks(at(767), spellbook(40), shippedCatalogSources),
    /more than 24 steps, of 1\.768/u,
  );
}
