// 0.377.0: starting weapons arrive in hand; the summary shows the hit point maximum.
{
  const gear = new Map(parsedAsset.items.startingGear.map((one) => [one.id, one]));
  const equipped = (id) => [
    ...gear
      .get(id)
      .lines.filter((line) => line.equip)
      .map((line) => line.item ?? "oneOf"),
    ...(gear.get(id).choices ?? []).flatMap((choice) =>
      choice.options.flatMap((option) => option.lines.filter((line) => line.equip).map((line) => line.item ?? "oneOf")),
    ),
  ];
  assert.deepEqual(
    equipped("barbarian"),
    ["equipment/greataxe", "oneOf", "equipment/handaxe", "oneOf"],
    "the chosen weapons, not the four javelins",
  );
  assert.deepEqual(equipped("wizard"), ["equipment/quarterstaff", "equipment/dagger"]);
  assert.ok(equipped("fighter").includes("equipment/chain-mail") && equipped("fighter").includes("equipment/longbow"));
  assert.deepEqual(equipped("acolyte"), []);
  for (const one of parsedAsset.items.startingGear)
    for (const line of [
      ...one.lines,
      ...(one.choices ?? []).flatMap((choice) => choice.options.flatMap((option) => option.lines)),
    ])
      if (line.equip) assert.ok((line.count ?? 1) <= 2, `${one.id} equips no stack over two`);
  assert.deepEqual(parsedAsset.gm.sheetSummary.derived.slice(0, 2), ["level", "hp_max_total"]);
  assert.doesNotThrow(() => assertRulesetSheetHooks(shippedManifest, parsedAsset, shippedCatalogSources));
}
