// 0.437.0 (Capability API 1.806): translations ship as locales/<language>.json beside the catalogs.
{
  // The package without the translations it ships (0.439.0), for adding one at a time.
  const bareManifest = {
    ...shippedManifest,
    contributions: {
      assets: { paths: shippedManifest.contributions.assets.paths.filter((path) => !path.startsWith("locales/")) },
    },
    files: shippedManifest.files.filter((file) => !file.path.startsWith("locales/")),
  };
  const { assertRulesetLocales, rulesetLocaleOfAssetPath } = await import("../ruleset-package-checks.mjs");
  assert.equal(shippedManifest.capabilityApi.minor >= 806, true);
  assert.deepEqual(
    [
      "locales/ru.json",
      "locales/pt-BR.json",
      "locales/zh-Hans.json",
      "locales/en.json",
      "catalogs/spells.json",
      "locales/RU.json",
    ].map(rulesetLocaleOfAssetPath),
    ["ru", "pt-BR", "zh-Hans", "en", null, null],
  );
  const ru = JSON.stringify({
    _meta: { locale: "ru", direction: "ltr" },
    ruleset: { Prone: "Лежащий", "Fire Bolt": "" },
  });
  const withLocale = (minor, path = "locales/ru.json", files = true) => ({
    ...bareManifest,
    capabilityApi: { major: 1, minor },
    contributions: { assets: { paths: [...bareManifest.contributions.assets.paths, path] } },
    files: [...bareManifest.files, ...(files ? [{ path, sha256: "0".repeat(64), bytes: 1 }] : [])],
  });
  assert.equal(assertRulesetLocales(bareManifest, new Map()), 0);
  assert.equal(assertRulesetLocales(withLocale(806), new Map([["locales/ru.json", ru]])), 1);
  assert.throws(
    () => assertRulesetLocales(withLocale(805), new Map([["locales/ru.json", ru]])),
    /capability API 1\.806/u,
  );
  assert.throws(
    () => assertRulesetLocales(withLocale(806, "locales/ru.json", false), new Map([["locales/ru.json", ru]])),
    /manifest\.files/u,
  );
  assert.throws(
    () => assertRulesetLocales(withLocale(806, "locales/en.json"), new Map([["locales/en.json", ru]])),
    /English/u,
  );
  assert.throws(
    () => assertRulesetLocales(withLocale(806, "locales/de.json"), new Map([["locales/de.json", ru]])),
    /_meta\.locale is not "de"/u,
  );
  assert.throws(
    () => assertRulesetLocales(withLocale(806, "locales/Russian.json"), new Map()),
    /not a "locales\/<language>\.json"/u,
  );
  const extra = JSON.stringify({ _meta: { locale: "ru" }, ruleset: {}, agents: {} });
  assert.throws(() => assertRulesetLocales(withLocale(806), new Map([["locales/ru.json", extra]])), /holds "agents"/u);
  const notText = JSON.stringify({ _meta: { locale: "ru" }, ruleset: { Prone: 3 } });
  assert.throws(() => assertRulesetLocales(withLocale(806), new Map([["locales/ru.json", notText]])), /is not text/u);
}
console.log("ruleset 0.437.0 translations regression checks passed");

// 0.438.0 (Capability API 1.807): ritual spells and cantrips that come prepared.
{
  assert.equal(shippedManifest.capabilityApi.minor >= 807, true);
  assert.equal(parsedAsset.sheet.lists.find((one) => one.id === "spells").ritual, "ritual");
  const spells = JSON.parse(shippedCatalogSources.get("catalogs/spells.json")).entries;
  const cantrips = spells.filter((entry) => entry.rows[0].values.level === 0);
  assert.ok(cantrips.length > 20);
  assert.ok(cantrips.every((entry) => entry.rows[0].values.prepared === true));
  assert.ok(
    spells.filter((entry) => entry.rows[0].values.level > 0).every((entry) => entry.rows[0].values.prepared === false),
  );
  assert.equal(spells.find((entry) => entry.id === "detect-magic").rows[0].values.ritual, true);
}
console.log("ruleset 0.438.0 rituals regression checks passed");

// 0.439.0: eleven translations ship; from 0.441.0 (Capability API 1.811) as language packs beside the ruleset file.
{
  const { assertRulesetLanguagePacks, rulesetLanguagePackName } = await import("../ruleset-package-checks.mjs");
  const LOCALES = ["ar", "de", "es", "fr", "hi", "ja", "ko", "pl", "pt-BR", "ru", "zh-Hans"];
  assert.deepEqual(
    shippedManifest.contributions.assets.paths.filter((path) => path.startsWith("locales/")),
    [],
  );
  assert.ok(shippedManifest.files.every((file) => !file.path.startsWith("locales/")));
  const packs = new Map();
  for (const locale of LOCALES) packs.set(locale, await readFile(join(packageRoot, `locales/${locale}.json`), "utf8"));
  assert.equal(assertRulesetLanguagePacks(shippedManifest, packs), 11);
  assert.equal(JSON.parse(packs.get("ar"))._meta.direction, "rtl");
  const preview = JSON.parse(await readFile(join(repoRoot, "catalog/preview/v3/catalog.json"), "utf8"));
  const listed = preview.packages.find((entry) => entry.manifest.id === shippedManifest.id);
  assert.deepEqual(Object.keys(listed.locales), LOCALES);
  for (const locale of LOCALES) {
    const pack = await readFile(
      join(repoRoot, "artifacts", rulesetLanguagePackName(shippedManifest.id, shippedManifest.version, locale)),
    );
    assert.equal(pack.toString("utf8"), packs.get(locale));
    assert.equal(listed.locales[locale].bytes, pack.byteLength);
    assert.equal(listed.locales[locale].sha256, createHash("sha256").update(pack).digest("hex"));
    assert.equal(listed.locales[locale].name, JSON.parse(packs.get(locale)).package.name);
    assert.equal(listed.locales[locale].description, JSON.parse(packs.get(locale)).package.description);
  }
  const at = (minor) => ({ ...shippedManifest, capabilityApi: { major: 1, minor } });
  assert.throws(() => assertRulesetLanguagePacks(at(810), packs), /capability API 1\.811/u);
  assert.throws(() => assertRulesetLanguagePacks(shippedManifest, new Map([["en", packs.get("de")]])), /English/u);
  assert.throws(
    () => assertRulesetLanguagePacks(shippedManifest, new Map([["fr", packs.get("de")]])),
    /_meta\.locale is not "fr"/u,
  );
  const embedded = {
    ...shippedManifest,
    contributions: { assets: { paths: [...shippedManifest.contributions.assets.paths, "locales/de.json"] } },
  };
  assert.throws(() => assertRulesetLanguagePacks(embedded, packs), /inside its ruleset file/u);
  assert.equal(assertRulesetLanguagePacks(at(806), new Map()), 0);
}
console.log("ruleset 0.439.0 eleven translations regression checks passed");

// 0.440.0 (Capability API 1.808): a carried weapon is drawn as it is used.
