// 0.441.0: each translated description says how to choose the ruleset once, at its end.
{
  for (const locale of ["ar", "de", "es", "fr", "hi", "ja", "ko", "pl", "pt-BR", "ru", "zh-Hans"]) {
    const text = JSON.parse(await readFile(join(packageRoot, `locales/${locale}.json`), "utf8")).package.description;
    assert.ok(text.includes("https://creativecommons.org/licenses/by/4.0/legalcode"), locale);
    const sentences = text.split(/(?<=[.。।])\s*/u).filter(Boolean);
    assert.equal(new Set(sentences).size, sentences.length, `${locale} repeats a sentence`);
  }
}
{
  const shown = new Set([parsedAsset.combat.languages.prefix]);
  const gather = (value) => {
    if (Array.isArray(value)) value.forEach(gather);
    else if (value && typeof value === "object")
      for (const [name, inner] of Object.entries(value)) {
        if (name === "valueLabels") Object.values(inner).forEach((label) => shown.add(label));
        else if (name === "tab" || name === "labels" || name === "suggestions")
          [inner].flat().forEach((label) => typeof label === "string" && shown.add(label));
        else gather(inner);
      }
  };
  gather(parsedAsset.sheet);
  assert.ok(shown.has("Features") && shown.has("1st level") && shown.has("Arctic"));
  for (const locale of ["ar", "de", "es", "fr", "hi", "ja", "ko", "pl", "pt-BR", "ru", "zh-Hans"]) {
    const strings = JSON.parse(await readFile(join(packageRoot, `locales/${locale}.json`), "utf8")).ruleset;
    assert.deepEqual(
      [...shown].filter((text) => !strings[text]?.trim()),
      [],
      `${locale} leaves sheet labels untranslated`,
    );
  }
}
{
  assert.equal(parsedAsset.sheet.version, 10);
  assert.deepEqual(parsedAsset.sheet.migrations[0].steps, [
    { setColumn: { list: "spells", where: { level: [0] }, column: "prepared", to: true } },
  ]);
  assert.equal(parsedAsset.sheet.migrations[0].from, 9);
  assert.deepEqual(
    parsedAsset.gm.sheetSummary.lists.map((one) => one.list),
    ["spells", "attacks", "features", "eldritch", "pact"],
  );
}
console.log(
  "ruleset 0.441.0 language packs, layout 10, the features summary and translated sheet labels regression checks passed",
);

// 0.442.0: every language pack's store-card name and description fits the Engine's caps.
{
  for (const locale of ["ar", "de", "es", "fr", "hi", "ja", "ko", "pl", "pt-BR", "ru", "zh-Hans"]) {
    const card = JSON.parse(await readFile(join(packageRoot, `locales/${locale}.json`), "utf8")).package;
    assert.ok(card.description.length <= 1900, `${locale} description is ${card.description.length}`);
    assert.ok(card.name.length >= 1 && card.name.length <= 120, `${locale} name`);
  }
  const { assertRulesetLanguagePacks } = await import("../ruleset-package-checks.mjs");
  const german = JSON.parse(await readFile(join(packageRoot, "locales/de.json"), "utf8"));
  const tooLong = new Map([
    [
      "de",
      JSON.stringify({
        ...german,
        package: { ...german.package, description: `${"x".repeat(200)} ${german.package.description}` },
      }),
    ],
  ]);
  assert.throws(() => assertRulesetLanguagePacks(shippedManifest, tooLong), /over the Engine's 2000/u);
  const noName = new Map([["de", JSON.stringify({ ...german, package: { ...german.package, name: "" } })]]);
  assert.throws(() => assertRulesetLanguagePacks(shippedManifest, noName), /store-card name/u);
}
console.log("ruleset 0.442.0 store descriptions within the Engine's cap regression checks passed");

// 0.443.0: Wild Shape leaves out the SRD's ten swarms.
{
  const creatures = JSON.parse(await readFile(join(packageRoot, "catalogs/creatures.json"), "utf8")).entries;
  const swarms = creatures
    .filter((one) => one.filters.swarm === "Swarm")
    .map((one) => one.id)
    .sort();
  assert.deepEqual(
    swarms,
    creatures
      .filter((one) => one.label.startsWith("Swarm of "))
      .map((one) => one.id)
      .sort(),
  );
  assert.equal(swarms.length, 10);
  assert.ok(
    parsedAsset.catalogs
      .find((one) => one.id === "creatures")
      .filters.some((one) => one.id === "swarm" && one.label === "Swarm"),
  );
  const features = JSON.parse(await readFile(join(packageRoot, "catalogs/features.json"), "utf8")).entries;
  const wild = features.find((one) => one.mechanics?.forms?.upTo?.at?.derived === "wild_shape_cr");
  assert.deepEqual(wild.mechanics.forms.from.notFilters, { swarm: ["Swarm"] });
}
console.log("ruleset 0.443.0 Wild Shape skips swarms regression checks passed");

// 0.444.0: Polymorph and Animal Shapes leave out the swarms too; Shapechange and True Polymorph do not.
{
  const spells = JSON.parse(await readFile(join(packageRoot, "catalogs/spells.json"), "utf8")).entries;
  const from = (id) => spells.find((one) => one.id === id).mechanics.forms.from;
  for (const id of ["polymorph", "polymorph-unwilling", "animal-shapes"])
    assert.deepEqual(from(id).notFilters, { swarm: ["Swarm"] }, id);
  assert.equal(from("true-polymorph").notFilters?.swarm, undefined);
  assert.deepEqual(from("shapechange").notFilters.type, ["Construct", "Undead"]);
}
console.log("ruleset 0.444.0 Polymorph and Animal Shapes skip swarms regression checks passed");

