// 0.446.0: True Polymorph and Shapechange leave out what a spell, item or ability makes.
{
  const creatures = JSON.parse(await readFile(join(packageRoot, "catalogs/creatures.json"), "utf8")).entries;
  const made = creatures.filter((one) => one.filters.origin === "Spell, item or ability").map((one) => one.id);
  assert.equal(made.length, 25);
  assert.ok(creatures.filter((one) => one.filters.type === "Object").every((one) => made.includes(one.id)));
  assert.ok(["illusory-double", "phantom-steed", "animated-object-medium"].every((id) => made.includes(id)));
  assert.ok(
    parsedAsset.catalogs
      .find((one) => one.id === "creatures")
      .filters.some((one) => one.id === "origin" && one.label === "Made by"),
  );
  const spells = JSON.parse(await readFile(join(packageRoot, "catalogs/spells.json"), "utf8")).entries;
  const from = (id) => spells.find((one) => one.id === id).mechanics.forms.from;
  for (const id of ["true-polymorph", "true-polymorph-unwilling"])
    assert.deepEqual(from(id).notFilters, { origin: ["Spell, item or ability"] }, id);
  assert.deepEqual(from("shapechange").notFilters, {
    type: ["Construct", "Undead"],
    origin: ["Spell, item or ability"],
  });
  assert.deepEqual(
    spells.find((one) => one.id === "true-polymorph-object-into-creature").mechanics.calls.from.notFilters,
    { origin: ["Spell, item or ability"] },
  );
}
console.log("ruleset 0.446.0 forms are creatures regression checks passed");

