// 0.448.0: +N ammunition adds its N to the attack roll (Capability API 1.812).
{
  const items = JSON.parse(await readFile(join(packageRoot, "catalogs/magic_items.json"), "utf8")).entries;
  const plusN = items.filter((one) => /^(arrow|bolt|bullet|needle)-[123]$/u.test(one.id));
  assert.equal(plusN.length, 12);
  for (const one of plusN) assert.equal(one.item.ammoRider.toHit, Number(one.id.slice(-1)), one.id);
  assert.ok(shippedManifest.capabilityApi.minor >= 812);
}
console.log("ruleset 0.448.0 magic ammunition to hit regression checks passed");

// 0.449.0: the made-up casters sit within 1 of their challenge's threat tier; the plain Arrow of Slaying
// points to a kind.
{
  const creatures = JSON.parse(await readFile(join(packageRoot, "catalogs/creatures.json"), "utf8")).entries;
  const casters = creatures.filter((one) => MADE_CASTER.test(one.id));
  assert.equal(casters.length, 35);
  for (const one of casters) {
    const tier = parsedAsset.combat.threat.tiers.find((row) => row.id === one.creature.tier);
    const numbers = evaluateSheet(parsedAsset, one.creature.sheet);
    assert.ok(Math.abs(one.creature.sheet.fields.ac - tier.defense) <= 1, one.id);
    assert.ok(Math.abs(numbers.derived("spell_attack") - tier.toHit) <= 1, one.id);
    assert.ok(Math.abs(numbers.derived("spell_save_dc") - tier.saveDifficulty) <= 1, one.id);
    assert.equal(one.creature.sheet.fields.spell_attack_extra, undefined, one.id);
  }
  const items = JSON.parse(await readFile(join(packageRoot, "catalogs/magic_items.json"), "utf8")).entries;
  const plain = items.find((one) => one.id === "arrow-of-slaying");
  assert.match(plain.summary, /Undead/u);
  assert.equal(plain.item.ammoRider, undefined);
}
console.log("ruleset 0.449.0 casters as strong as their challenge regression checks passed");

